function renderAlertsPanel(op) {
  const alerts = computeAlerts(op);
  if (alerts.length === 0) return '';
  const isOpen = !!alertsPanelOpen[op._uid];
  const hasUrgent = alerts.some(a => a.level === 'expired' || a.level === 'critical');
  const headerClass = hasUrgent ? 'alerts-panel-critical' : 'alerts-panel-warning';
  // Group counts by level
  const expired = alerts.filter(a => a.level === 'expired').length;
  const critical = alerts.filter(a => a.level === 'critical').length;
  const warning = alerts.filter(a => a.level === 'warning').length;
  const info = alerts.filter(a => a.level === 'info').length;
  const summary = [
    expired > 0 ? `<span class="alert-pill alert-pill-expired">${expired} dépassée${expired > 1 ? 's' : ''}</span>` : '',
    critical > 0 ? `<span class="alert-pill alert-pill-critical">${critical} critique${critical > 1 ? 's' : ''}</span>` : '',
    warning > 0 ? `<span class="alert-pill alert-pill-warning">${warning} à surveiller</span>` : '',
    info > 0 ? `<span class="alert-pill alert-pill-info">${info} à anticiper</span>` : '',
  ].filter(Boolean).join('');
  return `
    <div class="alerts-panel ${headerClass}">
      <button class="alerts-panel-head" onclick="toggleAlertsPanel('${escapeHtml(op._uid)}')" type="button">
        <i class="ti ti-clock"></i>
        <span class="alerts-panel-count"><strong>${alerts.length}</strong> échéance${alerts.length > 1 ? 's' : ''} à surveiller</span>
        <span class="alerts-panel-summary">${summary}</span>
        <i class="ti ti-chevron-${isOpen ? 'up' : 'down'}"></i>
      </button>
      ${isOpen ? `
        <ul class="alerts-panel-list">
          ${alerts.map(a => `<li class="alert-item alert-${a.level}">
            <span class="alert-days">${a.days < 0 ? `${-a.days}j ⚠` : `${a.days}j`}</span>
            <span class="alert-msg">${escapeHtml(a.msg)}</span>
          </li>`).join('')}
        </ul>
      ` : ''}
    </div>
  `;
}
