function bilanTotal(t) {
  return BILAN_SECTIONS.reduce((s, sec) => s + bilanSectionTotal(t, sec.key), 0);
}
// Op-level: sum surfaces from all tranches. Returns null if nothing saved.
function opTotalSurface(op) {
  if (!op?.tranches?.length) return null;
  let total = 0;
  let hasAny = false;
  (op.tranches || []).forEach(t => {
    if (t.surfaces) {
      for (const v of Object.values(t.surfaces)) {
        const n = Number(v);
        if (!isNaN(n) && n !== 0) { total += n; hasAny = true; }
      }
    }
    // Also accept a m2 / m2_utiles scalar field on the tranche
    if (!hasAny) {
      const m2 = Number(t.m2_utiles ?? t.m2);
      if (!isNaN(m2) && m2 !== 0) { total += m2; hasAny = true; }
    }
  });
  return hasAny ? total : null;
}
// Op-level: sum of all tranches' bilan totals
function opBilanTotal(op) {
  return (op.tranches || []).reduce((s, t) => s + bilanTotal(t), 0);
}
// Op-level: sum of all tranches' section totals
function opBilanSectionTotal(op, sectionKey) {
  return (op.tranches || []).reduce((s, t) => s + bilanSectionTotal(t, sectionKey), 0);
}
// Op-level: sum of a specific line across all tranches
function opBilanLineTotal(op, sectionKey, lineName) {
  return (op.tranches || []).reduce((s, t) => {
    const v = t.bilan && t.bilan[sectionKey] && t.bilan[sectionKey][lineName];
    return s + (Number(v) || 0);
  }, 0);
}
