// ============== PERSISTANCE (localStorage) ==============
// Helpers safe : essaient localStorage, retombent silencieusement si indisponible (mode privé, etc.)
const STORAGE_PREFIX = 'exnihilo:';
function storageGet(key) {
  try { return localStorage.getItem(STORAGE_PREFIX + key); }
  catch (e) { return null; }
}
function storageSet(key, value) {
  try {
    if (value === null || value === undefined) localStorage.removeItem(STORAGE_PREFIX + key);
    else localStorage.setItem(STORAGE_PREFIX + key, String(value));
  } catch (e) { /* swallow */ }
}

let selectedOpCode = DATA[0]?._uid || null;
let selectedTrancheIdx = 0;
let editMode = false;
let AAPS = [];
let editingAapLid = null;
let comitesCalMonth = null;
