// Returns the comparison reference snapshot (or null)
function getCompareSnapshot(op) {
  if (compareWithIdx == null) return null;
  return op.phases_history[compareWithIdx] || null;
}

// For comparison: get reference value of a field from a snapshot
function getRefValue(op, field) {
  if (compareWithIdx == null) return null;
  const snap = getCompareSnapshot(op);
  if (!snap) return null;
  return snap.snapshot[field];
}
function getRefTrancheValue(op, trancheIdx, field) {
  if (compareWithIdx == null) return null;
  const snap = getCompareSnapshot(op);
  if (!snap || !snap.snapshot.tranches) return null;
  const refTranche = snap.snapshot.tranches[trancheIdx];
  if (!refTranche) return null;
  return refTranche[field];
}

