// Get all unique tags across all ops, alphabetically sorted
function getAllTags() {
  const tags = new Set();
  DATA.forEach(op => {
    if (Array.isArray(op.tags)) op.tags.forEach(t => { if (t) tags.add(t); });
  });
  return [...tags].sort((a, b) => a.localeCompare(b, 'fr'));
}

// Get ops sharing at least one tag with the given op (excluding itself)
function getLinkedOps(op) {
  if (!Array.isArray(op.tags) || op.tags.length === 0) return [];
  return DATA.filter(o =>
    o._uid !== op._uid
    && Array.isArray(o.tags)
    && o.tags.some(t => op.tags.includes(t))
  );
}

// Render tags pills (in read or edit mode)
function renderOpTags(op, isEditMode) {
  const tags = Array.isArray(op.tags) ? op.tags : [];
  if (!isEditMode && tags.length === 0) return '';
  const tagsHtml = tags.map((t, i) => {
    const safeTag = escapeHtml(t);
    if (isEditMode) {
      return `<span class="op-tag op-tag-editing" data-tag-idx="${i}">
        <i class="ti ti-tag"></i>${safeTag}
        <button class="op-tag-remove" data-tag-action="remove" data-tag-idx="${i}" title="Retirer ce tag" type="button">×</button>
      </span>`;
    }
    return `<span class="op-tag" data-tag-action="show-linked" data-tag-value="${safeTag}" title="Voir les opérations liées par ce tag">
      <i class="ti ti-tag"></i>${safeTag}
    </span>`;
  }).join('');
  // "+ Ajouter" always available in edit mode (multi-tags)
  const addInput = isEditMode ? `
    <span class="op-tag-add">
      <input type="text" id="opTagInput" placeholder="+ Ajouter un tag…" autocomplete="off" list="opTagsDatalist" />
      <datalist id="opTagsDatalist">
        ${getAllTags().filter(t => !tags.some(existing => existing.toLowerCase() === t.toLowerCase())).map(t => `<option value="${escapeHtml(t)}">`).join('')}
      </datalist>
    </span>
  ` : '';
  return `<span class="op-tags-wrap">${tagsHtml}${addInput}</span>`;
}
