async function createOp() {
  const msg = ["Créer une nouvelle opération.", "", "Entrez son nom (vous pourrez le modifier ensuite) :"].join('\n');
  const name = prompt(msg, "Nouvelle opération");
  if (name === null) return; // Cancel
  const trimmed = (name || '').trim();
  if (!trimmed) {
    showToast('Création annulée : nom vide', 'alert-circle');
    return;
  }
  const newOp = makeNewOp();
  newOp.display_name = trimmed;
  // Insertion immédiate dans Supabase pour obtenir un id persistant
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/operations`, {
      method: 'POST',
      headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}`, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
      body: JSON.stringify({ code: newOp.code, display_name: newOp.display_name, phase_actuelle: newOp.phase_actuelle })
    });
    if (!res.ok) throw new Error(await res.text());
    const rows = await res.json();
    const id = rows && rows[0] && rows[0].id;
    if (id) { newOp._supabase_id = id; newOp._uid = 'op-supabase-' + id; }
  } catch (e) {
    console.error('Création Supabase échouée:', e);
    showToast('Opération créée localement, mais non enregistrée dans Supabase', 'alert-triangle');
  }
  DATA.push(newOp);
  selectedOpCode = newOp._uid;
  selectedTrancheIdx = 0;
  editMode = true;
  searchQuery = ''; // Clear search so the new op is visible
  const searchInput = document.getElementById('sidebarSearch');
  if (searchInput) searchInput.value = '';
  renderAll();
  if (newOp._supabase_id) saveOpToSupabase(newOp); // persiste les valeurs par défaut
  showToast(`Opération « ${trimmed} » créée — pensez à lui attribuer un code analytique`, 'plus');
}

function deleteOp() {
  // Soft delete: move to trash instead of removing
  softDeleteOp();
}

function createTranche() {
  const op = findOp(selectedOpCode);
  if (!op) return;
  // Find next integer id
  const ids = op.tranches
    .map(t => parseInt(String(t.id || '').match(/^\d+/)?.[0] || '0', 10))
    .filter(n => !isNaN(n));
  const nextId = ids.length > 0 ? Math.max(...ids) + 1 : 1;
  op.tranches.push(makeNewTranche(op.code, String(nextId)));
  selectedTrancheIdx = op.tranches.length - 1;
  editMode = true;
  renderAll();
  showToast('Tranche créée', 'plus');
}

// ============== BILAN PR/PF — APERÇU & PDF ==============
// Aide : trouve dans un objet bilan (clé=nom poste, valeur=montant) les postes contenant un mot-clé
function _bilanMatchSum(section, keywords) {
  if (!section || typeof section !== 'object') return { total: 0, keys: [] };
  const matched = [];
  let total = 0;
  Object.entries(section).forEach(([k, v]) => {
    const kl = String(k).toLowerCase();
    if (keywords.some(kw => kl.includes(kw.toLowerCase()))) {
      matched.push(k);
      const n = Number(v);
      if (!isNaN(n)) total += n;
    }
  });
  return { total, keys: matched };
}
function _bilanSumOther(section, excludeKeys) {
  if (!section || typeof section !== 'object') return 0;
  let total = 0;
  Object.entries(section).forEach(([k, v]) => {
    if (excludeKeys.includes(k)) return;
    const n = Number(v); if (!isNaN(n)) total += n;
  });
  return total;
}
function _bilanSumSection(section) {
  if (!section || typeof section !== 'object') return 0;
  return Object.values(section).reduce((s, v) => s + (Number(v) || 0), 0);
}
function _bilanSumPrets(prets, kws, excludeKws = []) {
  let t = 0;
  (prets || []).forEach(p => {
    const ligne = String(p.ligne || '').toLowerCase();
    const matches = kws.some(kw => ligne.includes(kw.toLowerCase()));
    const excl = excludeKws.some(kw => ligne.includes(kw.toLowerCase()));
    if (matches && !excl) {
      const amt = Number(p.montant_contrat) || Number(p.montant_lo) || Number(p.montant_sim) || 0;
      t += amt;
    }
  });
  return t;
}
function _bilanFmt(v) {
  if (!v || isNaN(v)) return '—';
  return Math.round(v).toLocaleString('fr-FR') + ' €';
}
function _bilanFmtPct(v, total) {
  if (!total || total === 0) return '—';
  const p = (v / total) * 100;
  return p.toFixed(1).replace('.', ',') + ' %';
}

// Agrège les données du bilan pour une liste de tranches sélectionnées (somme des postes)
function _bilanAggregateData(op, tranches) {
  const types = new Set(), gestionnaires = new Set(), refs = new Set();
  const addToMap = (map, obj) => {
    if (!obj || typeof obj !== 'object') return;
    Object.entries(obj).forEach(([k, v]) => {
      const n = Number(v); if (isNaN(n)) return;
      map.set(k, (map.get(k) || 0) + n);
    });
  };
  const cfMap = new Map(), batMap = new Map(), honMap = new Map();
  const recMap = new Map();
  let fp = 0;

  tranches.forEach(t => {
    const bl = t.bilan || {};
    addToMap(cfMap, bl.charge_fonciere || t.charge_fonciere);
    addToMap(batMap, bl.batiment || t.batiment);
    addToMap(batMap, bl.frais_divers || t.frais_divers);
    addToMap(honMap, bl.honoraires || t.honoraires);
    addToMap(honMap, bl.frais_financiers || t.frais_financiers);

    const trCode = t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id;
    (op.prets || []).filter(p => p.tranche === trCode).forEach(p => {
      const label = (p.ligne || 'Prêt') + (p.financeur ? ' · ' + p.financeur : '');
      const amt = Number(p.montant_contrat) || Number(p.montant_lo) || Number(p.montant_sim) || 0;
      if (amt) { const k = 'P:' + label; recMap.set(k, { label, montant: (recMap.get(k)?.montant || 0) + amt }); }
    });
    (op.subventions || []).filter(s => s.tranche === trCode).forEach(s => {
      const label = s.financement || ('Subvention ' + (s.financeur || '')).trim();
      const amt = Number(s.montant_notifie) || Number(s.montant_demande) || 0;
      if (amt) { const k = 'S:' + label; recMap.set(k, { label, montant: (recMap.get(k)?.montant || 0) + amt }); }
    });
    fp += Number(t.fonds_propres) || 0;

    if (t.type_structure) types.add(t.type_structure);
    if (t.gestionnaire) gestionnaires.add(t.gestionnaire);
    const ref = t.n_leon || t.n_siap; if (ref) refs.add(ref);
  });

  const mapToLines = m => [...m.entries()].map(([label, montant]) => ({ label, montant }));
  const sum = lines => lines.reduce((s, l) => s + l.montant, 0);
  const cfLines = mapToLines(cfMap), batLines = mapToLines(batMap), honLines = mapToLines(honMap);
  const blocks = [
    { title: 'CHARGE FONCIÈRE', totalLabel: 'TOTAL CHARGE FONCIÈRE', depLabel: 'Charge Foncière', lines: cfLines, total: sum(cfLines) },
    { title: 'BÂTIMENT / TRAVAUX', totalLabel: 'TOTAL BÂTIMENT', depLabel: 'Bâtiment / Travaux', lines: batLines, total: sum(batLines) },
    { title: 'HONORAIRES', totalLabel: 'TOTAL HONORAIRES', depLabel: 'Honoraires', lines: honLines, total: sum(honLines) },
  ].filter(b => b.lines.length || b.total);

  const totalPR = blocks.reduce((s, b) => s + b.total, 0);
  const depenses = blocks.map(b => ({ label: b.depLabel, montant: b.total }));
  const totalDep = totalPR;
  const recettes = [...recMap.values()].map(r => ({ label: r.label, montant: r.montant }));
  if (fp) recettes.push({ label: 'Fonds propres', montant: fp });
  const totalRec = recettes.reduce((s, l) => s + l.montant, 0);
  const equilibre = totalRec - totalDep;

  return { blocks, totalPR, depenses, totalDep, recettes, totalRec, equilibre,
    types: [...types], gestionnaires: [...gestionnaires], refs: [...refs] };
}

// Génère le HTML de la page bilan dans le conteneur #bilan-print-page
function _bilanRenderPage(op, tranchesSelected) {
  const d = _bilanAggregateData(op, tranchesSelected);
  const today = new Date();
  const dateStr = `${String(today.getDate()).padStart(2,'0')}/${String(today.getMonth()+1).padStart(2,'0')}/${today.getFullYear()}`;

  const depMatch = (op.departement || '').match(/\((\d+)\)/);
  const depCode = depMatch ? depMatch[1] : '';
  const programme = `${(op.commune || '').toUpperCase()}${depCode ? ' (' + depCode + ')' : ''}`;
  const typeProduit = d.types.join(' / ') || '—';
  const gestionnaireStr = d.gestionnaires.join(' / ') || '—';
  const refsStr = d.refs.join(' / ') || '—';

  const trancheLabels = tranchesSelected.map(t => {
    const tc = t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id;
    return `${tc}${t.financement ? ' (' + t.financement + ')' : ''}`;
  });
  const sousTitre = d.types.join(', ') || 'Bilan prévisionnel d\'opération';

  const logoEl = document.querySelector('.topnav-brand-logo');
  const logoSrc = logoEl ? logoEl.src : '';

  const multiTranche = tranchesSelected.length > 1;
  const legendHtml = multiTranche
    ? `<div class="bilan-tranches-legend"><strong>Périmètre :</strong> bilan consolidé de ${tranchesSelected.length} tranches (${escapeHtml(trancheLabels.join(', '))}). Les montants correspondent à la somme des postes de chaque tranche.</div>`
    : '';

  const bandeau = title => `<div class="bilan-section-header"><span>${title}</span><span class="bsh-cols"><span class="bsh-m">Montants TTC (€)</span><span class="bsh-p">%</span></span></div>`;
  const lineRow = (label, montant, base) => `<tr><td class="bilan-libelle-indent">${escapeHtml(label)}</td><td class="bilan-montant">${_bilanFmt(montant)}</td><td class="bilan-pct">${_bilanFmtPct(montant, base)}</td></tr>`;
  const subtotalRow = (label, montant) => `<tr class="bilan-subtotal"><td class="bilan-libelle">${escapeHtml(label)}</td><td class="bilan-montant">${_bilanFmt(montant)}</td><td class="bilan-pct">100,0 %</td></tr>`;

  const blocksHtml = d.blocks.map(b => `
    <div class="bilan-subsection-header">${escapeHtml(b.title)}</div>
    <table class="bilan-table">
      ${b.lines.map(l => lineRow(l.label, l.montant, b.total)).join('')}
      ${subtotalRow(b.totalLabel, b.total)}
    </table>`).join('');

  const depRows = d.depenses.map(l => lineRow(l.label, l.montant, d.totalDep)).join('');
  const recRows = d.recettes.map(l => lineRow(l.label, l.montant, d.totalRec)).join('');

  const equilibreOk = Math.abs(d.equilibre) < 1;
  const equilibreVal = (d.equilibre > 0 ? '+' : '') + (equilibreOk ? '0 €' : _bilanFmt(d.equilibre));

  return `
    <div class="bilan-header">
      <div class="bilan-title-block">
        <h1 class="bilan-title">BILAN PRÉVISIONNEL D'OPÉRATION</h1>
        <p class="bilan-subtitle">${escapeHtml(sousTitre)}</p>
      </div>
      ${logoSrc ? `<img src="${logoSrc}" alt="AXENTIA" class="bilan-logo">` : ''}
    </div>
    <div class="bilan-date-block">Date : <b>${dateStr}</b></div>
    ${legendHtml}

    <div class="bilan-section-header"><span>IDENTIFICATION DE L'OPÉRATION</span></div>
    <div class="bilan-id-grid">
      <div class="bik">Programme</div><div class="biv">${escapeHtml(programme || '—')}</div>
      <div class="bik">Gestionnaire</div><div class="biv">${escapeHtml(gestionnaireStr)}</div>
      <div class="bik">Type de produit</div><div class="biv">${escapeHtml(typeProduit)}</div>
      <div class="bik">Référence</div><div class="biv">${escapeHtml(refsStr)}</div>
    </div>

    ${bandeau('PRIX DE REVIENT PRÉVISIONNEL')}
    ${blocksHtml}
    <table class="bilan-table">
      <tr class="bilan-total-gold"><td>PRIX DE REVIENT OPÉRATION</td><td class="bilan-montant">${_bilanFmt(d.totalPR)}</td><td class="bilan-pct">100,0 %</td></tr>
    </table>

    ${bandeau('PLAN DE FINANCEMENT PRÉVISIONNEL')}
    <div class="bilan-subsection-header">I — DÉPENSES</div>
    <table class="bilan-table">
      ${depRows}
      <tr class="bilan-total-navy"><td>TOTAL DÉPENSES</td><td class="bilan-montant">${_bilanFmt(d.totalDep)}</td><td class="bilan-pct">100,0 %</td></tr>
    </table>
    <div class="bilan-subsection-header">II — RECETTES</div>
    <table class="bilan-table">
      ${recRows}
      <tr class="bilan-total-navy"><td>TOTAL FINANCEMENT</td><td class="bilan-montant">${_bilanFmt(d.totalRec)}</td><td class="bilan-pct">100,0 %</td></tr>
    </table>

    <div class="bilan-equilibre ${equilibreOk ? 'bilan-equilibre-ok' : 'bilan-equilibre-ko'}">ÉQUILIBRE&nbsp;&nbsp;—&nbsp;&nbsp;Écart (Recettes − Dépenses) : ${escapeHtml(equilibreVal)}</div>
    <div class="bilan-footer">Document confidentiel — Bilan prévisionnel d'opération · AXENTIA</div>
  `;
}

// Modal de sélection des tranches (avec checkboxes)
function _bilanOpenTranchesModal(op, defaultIdx, onConfirm) {
  document.querySelectorAll('.bilan-tranches-modal-backdrop').forEach(p => p.remove());
  const tranches = op.tranches || [];
  if (tranches.length === 0) {
    showToast('Aucune tranche disponible', 'alert-triangle');
    return;
  }
  // Si une seule tranche, on bypasse le modal
  if (tranches.length === 1) {
    onConfirm([0]);
    return;
  }

  const backdrop = document.createElement('div');
  backdrop.className = 'bilan-tranches-modal-backdrop';
  backdrop.innerHTML = `
    <div class="bilan-tranches-modal">
      <div class="bilan-tranches-modal-head">
        <span>Sélectionner les tranches à inclure</span>
        <button class="bilan-tranches-modal-close" type="button">×</button>
      </div>
      <div class="bilan-tranches-modal-body">
        <p class="helper">Cochez une ou plusieurs tranches. Le bilan consolide les postes (somme) sur les tranches sélectionnées.</p>
        ${tranches.map((t, i) => {
          const tc = t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id;
          const label = `${tc} — ${escapeHtml(t.type_structure || '?')}${t.financement ? ' (' + escapeHtml(t.financement) + ')' : ''}`;
          const meta = `${trancheLogements(t) || '?'} logements · ${t.gestionnaire || 'sans gestionnaire'}`;
          return `
            <label class="bilan-tranche-check">
              <input type="checkbox" data-tranche-idx="${i}" ${i === defaultIdx ? 'checked' : ''}>
              <div class="bilan-tranche-check-info">
                <div class="bilan-tranche-check-name">${label}</div>
                <div class="bilan-tranche-check-meta">${escapeHtml(meta)}</div>
              </div>
            </label>
          `;
        }).join('')}
      </div>
      <div class="bilan-tranches-modal-foot">
        <span class="selection-count" id="bilan-sel-count">1 tranche sélectionnée</span>
        <div style="display:flex; gap:8px;">
          <button type="button" class="cancel-btn">Annuler</button>
          <button type="button" class="primary confirm-btn">Continuer</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  replaceTablerIcons();

  const updateCount = () => {
    const n = backdrop.querySelectorAll('input[type="checkbox"]:checked').length;
    backdrop.querySelector('#bilan-sel-count').textContent = `${n} tranche${n > 1 ? 's' : ''} sélectionnée${n > 1 ? 's' : ''}`;
  };
  backdrop.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', updateCount);
  });
  const close = () => backdrop.remove();
  backdrop.querySelector('.bilan-tranches-modal-close').addEventListener('click', close);
  backdrop.querySelector('.cancel-btn').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.confirm-btn').addEventListener('click', () => {
    const idxs = [...backdrop.querySelectorAll('input[type="checkbox"]:checked')]
      .map(cb => parseInt(cb.dataset.trancheIdx, 10))
      .filter(n => !isNaN(n));
    if (idxs.length === 0) {
      showToast('Sélectionnez au moins une tranche', 'alert-triangle');
      return;
    }
    close();
    onConfirm(idxs);
  });
}

// Affiche l'aperçu (avec toolbar) sans imprimer
function openBilanPreview() {
  const op = findOp(selectedOpCode);
  if (!op) { showToast('Aucune opération sélectionnée', 'alert-triangle'); return; }
  _bilanOpenTranchesModal(op, selectedTrancheIdx, (idxs) => {
    const tranches = idxs.map(i => op.tranches[i]).filter(Boolean);
    const html = _bilanRenderPage(op, tranches);
    document.getElementById('bilan-print-page').innerHTML = html;
    document.getElementById('bilan-preview-overlay').style.display = 'flex';
    replaceTablerIcons();
  });
}

// Ouvre directement l'aperçu PUIS lance l'impression (parcours rapide)
function openBilanPrint() {
  const op = findOp(selectedOpCode);
  if (!op) { showToast('Aucune opération sélectionnée', 'alert-triangle'); return; }
  _bilanOpenTranchesModal(op, selectedTrancheIdx, (idxs) => {
    const tranches = idxs.map(i => op.tranches[i]).filter(Boolean);
    const html = _bilanRenderPage(op, tranches);
    document.getElementById('bilan-print-page').innerHTML = html;
    document.getElementById('bilan-preview-overlay').style.display = 'flex';
    replaceTablerIcons();
    // Léger délai pour laisser le DOM se rendre + les icônes Tabler se charger
    setTimeout(() => { window.print(); }, 200);
  });
}

// Lance l'impression depuis le bouton dans la toolbar de l'aperçu
function triggerBilanPrint() {
  window.print();
}

// Ferme l'overlay d'aperçu
function closeBilanPreview() {
  document.getElementById('bilan-preview-overlay').style.display = 'none';
  document.getElementById('bilan-print-page').innerHTML = '';
}
// ============== END BILAN PR/PF ==============

function deleteTranche() {
  const op = findOp(selectedOpCode);
  if (!op) return;
  const t = op.tranches[selectedTrancheIdx];
  if (!t) return;
  if (!confirm(`Supprimer la tranche « ${t.type_structure || t.id} » ?

Les prêts, subventions, garanties, etc. liés à cette tranche resteront en base mais ne seront plus affichés tant qu'aucune tranche n'a leur code.`)) return;
  op.tranches.splice(selectedTrancheIdx, 1);
  selectedTrancheIdx = Math.max(0, Math.min(selectedTrancheIdx, op.tranches.length - 1));
  renderAll();
  showToast('Tranche supprimée', 'trash');
}

function abbrevName(name) {
  if (!name) return '';
  const parts = String(name).trim().split(/\s+/);
  if (parts.length === 1) return parts[0];
  const first = parts[0];
  const initials = parts.slice(1).map(p => p[0] || '').join('').toUpperCase();
  return initials ? `${first} ${initials}.` : first;
}

function escapeHtml(s) {
  if (s == null) return '';
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function dash(v) { return (v === null || v === undefined || v === '') ? '<span class="kv-value-empty">—</span>' : escapeHtml(v); }
function dashNum(v) { return (v === null || v === undefined || v === 0) ? '<span class="muted">—</span>' : v; }

// Returns the reference (snapshot) value for a given field & scope, or null if not in compare mode
function getFieldRef(field, scope) {
  if (compareWithIdx == null) return null;
  const op = findOp(selectedOpCode);
  if (!op) return null;
  if (scope === 'tranche-field') return getRefTrancheValue(op, selectedTrancheIdx, field);
  return getRefValue(op, field);
}

// Field formatter: which fields are monetary, which are dates, etc.
const MONETARY_FIELDS = new Set(['budget_ttc','pret_bati','pret_foncier','subv_total','fonds_propres','montant_redevance','montant_sim','montant_lo','montant_contrat','montant_demande','montant_notifie','montant_couvert','montant_tire']);
function formatRefValue(field, val) {
  if (val == null || val === '') return '—';
  if (MONETARY_FIELDS.has(field)) return fmtMontant(val);
  return String(val);
}

// Wrap a display HTML with diff highlight if refValue differs from currentValue
function diffifyKV(displayedHtml, currentValue, field, scope) {
  // No comparison active → never show any diff marker
  if (compareWithIdx == null) return displayedHtml;
  const refValue = getFieldRef(field, scope);
  if (refValue == null && (currentValue == null || currentValue === '')) return displayedHtml;
  // Normalize: null, undefined, '', false → all equivalent
  const a = normalizeForCompare(currentValue);
  const b = normalizeForCompare(refValue);
  if (JSON.stringify(a) === JSON.stringify(b)) return displayedHtml;
  const refStr = formatRefValue(field, refValue);
  return `<span class="diff-changed" title="Avant : ${escapeHtml(refStr)}">${displayedHtml}<span class="diff-mark">≠</span></span>`;
}

// Edit-mode helpers: render either a span (read) or an input (edit)
// scope: 'op-field' (default) or 'tranche-field'
function editableKV(label, value, field, type='text', scope='op-field') {
  if (editMode) {
    // Détection automatique du type pour validation
    let validateType = '';
    if (field && (field.startsWith('date_') || field.endsWith('_date') || field.includes('_date_'))) {
      validateType = 'date-fr';
    } else if (type === 'number') {
      validateType = 'number';
    }
    const validateAttr = validateType ? ` data-validate="${validateType}"` : '';
    const placeholder = validateType === 'date-fr' ? ' placeholder="JJ/MM/AAAA"' : '';
    return `<div class="kv-row">
      <span class="kv-key">${label}</span>
      <input type="${type}" class="editable-input" data-edit-${scope}="${field}" value="${escapeHtml(value == null ? '' : value)}"${validateAttr}${placeholder}>
    </div>`;
  }
  const displayed = diffifyKV(dash(value), value, field, scope);
  return `<div class="kv-row"><span class="kv-key">${label}</span><span class="kv-value">${displayed}</span></div>`;
}

// Bascule visuelle prévu/réel côté client (lue à l'enregistrement) — édition uniquement
function flipJalonPill(el) {
  const isReel = el.classList.toggle('reel');
  el.classList.toggle('prev', !isReel);
  const icon = el.querySelector('i'); if (icon) icon.className = 'ti ti-' + (isReel ? 'check' : 'clock');
  const txt = el.querySelector('.jalon-pill-txt'); if (txt) txt.textContent = isReel ? 'réel' : 'prév.';
}

// Ligne date d'opération avec pastille prévu/réel (cliquable en mode modif seulement)
function editableDateJalon(label, value, field, op) {
  const reel = !!(op && op.jalons_reel && op.jalons_reel[field]);
  const hasVal = value != null && value !== '';
  const cls = reel ? 'reel' : 'prev', icon = reel ? 'check' : 'clock', txt = reel ? 'réel' : 'prév.';
  if (editMode) {
    const pill = `<span class="jalon-pill ${cls}" data-jalon-reel="${field}" onclick="flipJalonPill(this)" title="Basculer prévu / réel"><i class="ti ti-${icon}" aria-hidden="true"></i><span class="jalon-pill-txt">${txt}</span></span>`;
    return `<div class="kv-row">
      <span class="kv-key">${label}</span>
      <span style="display:flex;align-items:center;gap:8px;min-width:0;">
        <input type="text" class="editable-input" style="flex:1;min-width:0;" data-edit-op-field="${field}" value="${escapeHtml(value == null ? '' : value)}" data-validate="date-fr" placeholder="JJ/MM/AAAA">
        ${pill}
      </span>
    </div>`;
  }
  const pill = hasVal ? `<span class="jalon-pill ${cls}" style="cursor:default;"><i class="ti ti-${icon}" aria-hidden="true"></i><span class="jalon-pill-txt">${txt}</span></span>` : '';
  const displayed = diffifyKV(dash(value), value, field, 'op-field');
  return `<div class="kv-row"><span class="kv-key">${label}</span><span class="kv-value" style="display:flex;align-items:center;gap:8px;">${displayed}${pill}</span></div>`;
}

function editableSelect(label, value, field, options, scope='op-field') {
  if (editMode) {
    const opts = options.map(o => `<option value="${escapeHtml(o)}"${o === value ? ' selected' : ''}>${escapeHtml(o)}</option>`).join('');
    return `<div class="kv-row">
      <span class="kv-key">${label}</span>
      <select class="editable-select" data-edit-${scope}="${field}"><option value=""></option>${opts}</select>
    </div>`;
  }
  const displayed = diffifyKV(dash(value), value, field, scope);
  return `<div class="kv-row"><span class="kv-key">${label}</span><span class="kv-value">${displayed}</span></div>`;
}
function editableNotes(value, field, scope, placeholder) {
  if (editMode) {
    const attr = scope === 'tranche-field' ? 'data-edit-tranche-field' : 'data-edit-op-field';
    const ph = placeholder || 'Notes libres…';
    return `<textarea class="editable-textarea" ${attr}="${field}" placeholder="${escapeHtml(ph)}">${escapeHtml(value || '')}</textarea>`;
  }
  // Diff-aware notes block
  const realScope = scope === 'tranche-field' ? 'tranche-field' : 'op-field';
  const refValue = getFieldRef(field, realScope);
  const isDifferent = refValue != null && String(refValue || '') !== String(value || '');
  if (!value) {
    if (isDifferent) {
      return `<div class="notes-block notes-block-empty diff-changed" title="Avant : ${escapeHtml(String(refValue))}">—<span class="diff-mark">≠</span></div>`;
    }
    return '<div class="notes-block notes-block-empty">—</div>';
  }
  if (isDifferent) {
    return `<div class="notes-block diff-changed" title="Avant : ${escapeHtml(String(refValue))}">${escapeHtml(value)}<span class="diff-mark">≠</span></div>`;
  }
  return `<div class="notes-block">${escapeHtml(value)}</div>`;
}
function editableVolCell(key, value, t) {
  const label = key.toUpperCase();
  // Get surface from t.surfaces[key] if available
  const surface = (t && t.surfaces && t.surfaces[key]) || null;
  if (editMode) {
    return `<div class="vol-cell vol-cell-edit"><div class="vol-cell-label">${label}</div>
      <div class="vol-cell-edit-row">
        <input type="number" min="0" class="editable-input vol-cell-input" data-edit-tranche-vol="${key}" value="${value || ''}" placeholder="lgts" title="Nombre de logements">
        <span class="vol-cell-edit-unit">lgts</span>
      </div>
      <div class="vol-cell-edit-row">
        <input type="number" min="0" step="0.01" class="editable-input vol-cell-input" data-edit-tranche-surface="${key}" value="${surface || ''}" placeholder="m²" title="Surface utile m²">
        <span class="vol-cell-edit-unit">m²</span>
      </div>
    </div>`;
  }
  // Diff: compare with snapshot tranche vol[key]
  let refValue = null;
  if (compareWithIdx != null) {
    const op = findOp(selectedOpCode);
    if (op) {
      const snap = getCompareSnapshot(op);
      if (snap && snap.snapshot.tranches && snap.snapshot.tranches[selectedTrancheIdx]) {
        refValue = snap.snapshot.tranches[selectedTrancheIdx].vol?.[key];
      }
    }
  }
  const isDifferent = refValue != null && Number(refValue) !== Number(value || 0);
  const displayedVal = value || '—';
  const surfaceLine = surface ? `<div class="vol-cell-surface">${fmtSurface(surface)}</div>` : (value ? '<div class="vol-cell-surface vol-cell-surface-empty">— m²</div>' : '');
  if (isDifferent) {
    return `<div class="vol-cell${value ? '' : ' vol-cell-empty'}"><div class="vol-cell-label">${label}</div><div class="vol-cell-value diff-changed" title="Avant : ${refValue}">${displayedVal}<span class="diff-mark">${Number(value || 0) > Number(refValue) ? '↑' : '↓'}</span></div>${surfaceLine}</div>`;
  }
  return `<div class="vol-cell${value ? '' : ' vol-cell-empty'}"><div class="vol-cell-label">${label}</div><div class="vol-cell-value">${displayedVal}</div>${surfaceLine}</div>`;
}

// JS formatters (mirror Python ones, used at render time)
function fmtMontant(v) {
  if (v === null || v === undefined || v === 0 || v === '') return '—';
  const n = Number(v);
  if (isNaN(n)) return '—';
  const k = Math.round(n / 1000);
  return k.toLocaleString('fr-FR').replace(/ /g, ' ').replace(/,/g, ' ') + ' k€';
}
function fmtEuros(v) {
  if (v === null || v === undefined || v === '') return '—';
  const n = Number(v);
  if (isNaN(n)) return '—';
  const rounded = Math.round(n);
  return rounded.toLocaleString('fr-FR').replace(/ /g, ' ').replace(/,/g, ' ') + ' €';
}
function fmtSurface(v) {
  if (v === null || v === undefined || v === 0) return '—';
  const n = Number(v);
  if (isNaN(n)) return '—';
  return Math.round(n).toLocaleString('fr-FR').replace(/,/g, ' ') + ' m²';
}

// On-the-fly totals (recompute when tranches change)
// Règle : champ stocké directement sur la tranche (saisie utilisateur).
// Au niveau op, on somme ce qui est saisi sur les tranches. Si AUCUNE tranche
// n'a la valeur saisie (toutes null/undefined), on renvoie null (= "—" à l'affichage).
function sumTrancheField(op, field) {
  if (!op?.tranches?.length) return null;
  let total = 0;
  let hasAny = false;
  for (const t of op.tranches) {
    const v = t[field];
    if (v !== null && v !== undefined && v !== '') {
      const n = Number(v);
      if (!isNaN(n)) { total += n; hasAny = true; }
    }
  }
  return hasAny ? total : null;
}
function sumVol(t) {
  if (!t || !t.vol) return 0;
  return Object.values(t.vol).reduce((s, v) => s + (Number(v) || 0), 0);
}
// Prix de revient TTC d'une tranche = somme des postes du bilan (Option A : bilan = source de vérité)
// Renvoie null si le bilan est entièrement vide (pas de poste saisi).
function trancheBudgetTTC(t) {
  if (!t) return null;
  let total = 0;
  let hasAny = false;
  const sections = ['charge_fonciere', 'batiment', 'honoraires', 'frais_divers', 'frais_financiers'];
  for (const sec of sections) {
    const obj = t[sec];
    if (obj && typeof obj === 'object') {
      for (const v of Object.values(obj)) {
        const n = Number(v);
        if (!isNaN(n) && n !== 0) { total += n; hasAny = true; }
      }
    }
  }
  return hasAny ? total : null;
}
// Logements d'une tranche : saisie directe (champ logements stocké en DB)
// La volumétrie T1-T5+ est un détail informatif qui ne court-circuite plus la saisie.
function trancheLogements(t) {
  // Volumétrie = source de vérité (cohérent avec "auto · somme volumétrie" et les snapshots).
  // Si un détail vol existe, total = sa somme (jamais le scalaire stocké, qui peut être obsolète).
  if (!t) return null;
  if (t.vol) return sumVol(t);
  const v = t.logements;
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}
// Total logements op : somme des tranches qui ont une saisie, sinon null
function totalLgts(op) {
  if (!op?.tranches?.length) return null;
  let total = 0;
  let hasAny = false;
  for (const t of op.tranches) {
    const v = trancheLogements(t);
    if (v !== null) { total += v; hasAny = true; }
  }
  return hasAny ? total : null;
}
// Prix de revient TTC d'une op = somme des bilans des tranches (Option A)
function totalBudget(op) {
  if (!op?.tranches?.length) return null;
  let total = 0;
  let hasAny = false;
  for (const t of op.tranches) {
    const v = trancheBudgetTTC(t);
    if (v !== null) { total += v; hasAny = true; }
  }
  return hasAny ? total : null;
}

// Best amount = most committed value (contract > LO > simulation)
// Renvoie 0 si aucun montant (pour rester compatible avec les reduce)
function bestPretAmount(p) {
  return Number(p.montant_contrat) || Number(p.montant_lo) || Number(p.montant_sim) || 0;
}
function bestSubvAmount(s) {
  return Number(s.montant_notifie ?? s.montant_notif) || Number(s.montant_demande) || 0;
}
// Variantes qui renvoient null si aucun montant (pour affichage "—")
function bestPretAmountOrNull(p) {
  const c = Number(p.montant_contrat);
  if (!isNaN(c) && c !== 0) return c;
  const l = Number(p.montant_lo);
  if (!isNaN(l) && l !== 0) return l;
  const s = Number(p.montant_sim);
  if (!isNaN(s) && s !== 0) return s;
  return null;
}
function bestSubvAmountOrNull(s) {
  const n = Number(s.montant_notifie ?? s.montant_notif);
  if (!isNaN(n) && n !== 0) return n;
  const d = Number(s.montant_demande);
  if (!isNaN(d) && d !== 0) return d;
  return null;
}

// Tranche-level derived totals (from sub-entity detail cards if present, else stored field)
function trancheDerivedPretBati(op, trancheKey, fallback) {
  const items = (op.prets || []).filter(p => p.tranche === trancheKey && (p.ligne || '').toLowerCase().includes('bâti'));
  if (items.length > 0) return items.reduce((s, p) => s + bestPretAmount(p), 0);
  return Number(fallback) || 0;
}
function trancheDerivedPretFoncier(op, trancheKey, fallback) {
  const items = (op.prets || []).filter(p => p.tranche === trancheKey && (p.ligne || '').toLowerCase().includes('foncier'));
  if (items.length > 0) return items.reduce((s, p) => s + bestPretAmount(p), 0);
  return Number(fallback) || 0;
}
function trancheDerivedPretAutres(op, trancheKey) {
  return (op.prets || []).filter(p => {
    if (p.tranche !== trancheKey) return false;
    const l = (p.ligne || '').toLowerCase();
    return !l.includes('bâti') && !l.includes('foncier');
  }).reduce((s, p) => s + bestPretAmount(p), 0);
}
function trancheDerivedPretTotal(op, trancheKey, fallbackBati, fallbackFoncier) {
  const items = (op.prets || []).filter(p => p.tranche === trancheKey);
  if (items.length > 0) return items.reduce((s, p) => s + bestPretAmount(p), 0);
  return (Number(fallbackBati) || 0) + (Number(fallbackFoncier) || 0);
}
function trancheDerivedSubvTotal(op, trancheKey, fallback) {
  const items = (op.subventions || []).filter(s => s.tranche === trancheKey);
  if (items.length > 0) return items.reduce((sum, s) => sum + bestSubvAmount(s), 0);
  return Number(fallback) || 0;
}

// Op-level totals: sum all prêt/subv cards (or fallback to tranche stored fields)
function opTotalPrets(op) {
  if ((op.prets || []).length > 0) {
    return (op.prets || []).reduce((s, p) => s + bestPretAmount(p), 0);
  }
  return totalPretsBatiFoncier(op);
}
function opTotalSubv(op) {
  if ((op.subventions || []).length > 0) {
    return (op.subventions || []).reduce((s, p) => s + bestSubvAmount(p), 0);
  }
  return totalSubvSum(op);
}

function totalPretsBatiFoncier(op) { return sumTrancheField(op, 'pret_bati') + sumTrancheField(op, 'pret_foncier'); }
function totalSubvSum(op) { return sumTrancheField(op, 'subv_total'); }
function totalFondsPropres(op) { return sumTrancheField(op, 'fonds_propres'); }

// Status class derivation (port from Python)
const STATUS_MAP = {
  'Notifiée':'success','Conventionné':'success','Convention signée':'success','Délibérée':'success','Contrat signé':'success','DFA signée':'success','Obtenu':'success','Validé':'success',
  "Lettre d'offre":'info','Accord de principe reçu':'info','Délibération votée':'info','DU sur opération':'info','Programmée':'info',
  'En cours':'warning','En cours de versement':'warning','En instruction':'warning','Demandée':'warning','En négociation':'warning','À instruire':'warning','Dossier transmis':'warning','Demandé':'warning','Déposée':'warning','Déposé':'warning','Instruction':'warning',
  'À demander':'neutral','À déposer':'neutral','En attente':'neutral','Soldé':'neutral','Soldée':'neutral','Sans objet':'neutral',
  'Refusé':'danger','Garantie refusée':'danger',
  'Travaux':'coral','Montage':'warning','GPA':'info','Livré / Clôturé':'success','Abandonné':'neutral',
};
function getStatusClass(statut) { return STATUS_MAP[statut] || 'neutral'; }
function statusBadge(text) {
  if (!text) return '<span class="muted">—</span>';
  return `<span class="badge-statut status-bg-${getStatusClass(text)}">${escapeHtml(text)}</span>`;
}

// Tranches options for dropdowns
function tranchesOptions(op, currentValue) {
  const codes = op.tranches.map(t => {
    const trCode = t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id;
    return trCode;
  });
  return codes.map(c => `<option value="${escapeHtml(c)}"${c === currentValue ? ' selected' : ''}>${escapeHtml(c)}</option>`).join('');
}

