// Handle taux index dropdown change: toggle visibility of spread vs libre input
function onTauxIndexChange(sel) {
  const card = sel.closest('.entity-card');
  if (!card) return;
  const idx = sel.value;
  const spreadWrap = card.querySelector('[data-taux-spread-wrap]');
  const libreWrap = card.querySelector('[data-taux-libre-wrap]');
  const spreadLabel = spreadWrap?.querySelector('label');
  const spreadInput = spreadWrap?.querySelector('input');
  if (idx === 'Autre') {
    if (spreadWrap) spreadWrap.style.display = 'none';
    if (libreWrap) libreWrap.style.display = '';
  } else if (idx === 'Fixe') {
    if (spreadWrap) spreadWrap.style.display = '';
    if (libreWrap) libreWrap.style.display = 'none';
    if (spreadLabel) spreadLabel.textContent = 'Taux (%)';
    if (spreadInput) spreadInput.placeholder = '1,20';
  } else {
    if (spreadWrap) spreadWrap.style.display = '';
    if (libreWrap) libreWrap.style.display = 'none';
    if (spreadLabel) spreadLabel.textContent = 'Spread (%)';
    if (spreadInput) spreadInput.placeholder = '+/- 0,20';
  }
}

// ============== GARANTIES (loan-centric view) ==============

const GARANT_COLORS = {
  'Commune': '#185fa5',
  'Métropole': '#9333ea',
  'EPCI': '#7c3aed',
  'Département': '#ba7517',
  'Région': '#1d9e75',
  'CGLLS': '#d85a30',
  'Hypothèque': '#888780',
  'CEGC': '#c4423a',
  'Caution bancaire': '#0c447c',
  'Autre': '#444441',
};
function garantColor(name) { return GARANT_COLORS[name] || '#888780'; }

function parseQuotite(q) {
  if (q == null || q === '') return 0;
  const n = Number(q);
  if (isNaN(n)) return 0;
  return n <= 1 ? n * 100 : n; // accept 0-1 or 0-100
}

function addGaranteeForPret(pretLigne) {
  const op = findOp(selectedOpCode);
  if (!op) return;
  if (!op.garanties) op.garanties = [];
  const t = op.tranches[selectedTrancheIdx];
  const trCode = t ? (t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id) : '';
  op.garanties.push({
    tranche: trCode,
    pret_lie: pretLigne,
  });
  renderTrancheDetail();
}

function renderGarantiesSection(garanties, op) {
  // Get prêts of the current tranche (with original indices for editing)
  const t = op.tranches[selectedTrancheIdx];
  const trCode = t ? (t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id) : null;
  const tranchePrets = (op.prets || [])
    .map((p, idx) => ({...p, _originalIdx: idx}))
    .filter(p => p.tranche === trCode);

  // Group garanties by pret_lie. Orphans are those whose pret_lie doesn't match any loan in this tranche.
  const byPret = {};
  const orphans = [];
  garanties.forEach(g => {
    const matching = tranchePrets.find(p => p.ligne === g.pret_lie);
    if (matching) {
      const key = matching.ligne;
      if (!byPret[key]) byPret[key] = [];
      byPret[key].push(g);
    } else {
      orphans.push(g);
    }
  });

  // Render a card per loan
  let loanCards = '';
  if (tranchePrets.length === 0) {
    loanCards = '<div class="gar-no-prets">Ajoute d\'abord des prêts dans la section Prêts ci-dessus pour pouvoir rattacher des garanties.</div>';
  } else {
    loanCards = tranchePrets.map(pret => renderGarLoanCard(pret, byPret[pret.ligne] || [], op)).join('');
  }

  // Orphans section
  let orphansHtml = '';
  if (orphans.length > 0) {
    orphansHtml = `
      <div class="gar-orphans-header"><i class="ti ti-alert-circle"></i>Garanties sans prêt rattaché (${orphans.length})</div>
      ${orphans.map(g => editMode ? renderGarantieCardEdit(g, op) : renderGarantieCard(g)).join('')}
    `;
  }

  // Add orphan button (edit mode only): a free-standing garantie
  const addOrphanBtn = editMode
    ? `<button class="add-row-btn" style="margin-top:8px;" onclick="addEntityRow('garanties')"><i class="ti ti-plus"></i>Ajouter une garantie sans rattachement</button>`
    : '';

  return `
    <div class="section">
      <div class="subent-header">
        <div class="subent-title gar"><i class="ti ti-shield-check"></i>Garanties d'emprunt · ${garanties.length}</div>
        <div class="subent-aggr">${tranchePrets.length} prêt${tranchePrets.length > 1 ? 's' : ''} à couvrir</div>
      </div>
      ${loanCards}
      ${orphansHtml}
      ${addOrphanBtn}
    </div>
  `;
}

function renderGarLoanCard(pret, gars, op) {
  const amount = bestPretAmountOrNull(pret);

  // Case 1: prêt non garanti — render different layout
  if (pret.non_garanti) {
    return `
      <div class="gar-loan-card gar-loan-card-non-garanti">
        <div class="gar-loan-head">
          <div class="gar-loan-title">${escapeHtml(pret.ligne || '—')}${pret.financeur ? ` <span style="color:var(--text-tertiary);font-weight:400;">· ${escapeHtml(pret.financeur)}</span>` : ''}</div>
          <div class="gar-loan-amount">${fmtMontant(amount)}</div>
        </div>
        <div class="gar-non-garanti-msg">
          <i class="ti ti-shield-check"></i>
          Prêt sans garantie requise
        </div>
      </div>
    `;
  }

  // Classify garanties: actée vs prévisionnelle vs relais
  const STATUTS_ACTES = ['Délibération votée', 'Délibération exécutoire', 'Convention signée'];
  const STATUTS_PREV = ['À demander', 'Dossier transmis', 'Accord de principe reçu'];

  // Relais comes first regardless of statut (it's a temporary cover)
  const relaisGars = gars.filter(g => g.caution_relais);
  const acteeGars = gars.filter(g => !g.caution_relais && STATUTS_ACTES.includes(g.statut));
  const prevGars = gars.filter(g => !g.caution_relais && STATUTS_PREV.includes(g.statut));
  const otherGars = gars.filter(g => !g.caution_relais && !STATUTS_ACTES.includes(g.statut) && !STATUTS_PREV.includes(g.statut));

  const acteeQuotite = acteeGars.reduce((s, g) => s + parseQuotite(g.quotite), 0);
  const prevQuotite = prevGars.reduce((s, g) => s + parseQuotite(g.quotite), 0);
  const otherQuotite = otherGars.reduce((s, g) => s + parseQuotite(g.quotite), 0);
  const relaisQuotite = relaisGars.reduce((s, g) => s + parseQuotite(g.quotite), 0);

  // Real (non-relais) quotité — used to determine if "true" coverage exists
  const realQuotite = acteeQuotite + prevQuotite + otherQuotite;
  // Total displayed in the bar (with relais if no real coverage)
  const displayedQuotite = realQuotite > 0 ? realQuotite : (realQuotite + relaisQuotite);
  const remaining = Math.max(0, 100 - displayedQuotite);

  // Coverage status text
  let statusText, statusClass;
  if (gars.length === 0) {
    statusText = '○ Aucune garantie';
    statusClass = 'none';
  } else if (realQuotite === 0 && relaisQuotite > 0) {
    // Only caution relais
    if (Math.abs(relaisQuotite - 100) < 0.5) {
      statusText = `🛡 Caution relais ${relaisQuotite.toFixed(0)}% (en attente des vraies garanties)`;
    } else {
      statusText = `🛡 Caution relais ${relaisQuotite.toFixed(0)}% · ${remaining.toFixed(0)}% non couvert`;
    }
    statusClass = 'relais';
  } else if (Math.abs(realQuotite - 100) < 0.5) {
    // Fully covered by real garanties
    if (prevQuotite > 0 && acteeQuotite > 0) {
      statusText = `✓ Couverture actée ${acteeQuotite.toFixed(0)}% (+ ${prevQuotite.toFixed(0)}% prévisionnel)`;
      statusClass = 'partial';
    } else if (prevQuotite > 0) {
      statusText = `⏳ Couverture prévisionnelle ${prevQuotite.toFixed(0)}%`;
      statusClass = 'partial';
    } else {
      statusText = '✓ Entièrement couvert et acté (100%)';
      statusClass = 'complete';
    }
    if (relaisQuotite > 0) statusText += ` · 🛡 relais ${relaisQuotite.toFixed(0)}% encore en place`;
  } else if (realQuotite > 100) {
    statusText = `⚠ Surcouverture : ${realQuotite.toFixed(0)}% (somme des quotités > 100%)`;
    statusClass = 'over';
  } else {
    // Partial real coverage — describe components
    const parts = [];
    if (acteeQuotite > 0) parts.push(`${acteeQuotite.toFixed(0)}% acté`);
    if (prevQuotite > 0) parts.push(`${prevQuotite.toFixed(0)}% prévisionnel`);
    if (otherQuotite > 0) parts.push(`${otherQuotite.toFixed(0)}% autre`);
    if (relaisQuotite > 0) parts.push(`🛡 ${relaisQuotite.toFixed(0)}% relais`);
    statusText = `⚠ ${remaining.toFixed(0)}% non couvert · ` + parts.join(' + ');
    statusClass = 'partial';
  }

  // Build coverage bar segments
  const buildSegment = (g, kind) => {
    const pct = parseQuotite(g.quotite);
    if (pct <= 0) return '';
    const color = garantColor(g.garant);
    const label = pct >= 12 ? `${Math.round(pct)}%` : '';
    let cls = 'gar-segment';
    let title = `${g.garant || '—'} : ${pct}% — ${g.statut || 'statut inconnu'}`;
    if (kind === 'relais') {
      cls += ' gar-segment-relais';
      title += ' (caution RELAIS)';
    } else if (kind === 'prev') {
      cls += ' gar-segment-prev';
      title += ' (prévisionnel)';
    }
    const extraLabel = kind === 'relais' && pct >= 18 ? ' · RELAIS' : '';
    return `<div class="${cls}" style="flex: 0 0 ${pct}%; background: ${color};" title="${escapeHtml(title)}">${label}${extraLabel}</div>`;
  };

  // Order: actée, prev, other, then relais if no real coverage
  let segmentsHtml = '';
  segmentsHtml += acteeGars.map(g => buildSegment(g, 'actee')).join('');
  segmentsHtml += prevGars.map(g => buildSegment(g, 'prev')).join('');
  segmentsHtml += otherGars.map(g => buildSegment(g, 'other')).join('');
  // Show relais segments only if no real coverage (they "fill the gap")
  if (realQuotite === 0) {
    segmentsHtml += relaisGars.map(g => buildSegment(g, 'relais')).join('');
  }

  const uncoveredSegment = remaining > 0.5
    ? `<div class="gar-segment uncovered" style="flex: 0 0 ${remaining}%;">${remaining >= 18 ? remaining.toFixed(0) + '% à couvrir' : ''}</div>`
    : '';

  // Garantee rows
  let garRowsHtml;
  if (editMode) {
    garRowsHtml = gars.map(g => renderGarantieCardEdit(g, op)).join('');
  } else {
    garRowsHtml = gars.map(g => renderGarRowCompact(g)).join('');
  }

  // Add button (edit mode)
  const addBtn = editMode
    ? `<button class="gar-add-btn-mini" onclick="addGaranteeForPret('${escapeHtml(pret.ligne || '').replace(/'/g, '\\\'')}')"><i class="ti ti-plus"></i>Ajouter une garantie pour ce prêt</button>`
    : '';

  return `
    <div class="gar-loan-card">
      <div class="gar-loan-head">
        <div class="gar-loan-title">${escapeHtml(pret.ligne || '—')}${pret.financeur ? ` <span style="color:var(--text-tertiary);font-weight:400;">· ${escapeHtml(pret.financeur)}</span>` : ''}</div>
        <div class="gar-loan-amount">${fmtMontant(amount)}</div>
      </div>
      <div class="gar-coverage-bar">
        ${segmentsHtml}${uncoveredSegment}
      </div>
      <div class="gar-coverage-status ${statusClass}">${statusText}</div>
      ${garRowsHtml}
      ${addBtn}
    </div>
  `;
}

function renderGarRowCompact(g) {
  const pct = parseQuotite(g.quotite);
  const color = garantColor(g.garant);
  const spIcons = sharepointIcons([
    { lien: g.lien_sp_accord, label: 'Accord de principe', icon: 'file-text' },
    { lien: g.lien_sp_delib, label: 'Délibération', icon: 'file-certificate' },
  ]);
  return `
    <div class="gar-row${diffEntityClass('garanties', g)}" data-section="garanties" data-row-idx="${g._originalIdx}">
      <span class="gar-color-dot" style="background: ${color};"></span>
      <div class="gar-row-content">
        <div class="gar-row-line1">
          <span class="gar-row-name">${escapeHtml(g.garant || '—')}</span>
          <span class="gar-row-pct">${pct ? pct + '%' : '—'}</span>
          ${g.caution_relais ? '<span class="relais-tag">🛡 RELAIS</span>' : ''}
          ${spIcons}
          ${statusBadge(g.statut)}
        </div>
        ${(g.contact || g.date_demande || g.date_ap || g.date_conv) ? `<div class="gar-row-meta">
          ${g.contact ? `<span><i class="ti ti-user"></i>${escapeHtml(g.contact)}</span>` : ''}
          ${g.date_demande ? `<span>Demandée : ${escapeHtml(g.date_demande)}</span>` : ''}
          ${g.date_ap ? `<span>AP : ${escapeHtml(g.date_ap)}</span>` : ''}
          ${g.date_conv ? `<span>Convention : ${escapeHtml(g.date_conv)}</span>` : ''}
        </div>` : ''}
        ${g.commentaires ? `<div class="gar-row-notes">${escapeHtml(g.commentaires)}</div>` : ''}
      </div>
    </div>
  `;
}

