// Formatters: see fmtMontant defined at top of script

function selectOp(code) {
  // Garde-fou : si des modifs sont en cours, demander confirmation
  if (editMode && hasUnsavedChanges()) {
    if (!confirm('Vous avez des modifications non enregistrées sur l\'opération en cours. Les abandonner et changer d\'opération ?')) {
      return;
    }
    // L'utilisateur a confirmé l'abandon : on restaure l'état d'origine
    revertOpEdits();
  }
  selectedOpCode = code;
  selectedTrancheIdx = 0;
  editMode = false; // exit edit mode when switching ops
  editSessionSnap = null;
  viewingSnapshotIdx = null;
  compareWithIdx = null;
  storageSet('selectedOp', code || '');
  renderAll();
}

// Retourne true si l'op affichée a des modifs non sauvegardées (vs snapshot d'édition)
function hasUnsavedChanges() {
  if (!editMode || !editSessionSnap) return false;
  const op = findOp(selectedOpCode);
  if (!op) return false;
  // Compare les champs principaux + tranches + sub-entités
  // On fait une comparaison stringifiée, ce qui couvre toute modification
  try {
    return JSON.stringify(op) !== JSON.stringify(editSessionSnap);
  } catch (e) {
    return false;
  }
}

// Restaure l'op à son état au début de l'édition (rollback en mémoire)
function revertOpEdits() {
  if (!editSessionSnap) return;
  const op = findOp(selectedOpCode);
  if (!op) return;
  // On copie chaque clé du snapshot vers l'op
  Object.keys(editSessionSnap).forEach(k => {
    op[k] = editSessionSnap[k];
  });
  editSessionSnap = null;
}
function selectTranche(idx) { selectedTrancheIdx = idx; renderTrancheDetail(); replaceTablerIcons(); }
function renderAll() { renderSidebar(); renderOpDetail(); renderTrancheDetail(); refreshNavBadges(); replaceTablerIcons(); }

// Met à jour le badge "Validations" avec le nombre de workflows en attente pour l'utilisateur courant
function refreshNavBadges() {
  const badge = document.getElementById('navBadgePending');
  if (!badge) return;
  // Compte les workflows où l'utilisateur courant est destinataire ET le statut est pending
  const me = (typeof CURRENT_USER !== 'undefined') ? CURRENT_USER : '';
  let pendingForMe = 0;
  WORKFLOWS.forEach(w => {
    if (Array.isArray(w.recipients)) {
      w.recipients.forEach(r => {
        if (isCurrentUser(r.name) && r.status === 'pending') pendingForMe++;
      });
    } else if (isCurrentUser(w.recipient) && w.status === 'pending') {
      pendingForMe++;
    }
  });
  if (pendingForMe > 0) {
    badge.textContent = pendingForMe;
    badge.style.display = '';
  } else {
    badge.style.display = 'none';
  }
}

// === Rebuild dashboard KPI tiles + bars dynamically from current DATA ===
function refreshDashboardKpis() {
  const ops = DATA.filter(o => !o.deleted && inScope(o));
  if (ops.length === 0) return;

  // Helper: render bar list HTML
  const renderBars = (rows) => {
    if (!rows || rows.length === 0) return '<div class="empty-state-mini">Aucune donnée</div>';
    const max = Math.max(...rows.map(r => r.value), 1);
    return '<div class="bar-list">' + rows.map(r => `
      <div class="bar-row">
        <div class="bar-row-label">${escapeHtml(r.label)}</div>
        <div class="bar-row-track">
          <div class="bar-row-fill" style="width:${(r.value / max * 100).toFixed(1)}%;background:${r.color || 'var(--info-accent)'};"></div>
        </div>
        <div class="bar-row-value">${escapeHtml(String(r.display ?? r.value))}</div>
      </div>
    `).join('') + '</div>';
  };

  // 1) KPI grid (4 tiles)
  let totalLgts = 0, totalBudget = 0;
  const regions = new Set();
  ops.forEach(op => {
    const tLgts = (typeof totalLgtsOp === 'function') ? totalLgtsOp(op) : null;
    if (tLgts !== null && tLgts !== undefined) totalLgts += (tLgts || 0);
    else (op.tranches || []).forEach(t => { const l = trancheLogements(t); if (l !== null) totalLgts += l; });
    const tBudget = totalBudget && (typeof totalBudget === 'function') ? null : null;
    (op.tranches || []).forEach(t => {
      const b = trancheBudgetTTC(t);
      if (b !== null) totalBudget += b;
    });
    if (op.region) regions.add(op.region);
  });
  const kpiGrid = document.getElementById('dashboardKpiGrid');
  if (kpiGrid) {
    kpiGrid.innerHTML = `
      <div class="kpi-card">
        <div class="kpi-label"><i class="ti ti-building-community"></i>Opérations</div>
        <div class="kpi-value">${ops.length}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label"><i class="ti ti-home"></i>Logements totaux</div>
        <div class="kpi-value">${totalLgts || '—'}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label"><i class="ti ti-cash"></i>Budget consolidé</div>
        <div class="kpi-value">${fmtEuros(totalBudget)}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label"><i class="ti ti-map-pin"></i>Régions</div>
        <div class="kpi-value">${regions.size}</div>
      </div>
    `;
  }

  // 2) Statut bars (par phase)
  const phaseCount = {};
  ops.forEach(op => {
    const p = op.phase_actuelle || 'Montage';
    phaseCount[p] = (phaseCount[p] || 0) + 1;
  });
  const phaseOrder = ['Montage', 'Validation CA', 'Travaux', 'Livraison', 'GPA'];
  const statutBars = phaseOrder
    .filter(p => phaseCount[p])
    .map(p => ({
      label: p,
      value: phaseCount[p],
      display: phaseCount[p],
      color: (PHASE_COLORS[p] && PHASE_COLORS[p].text) || 'var(--info-accent)'
    }));
  const statutEl = document.getElementById('dashboardStatutBars');
  if (statutEl) statutEl.innerHTML = renderBars(statutBars);

  // 3) Régions
  const regionCount = {};
  ops.forEach(op => {
    if (op.region) regionCount[op.region] = (regionCount[op.region] || 0) + 1;
  });
  const regionBars = Object.entries(regionCount)
    .sort((a, b) => b[1] - a[1])
    .map(([region, n]) => ({ label: region, value: n, display: n, color: 'var(--success-accent)' }));
  const regionEl = document.getElementById('dashboardRegionBars');
  if (regionEl) regionEl.innerHTML = renderBars(regionBars);

  // 4) Logements par type de financement (PLAI/PLUS/PLS/PLI/Libre/Autre)
  const finTypes = { 'PLAI': 0, 'PLUS': 0, 'PLS': 0, 'PLI': 0, 'LIBRE': 0, 'AUTRE': 0 };
  ops.forEach(op => {
    (op.tranches || []).forEach(t => {
      ['plai', 'plus', 'pls', 'pli', 'libre', 'autre'].forEach(k => {
        const v = (t.vol && Number(t.vol[k])) || 0;
        if (v > 0) finTypes[k.toUpperCase()] += v;
      });
    });
  });
  const finBars = Object.entries(finTypes)
    .filter(([_, v]) => v > 0)
    .map(([type, v]) => ({ label: type, value: v, display: v, color: 'var(--purple-accent)' }));
  const finEl = document.getElementById('dashboardFinancementBars');
  if (finEl) finEl.innerHTML = renderBars(finBars);

  // 5) Avancement agréments (par statut)
  const agrCount = {};
  ops.forEach(op => {
    (op.tranches || []).forEach(t => {
      const s = t.statut_agrement || 'Non défini';
      agrCount[s] = (agrCount[s] || 0) + 1;
    });
  });
  const agrBars = Object.entries(agrCount)
    .sort((a, b) => b[1] - a[1])
    .map(([s, n]) => ({ label: s, value: n, display: n, color: 'var(--success-accent)' }));
  const agrEl = document.getElementById('dashboardAgrementBars');
  if (agrEl) agrEl.innerHTML = renderBars(agrBars);

  // 6) Livraisons par année
  const livCount = {};
  ops.forEach(op => {
    if (op.date_livraison) {
      const d = parseDateStr(op.date_livraison);
      if (d) {
        const y = d.getFullYear();
        livCount[y] = (livCount[y] || 0) + 1;
      }
    }
  });
  const livBars = Object.entries(livCount)
    .sort((a, b) => a[0] - b[0])
    .map(([y, n]) => ({ label: y, value: n, display: n, color: 'var(--warning-accent)' }));
  const livEl = document.getElementById('dashboardLivraisonBars');
  if (livEl) livEl.innerHTML = renderBars(livBars);

  // 7) Répartition financement global (FP / Prêts / Subv)
  let fp = 0, prets = 0, subv = 0;
  ops.forEach(op => {
    (op.tranches || []).forEach(t => { fp += (parseFloat(t.fonds_propres) || 0); });
    (op.prets || []).forEach(p => { prets += bestPretAmount(p); });
    (op.subventions || []).forEach(s => { subv += bestSubvAmount(s); });
  });
  const finFmt = (v) => fmtEuros(v);
  const finGlobalBars = [
    { label: 'Fonds propres', value: fp, display: finFmt(fp), color: 'var(--purple-accent)' },
    { label: 'Prêts', value: prets, display: finFmt(prets), color: 'var(--info-accent)' },
    { label: 'Subventions', value: subv, display: finFmt(subv), color: 'var(--success-accent)' },
  ].filter(b => b.value > 0);
  const finGlobalEl = document.getElementById('dashboardFinanceBars');
  if (finGlobalEl) finGlobalEl.innerHTML = renderBars(finGlobalBars);

  // 8) Zone ABC
  const zoneCount = {};
  ops.forEach(op => {
    const z = op.zone_abc || 'Non définie';
    zoneCount[z] = (zoneCount[z] || 0) + 1;
  });
  const zoneBars = Object.entries(zoneCount)
    .sort((a, b) => b[1] - a[1])
    .map(([z, n]) => ({ label: 'Zone ' + z, value: n, display: n, color: 'var(--coral-accent)' }));
  const zoneEl = document.getElementById('dashboardZoneBars');
  if (zoneEl) zoneEl.innerHTML = renderBars(zoneBars);
}

// ============== GANTT VIEW ==============

let ganttEditMode = false;
let ganttMin = null;
let ganttMax = null;
const GANTT_MONTH_WIDTH = 50; // px per month
const GANTT_DAY_WIDTH = GANTT_MONTH_WIDTH / 30;

const GANTT_DATES = [
  { key: 'date_promesse', label: 'Promesse', color: '#888780' },
  { key: 'date_acte', label: 'Acte authentique', color: '#444441' },
  { key: 'date_depot_pc', label: 'Dépôt PC', color: '#ba7517' },
  { key: 'date_obtention_pc', label: 'Obtention PC', color: '#1d9e75' },
  { key: 'date_os', label: 'OS', color: '#185fa5' },
  { key: 'date_livraison', label: 'Livraison', color: '#9333ea' },
];

function parseDateStr(s) {
  if (!s) return null;
  const str = String(s).trim();
  // DD/MM/YYYY
  let m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) {
    const d = new Date(+m[3], +m[2] - 1, +m[1]);
    return isNaN(d.getTime()) ? null : d;
  }
  // YYYY-MM-DD
  m = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) {
    const d = new Date(+m[1], +m[2] - 1, +m[3]);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function fmtDateStr(d) {
  if (!d || isNaN(d.getTime())) return '';
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  return `${day}/${month}/${d.getFullYear()}`;
}

// Convertit DD/MM/YYYY (français) → YYYY-MM-DD (ISO, pour input type=date)
function frToIso(frStr) {
  if (!frStr) return '';
  const m = String(frStr).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  // Si déjà au format ISO
  if (/^\d{4}-\d{2}-\d{2}/.test(frStr)) return String(frStr).slice(0, 10);
  return '';
}

// Convertit YYYY-MM-DD (ISO) → DD/MM/YYYY (français)
function isoToFr(isoStr) {
  if (!isoStr) return '';
  const m = String(isoStr).match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[3].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[1]}`;
  return '';
}

function computeGanttRange() {
  // Hard floor: January 2023 (no need to go earlier per user request)
  const min = new Date(2023, 0, 1);
  let max = null;
  DATA.forEach(op => {
    GANTT_DATES.forEach(({key}) => {
      const d = parseDateStr(op[key]);
      if (d && (!max || d > max)) max = d;
    });
  });
  if (!max) {
    max = new Date(new Date().getFullYear() + 2, 11, 1);
  } else {
    // Pad: ceil to month end + 3 months
    max = new Date(max.getFullYear(), max.getMonth() + 3, 1);
  }
  // Ensure we always cover at least 3 years from min
  const minMax = new Date(min.getFullYear() + 3, 0, 1);
  if (max < minMax) max = minMax;
  return { min, max };
}

function monthsBetween(a, b) {
  return (b.getFullYear() - a.getFullYear()) * 12 + (b.getMonth() - a.getMonth());
}

function dateToPx(date, min) {
  const months = monthsBetween(min, date);
  const dayOffset = (date.getDate() - 1) / 30;
  return (months + dayOffset) * GANTT_MONTH_WIDTH;
}

function pxToDate(px, min) {
  const months = px / GANTT_MONTH_WIDTH;
  const wholeMonths = Math.floor(months);
  const monthFraction = months - wholeMonths;
  const day = Math.max(1, Math.min(28, Math.round(monthFraction * 30) + 1));
  return new Date(min.getFullYear(), min.getMonth() + wholeMonths, day);
}

// Gantt filter state
let ganttFilters = { search: '', phase: '', region: '', equipe: '' };

async function geocodeOpAddress(uid) {
  const op = DATA.find(o => o._uid === uid);
  if (!op) return;

  // Read LIVE values from form inputs (so unsaved edits work)
  const getInputVal = (field) => {
    const el = document.querySelector(`[data-edit-op-field="${field}"]`);
    return el ? (el.value || '').trim() : ((op[field] || '') + '').trim();
  };
  const adresse = getInputVal('adresse');
  const code_postal = getInputVal('code_postal');
  const commune = getInputVal('commune');
  const query = [adresse, code_postal, commune].filter(Boolean).join(' ').trim();

  if (!query) {
    showToast("Saisissez d'abord une adresse, un code postal ou une commune", 'alert-triangle');
    return;
  }
  showToast(`Recherche via la BAN : « ${query} »…`, 'map-pin');
  const result = await geocodeBAN(query);
  if (!result) {
    showToast('Adresse non trouvée — vérifiez la saisie', 'alert-triangle');
    return;
  }
  // Save geocoding result onto op (independent of form save)
  op.latitude = result.lat;
  op.longitude = result.lon;
  op.adresse_geocoded = result.label;

  // Auto-fill normalized fields from the BAN response
  const updates = [];
  const setField = (field, value) => {
    if (value == null || value === '') return;
    const el = document.querySelector(`[data-edit-op-field="${field}"]`);
    const oldVal = op[field];
    if (el) {
      el.value = value;
      // Visual feedback: mark as modified
      el.classList.add('field-modified-session');
    }
    op[field] = value;
    if ((oldVal || '') !== value) updates.push(field);
  };

  if (result.adresse) setField('adresse', result.adresse);
  if (result.postcode) setField('code_postal', result.postcode);
  if (result.city) setField('commune', result.city);
  if (result.depName && result.depCode) setField('departement', `${result.depName} (${result.depCode})`);
  if (result.regName) setField('region', result.regName);

  // Update the geo-panel DOM in place
  const panel = document.querySelector('.geo-panel .geo-panel-status');
  if (panel) {
    panel.innerHTML = `
      <i class="ti ti-check"></i>
      <span>Géolocalisée : <strong>${result.lat.toFixed(4)}, ${result.lon.toFixed(4)}</strong> <span class="geo-panel-label">— ${escapeHtml(result.label)}</span></span>
    `;
    replaceTablerIcons(panel);
  }

  // Refresh the mini-map to show the new position
  initOpLocationMap(op);

  const msg = updates.length > 0
    ? `Géolocalisée + ${updates.length} champ${updates.length > 1 ? 's' : ''} normalisé${updates.length > 1 ? 's' : ''}`
    : `Géolocalisée : ${result.label}`;
  showToast(msg, 'check');
}

// ============== MAP VIEW ==============
let mapInstance = null;
let opLocationMapInstance = null;

// Tile layer configurations — Plan (OSM) and Satellite (Esri)
const TILE_LAYERS = {
  plan: {
    url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
    attribution: '© OpenStreetMap',
    maxZoom: 19,
    subdomains: 'abc',
  },
  satellite: {
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attribution: '© Esri World Imagery',
    maxZoom: 19,
    subdomains: '',
  },
};

// Switch a map's tile layer between Plan and Satellite
function applyMapLayer(map, type) {
  if (!map) return;
  if (map._currentTileLayer) {
    try { map.removeLayer(map._currentTileLayer); } catch (e) {}
  }
  const conf = TILE_LAYERS[type] || TILE_LAYERS.plan;
  const layer = L.tileLayer(conf.url, {
    attribution: conf.attribution,
    maxZoom: conf.maxZoom,
    subdomains: conf.subdomains || 'abc',
  });
  layer.addTo(map);
  map._currentTileLayer = layer;
  map._currentLayerType = type;
}

// Add a Plan / Satellite toggle control to a Leaflet map (top-right corner)
function addMapLayerToggle(map, defaultType) {
  if (!map || !window.L) return;
  const ctrl = L.control({ position: 'topright' });
  ctrl.onAdd = function() {
    const div = L.DomUtil.create('div', 'map-layer-toggle leaflet-bar');
    const currentType = map._currentLayerType || defaultType || 'plan';
    div.innerHTML = `
      <button class="map-layer-btn${currentType === 'plan' ? ' active' : ''}" data-layer="plan" type="button">Plan</button>
      <button class="map-layer-btn${currentType === 'satellite' ? ' active' : ''}" data-layer="satellite" type="button">Satellite</button>
    `;
    L.DomEvent.disableClickPropagation(div);
    L.DomEvent.disableScrollPropagation(div);
    div.querySelectorAll('.map-layer-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const type = btn.dataset.layer;
        applyMapLayer(map, type);
        div.querySelectorAll('.map-layer-btn').forEach(b => {
          b.classList.toggle('active', b.dataset.layer === type);
        });
      });
    });
    return div;
  };
  ctrl.addTo(map);
  return ctrl;
}
let mapMarkers = [];
let mapFilters = { search: '', phase: '', region: '', person: '' };
const PHASE_MARKER_COLORS = {
  'Montage': '#d85a30',
  'Validation CA': '#185fa5',
  'Travaux': '#ba7517',
  'Livraison': '#1d9e75',
  'GPA': '#888780',
};

// Geocode an address using BAN (api-adresse.data.gouv.fr)
// Returns Promise<{lat, lon, label} | null>
async function geocodeBAN(query) {
  if (!query || !query.trim()) return null;
  try {
    const url = `https://api-adresse.data.gouv.fr/search/?q=${encodeURIComponent(query)}&limit=1`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    if (!data.features || data.features.length === 0) return null;
    const f = data.features[0];
    const p = f.properties || {};
    // Parse context: "92, Hauts-de-Seine, Île-de-France"
    let depCode = null, depName = null, regName = null;
    if (p.context) {
      const parts = p.context.split(',').map(s => s.trim());
      if (parts.length >= 1) depCode = parts[0];
      if (parts.length >= 2) depName = parts[1];
      if (parts.length >= 3) regName = parts[2];
    }
    return {
      lat: f.geometry.coordinates[1],
      lon: f.geometry.coordinates[0],
      label: p.label,
      score: p.score,
      adresse: p.name || null,        // "10 Allée des Acacias"
      housenumber: p.housenumber || null,
      street: p.street || null,
      postcode: p.postcode || null,    // "92310"
      city: p.city || null,            // "Sèvres"
      depCode, depName, regName,
    };
  } catch (e) {
    console.warn('BAN geocoding failed:', e);
    return null;
  }
}

// Build the search query from an op's address fields
function opAddressQuery(op) {
  return [op.adresse, op.code_postal, op.commune].filter(Boolean).join(' ').trim();
}

function buildMarkerIcon(color) {
  if (!window.L) return null;
  return L.divIcon({
    className: 'map-marker-icon',
    html: `<div class="map-marker-pin" style="background:${color};"></div>`,
    iconSize: [22, 22],
    iconAnchor: [11, 11],
  });
}

// ============== COMITÉS ==============
// Each comité is attached to an op (in op.comites array).
// Fields: id, type ('CA'|'C2I'|'Revue'), date, lien_sharepoint, doc_name, doc_data_url, doc_size, notes,
//         submitted_wf_id (optional — reference to a WORKFLOWS entry if submitted for validation)

function comiteTypeConfig(type) {
  switch (type) {
    case 'CA': return { label: 'CA', full: "Conseil d'Administration", color: 'success', bg: 'var(--success-bg)', txt: 'var(--success-text)', accent: 'var(--success-accent)' };
    case 'C2I': return { label: 'C2I', full: "Comité Interne d'Investissement", color: 'warning', bg: 'var(--warning-bg)', txt: 'var(--warning-text)', accent: 'var(--warning-accent)' };
    case 'Revue': return { label: 'Revue', full: "Revue d'opération", color: 'info', bg: 'var(--info-bg)', txt: 'var(--info-text)', accent: 'var(--info-accent)' };
    default: return { label: type || '?', full: type || '?', color: 'neutral', bg: 'var(--bg-tertiary)', txt: 'var(--text-secondary)', accent: 'var(--border-color-strong)' };
  }
}

// A comité is "planifié" if statut === 'planifie' (no PV yet, future date typically)
// "réalisé" otherwise (default if statut absent, for backward compat)
function isComitePlanifie(c) {
  return c && c.statut === 'planifie';
}
function comiteStatutLabel(c) {
  return isComitePlanifie(c) ? 'Planifié' : 'Réalisé';
}

// Return all comités across all ops with the host op attached
function getAllComites() {
  const result = [];
  DATA.forEach(op => {
    if (op.deleted) return;
    if (!Array.isArray(op.comites)) return;
    op.comites.forEach(c => result.push({ comite: c, op }));
  });
  return result;
}

function findComite(uid) {
  for (const op of DATA) {
    if (!Array.isArray(op.comites)) continue;
    const c = op.comites.find(x => x.id === uid);
    if (c) return { comite: c, op };
  }
  return null;
}

function formatComDate(dateStr) {
  return dateStr || '—';
}

// Render the Comités section in op detail
function renderComitesSection(op, isEditMode) {
  const comites = Array.isArray(op.comites) ? op.comites : [];
  // Sort by date desc (most recent first)
  const sorted = [...comites].sort((a, b) => {
    const da = parseDateStr(a.date) || new Date(0);
    const db = parseDateStr(b.date) || new Date(0);
    return db.getTime() - da.getTime();
  });

  const cards = sorted.map(c => renderComiteCard(c, op, isEditMode)).join('');

  return `
    <div class="section">
      <div class="section-label comites"><i class="ti ti-users"></i>Comités</div>
      ${comites.length === 0 && !isEditMode
        ? '<div class="comites-empty">Aucun comité enregistré pour cette opération.</div>'
        : `<div class="comites-list">${cards}</div>`}
      ${isEditMode ? `
        <button class="btn-add-comite" onclick="addComite('${escapeHtml(op._uid)}')" type="button">
          <i class="ti ti-plus"></i>Ajouter un comité
        </button>
      ` : ''}
    </div>
  `;
}

function renderComiteCard(c, op, isEditMode) {
  const conf = comiteTypeConfig(c.type);
  const wf = c.submitted_wf_id ? WORKFLOWS.find(w => w.id === c.submitted_wf_id) : null;

  if (isEditMode) {
    return `
      <div class="comite-card comite-card-edit" data-comite-id="${escapeHtml(c.id)}">
        <div class="comite-card-row">
          <div class="comite-edit-field">
            <label>Type</label>
            <select class="comite-edit-input" data-comite-field="type" data-comite-id="${escapeHtml(c.id)}">
              ${getRef('types_comite').map(t => `<option value="${escapeHtml(t)}"${c.type === t ? ' selected' : ''}>${escapeHtml(comiteTypeConfig(t).full)}</option>`).join('')}
            </select>
          </div>
          <div class="comite-edit-field">
            <label>Date</label>
            <input type="date" class="comite-edit-input" data-comite-field="date" data-comite-id="${escapeHtml(c.id)}" value="${escapeHtml(frToIso(c.date))}" />
          </div>
          <div class="comite-edit-field comite-edit-field-wide">
            <label>Lien SharePoint</label>
            <input type="text" class="comite-edit-input" data-comite-field="lien_sharepoint" data-comite-id="${escapeHtml(c.id)}" value="${escapeHtml(c.lien_sharepoint || '')}" placeholder="https://..." />
          </div>
          <button class="comite-remove-btn" onclick="removeComite('${escapeHtml(op._uid)}', '${escapeHtml(c.id)}')" type="button" title="Supprimer ce comité"><i class="ti ti-trash"></i></button>
        </div>
        ${c.doc_name ? `<div class="comite-card-doc">
          <i class="ti ti-file-text"></i><span>${escapeHtml(c.doc_name)}</span>
          <span class="comite-doc-size">${formatFileSize(c.doc_size)}</span>
        </div>` : ''}
        <div class="comite-edit-actions">
          <label class="comite-upload-btn" title="Joindre un PDF">
            <input type="file" accept="application/pdf,.pdf" style="display:none;" onchange="attachComiteFile(event, '${escapeHtml(op._uid)}', '${escapeHtml(c.id)}')" />
            <i class="ti ti-cloud"></i>${c.doc_name ? 'Remplacer le PDF' : 'Joindre un PDF'}
          </label>
          ${c.doc_data_url ? `<button class="btn-small btn-preview" type="button" onclick="openPdfPreview('${escapeHtml(c.doc_name || 'document.pdf')}', findComite('${escapeHtml(c.id)}').comite.doc_data_url)"><i class="ti ti-eye"></i>Voir</button>` : ''}
        </div>
      </div>
    `;
  }

  // Read mode
  const isPlanned = isComitePlanifie(c);
  const wfApproved = wf && computeWfOverallStatus(wf) === 'approved';
  // Récupérer la date de signature du PV (date du dernier recipient approved du workflow)
  let pvSignedDate = null;
  let pvDocUrl = null;
  if (wfApproved && wf) {
    const recipients = getWfRecipients(wf);
    const approvedRecipients = recipients.filter(r => r.status === 'approved' && r.responded_at);
    if (approvedRecipients.length > 0) {
      // Dernière signature
      const latest = approvedRecipients.sort((a, b) => new Date(b.responded_at) - new Date(a.responded_at))[0];
      const d = new Date(latest.responded_at);
      if (!isNaN(d.getTime())) {
        pvSignedDate = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
      }
    }
    pvDocUrl = wf.doc_url || wf.doc_data_url;
  }

  return `
    <div class="comite-card comite-card-${conf.color}${isPlanned ? ' comite-card-planned' : ''}" data-comite-id="${escapeHtml(c.id)}">
      <div class="comite-card-row">
        <span class="comite-type-pill" style="background:${conf.bg};color:${conf.txt};border-color:${conf.accent};" title="${escapeHtml(conf.full)}">${escapeHtml(conf.label)}</span>
        <span class="comite-date"><i class="ti ti-calendar"></i>${escapeHtml(formatComDate(c.date))}</span>
        ${isPlanned ? `<span class="comite-state-pill planned"><i class="ti ti-clock"></i>Planifié</span>` : ''}
        ${pvSignedDate ? `<span class="comite-state-pill signed"><i class="ti ti-check"></i>PV signé le ${escapeHtml(pvSignedDate)}</span>` : ''}
        ${!isPlanned && !pvSignedDate && c.doc_name ? `<span class="comite-doc-name">${escapeHtml(c.doc_name)}</span>` : ''}
        ${!isPlanned && !pvSignedDate && !c.doc_name ? '<span class="comite-doc-name comite-doc-empty">Aucun document joint</span>' : ''}
        <div class="comite-card-actions">
          ${pvDocUrl ? `<button class="comite-action-btn" onclick="openPdfPreview('${escapeHtml(c.doc_name || 'PV.pdf')}', ${JSON.stringify(pvDocUrl)})" title="Voir le PV signé"><i class="ti ti-eye"></i></button>` : (c.doc_data_url ? `<button class="comite-action-btn" onclick="openPdfPreview('${escapeHtml(c.doc_name || 'document.pdf')}', findComite('${escapeHtml(c.id)}').comite.doc_data_url)" title="Prévisualiser"><i class="ti ti-eye"></i></button>` : '')}
          ${c.lien_sharepoint ? `<a class="comite-action-btn" href="${escapeHtml(c.lien_sharepoint)}" target="_blank" rel="noopener" title="Ouvrir sur SharePoint"><i class="ti ti-cloud"></i></a>` : ''}
          ${!wf && c.doc_data_url ? `<button class="comite-action-btn comite-submit-btn" onclick="submitComiteForValidation('${escapeHtml(c.id)}')" title="Soumettre pour validation"><i class="ti ti-file-certificate"></i></button>` : ''}
        </div>
      </div>
      ${wf && !wfApproved ? (() => {
        const overall = computeWfOverallStatus(wf);
        const ovConf = wfStatusConfig(overall);
        const recipients = getWfRecipients(wf);
        const total = recipients.length;
        const approved = recipients.filter(r => r.status === 'approved').length;
        let detailNames = '';
        if (overall === 'refused') {
          const refusers = recipients.filter(r => r.status === 'refused');
          detailNames = refusers.map(r => `${escapeHtml(r.name)}${r.refused_reason ? ` (« ${escapeHtml(r.refused_reason)} »)` : ''}`).join(' · ');
        } else {
          const pending = recipients.filter(r => r.status === 'pending');
          detailNames = pending.map(r => escapeHtml(r.name)).join(' · ');
        }
        return `<div class="comite-wf-status wf-status-${ovConf.color}">
          <i class="ti ti-${ovConf.icon}"></i>
          <span><strong>${escapeHtml(ovConf.label)} ${approved}/${total}</strong> — ${detailNames}</span>
        </div>`;
      })() : ''}
    </div>
  `;
}

function addComite(opUid) {
  const op = DATA.find(o => o._uid === opUid);
  if (!op) return;
  if (!Array.isArray(op.comites)) op.comites = [];
  const newComite = {
    id: 'com-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
    type: 'CA',
    date: '',
    lien_sharepoint: '',
    doc_name: null,
    doc_data_url: null,
    doc_size: null,
    notes: '',
    statut: 'realise',
  };
  op.comites.push(newComite);
  persistNewComite(newComite, op);
  renderOpDetail();
  replaceTablerIcons();
}

function removeComite(opUid, comiteId) {
  const op = DATA.find(o => o._uid === opUid);
  if (!op || !Array.isArray(op.comites)) return;
  if (!confirm('Supprimer ce comité ?')) return;
  const toDelete = op.comites.find(c => c.id === comiteId);
  if (toDelete) persistComiteDelete(toDelete);
  op.comites = op.comites.filter(c => c.id !== comiteId);
  renderOpDetail();
  replaceTablerIcons();
}

function attachComiteFile(event, opUid, comiteId) {
  const file = event.target.files[0];
  if (!file) return;
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
    showToast('Seuls les fichiers PDF sont acceptés', 'alert-triangle');
    return;
  }
  const op = DATA.find(o => o._uid === opUid);
  if (!op || !Array.isArray(op.comites)) return;
  const c = op.comites.find(x => x.id === comiteId);
  if (!c) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    c.doc_name = file.name;
    c.doc_size = file.size;
    c.doc_data_url = e.target.result;
    persistComiteChange(c, op);
    showToast(`Document « ${file.name} » joint`, 'check');
    renderOpDetail();
    replaceTablerIcons();
  };
  reader.readAsDataURL(file);
}

// Wire up the edit inputs to save back into op.comites
// Called when an edit-input loses focus
function bindComiteEditInputs() {
  document.querySelectorAll('[data-comite-field]').forEach(el => {
    if (el.dataset.wired) return;
    el.dataset.wired = '1';
    const saveValue = () => {
      const cid = el.dataset.comiteId;
      const field = el.dataset.comiteField;
      const found = findComite(cid);
      if (!found) return;
      // Si c'est un input type=date, on convertit en DD/MM/YYYY pour stockage
      let value = el.value;
      if (el.type === 'date' && value) value = isoToFr(value);
      found.comite[field] = value;
      persistComiteChange(found.comite, found.op);
    };
    el.addEventListener('change', saveValue);
    el.addEventListener('blur', saveValue);
  });
}

// Submit a comité document for validation (creates a WORKFLOWS entry)
function submitComiteForValidation(comiteId) {
  const found = findComite(comiteId);
  if (!found) return;
  const { comite, op } = found;
  if (!comite.doc_data_url) {
    showToast('Joignez d\'abord un PDF au comité', 'alert-triangle');
    return;
  }
  const conf = comiteTypeConfig(comite.type);
  // Open the standard workflow modal pre-filled with the comité data
  openWfModalForComite(comite, op);
}

// Specialized modal that creates a WF and links it back to the comité
function openWfModalForComite(comite, op) {
  document.querySelectorAll('.wf-modal-backdrop').forEach(p => p.remove());

  const persons = [...new Set([...getAllPersons(), 'Aliette GENDRE'])].sort();
  const conf = comiteTypeConfig(comite.type);
  const defaultType = comite.type === 'CA' ? 'Note interne CA' : (comite.type === 'C2I' ? 'Note interne CA' : 'Bilan d\'opération');

  const backdrop = document.createElement('div');
  backdrop.className = 'wf-modal-backdrop';
  backdrop.innerHTML = `
    <div class="wf-modal">
      <div class="wf-modal-head">
        <i class="ti ti-file-certificate"></i>
        <span>Soumettre le PV du comité ${escapeHtml(conf.label)} pour validation</span>
        <button class="wf-modal-close" type="button">×</button>
      </div>
      <div class="wf-modal-body">
        <div class="wf-modal-file">
          <i class="ti ti-file-text"></i>
          <div class="wf-modal-file-info">
            <div class="wf-modal-filename">${escapeHtml(comite.doc_name || 'document.pdf')}</div>
            <div class="wf-modal-filesize">${formatFileSize(comite.doc_size)} · Comité ${escapeHtml(conf.label)} du ${escapeHtml(comite.date || '?')} — ${escapeHtml(op.display_name || '')}</div>
          </div>
          <button class="wf-modal-file-preview" type="button" id="wfModalPreviewBtn"><i class="ti ti-eye"></i>Prévisualiser</button>
        </div>

        <div class="wf-modal-field">
          <label>Type de document</label>
          <select id="wfFormType">
            ${getRef('types_document').map(t => `<option value="${escapeHtml(t)}"${t === defaultType ? ' selected' : ''}>${escapeHtml(t)}</option>`).join('')}
          </select>
        </div>

        <div class="wf-modal-field">
          <label>Validateur(s) — sélectionnez un ou plusieurs</label>
          <div class="wf-multi-recipients" id="wfMultiRecipients">
            ${persons.map(p => `
              <label class="wf-recipient-check">
                <input type="checkbox" value="${escapeHtml(p)}"${p === 'Aliette GENDRE' ? ' checked' : ''} />
                <span>${escapeHtml(p)}</span>
              </label>
            `).join('')}
          </div>
        </div>

        <div class="wf-modal-field">
          <label>Message au validateur (optionnel)</label>
          <textarea id="wfFormMessage" rows="3" placeholder="Ex: Merci de valider le PV avant diffusion.">Validation du PV ${comite.type} du ${comite.date || '?'} pour l'opération ${op.code || op.display_name}.</textarea>
        </div>
      </div>
      <div class="wf-modal-foot">
        <button class="btn-small" type="button" id="wfFormCancel">Annuler</button>
        <button class="btn-small btn-primary" type="button" id="wfFormSend"><i class="ti ti-arrow-left" style="transform:rotate(180deg);"></i>Envoyer pour validation</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  replaceTablerIcons(backdrop);

  const close = () => backdrop.remove();
  backdrop.querySelector('.wf-modal-close').addEventListener('click', close);
  backdrop.querySelector('#wfFormCancel').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });

  backdrop.querySelector('#wfModalPreviewBtn').addEventListener('click', () => {
    openPdfPreview(comite.doc_name || 'document.pdf', comite.doc_data_url);
  });

  backdrop.querySelector('#wfFormSend').addEventListener('click', () => {
    const checks = backdrop.querySelectorAll('#wfMultiRecipients input[type="checkbox"]:checked');
    const recipientNames = [...checks].map(c => c.value);
    if (recipientNames.length === 0) {
      showToast('Sélectionnez au moins un validateur', 'alert-triangle');
      return;
    }
    const wfId = 'wf-' + Date.now();
    const wf = {
      id: wfId,
      doc_name: comite.doc_name,
      doc_type: backdrop.querySelector('#wfFormType').value,
      doc_size: comite.doc_size,
      doc_data_url: comite.doc_data_url,
      op_uid: op._uid,
      sender: 'Bastien MERCIER',
      recipients: recipientNames.map(name => ({
        name,
        status: 'pending',
        responded_at: null,
        refused_reason: null,
      })),
      status: 'pending',
      sent_at: new Date().toISOString(),
      message: backdrop.querySelector('#wfFormMessage').value.trim() || null,
      comite_id: comite.id,
    };
    WORKFLOWS.push(wf);
    // On crée d'abord le workflow en DB pour avoir son _supabase_id, puis on lie le comité
    persistNewWorkflow(wf).then(() => {
      comite.submitted_wf_id = wfId;
      persistComiteChange(comite, op);
    });
    comite.submitted_wf_id = wfId; // mémoire locale immédiate
    const recipientLabel = recipientNames.length === 1
      ? recipientNames[0]
      : `${recipientNames.length} validateurs`;
    showToast(`PV du comité ${comite.type} soumis à ${recipientLabel}`, 'check');
    close();
    renderOpDetail();
    replaceTablerIcons();
  });
}

// =========== Planification de comités ===========

// Open modal to plan a new comité (multi-ops)
function openPlanComiteModal(existingPlanningId) {
  document.querySelectorAll('.wf-modal-backdrop').forEach(p => p.remove());

  // If editing an existing planning, gather its current state
  let existing = null;
  if (existingPlanningId) {
    const members = [];
    DATA.forEach(op => {
      if (!Array.isArray(op.comites)) return;
      op.comites.forEach(c => { if (c.planning_id === existingPlanningId) members.push({ comite: c, op }); });
    });
    if (members.length > 0) {
      existing = {
        planning_id: existingPlanningId,
        type: members[0].comite.type,
        date: members[0].comite.date,
        lieu: members[0].comite.lieu || '',
        notes: members[0].comite.notes || '',
        opUids: members.map(m => m.op._uid),
      };
    }
  }

  const ops = DATA.filter(o => !o.deleted && inScope(o)).sort((a, b) => {
    const na = (a.display_name || a.code || '').toLowerCase();
    const nb = (b.display_name || b.code || '').toLowerCase();
    return na.localeCompare(nb, 'fr');
  });
  const selectedSet = new Set(existing ? existing.opUids : []);

  const backdrop = document.createElement('div');
  backdrop.className = 'wf-modal-backdrop';
  backdrop.innerHTML = `
    <div class="wf-modal wf-modal-large">
      <div class="wf-modal-head">
        <i class="ti ti-calendar"></i>
        <span>${existing ? 'Modifier la planification de comité' : 'Planifier un nouveau comité'}</span>
        <button class="wf-modal-close" type="button">×</button>
      </div>
      <div class="wf-modal-body">
        <div class="wf-modal-row">
          <div class="wf-modal-field">
            <label>Type de comité</label>
            <select id="planFormType">
              ${getRef('types_comite').map(t => `<option value="${escapeHtml(t)}"${existing && existing.type === t ? ' selected' : ''}>${escapeHtml(t)} — ${escapeHtml(comiteTypeConfig(t).full)}</option>`).join('')}
            </select>
          </div>
          <div class="wf-modal-field">
            <label>Date prévue</label>
            <input type="date" id="planFormDate" value="${escapeHtml(existing ? frToIso(existing.date) : '')}" />
          </div>
        </div>

        <div class="wf-modal-field">
          <label>Ordre du jour / Notes (optionnel)</label>
          <textarea id="planFormNotes" rows="2" placeholder="Points à l'ordre du jour, contexte…">${escapeHtml(existing ? existing.notes : '')}</textarea>
        </div>

        <div class="wf-modal-field">
          <label>Opérations à inscrire à l'ordre du jour <span class="plan-ops-count" id="planOpsCount">0</span></label>
          <div class="plan-ops-search">
            <input type="text" id="planOpsSearch" placeholder="Filtrer les opérations par nom, code, commune…" />
          </div>
          <div class="plan-ops-list" id="planOpsList"></div>
        </div>
      </div>
      <div class="wf-modal-foot">
        <button class="btn-small" type="button" id="planFormCancel">Annuler</button>
        <button class="btn-small btn-primary" type="button" id="planFormSave"><i class="ti ti-check"></i>${existing ? 'Enregistrer les modifications' : 'Planifier le comité'}</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  replaceTablerIcons(backdrop);

  const opsList = backdrop.querySelector('#planOpsList');
  const countEl = backdrop.querySelector('#planOpsCount');
  const searchEl = backdrop.querySelector('#planOpsSearch');

  function renderPlanOps() {
    const q = (searchEl.value || '').trim().toLowerCase();
    const filtered = q
      ? ops.filter(o => [o.code, o.display_name, o.commune].filter(Boolean).join(' ').toLowerCase().includes(q))
      : ops;
    opsList.innerHTML = filtered.map(o => `
      <label class="plan-op-check">
        <input type="checkbox" data-op-uid="${escapeHtml(o._uid)}" ${selectedSet.has(o._uid) ? 'checked' : ''} />
        <span class="plan-op-code">${escapeHtml(o.code || '?')}</span>
        <span class="plan-op-name">${escapeHtml(o.display_name || '')}</span>
        <span class="plan-op-phase" style="background:${PHASE_COLORS[o.phase_actuelle || 'Montage'].bg};color:${PHASE_COLORS[o.phase_actuelle || 'Montage'].text};">${escapeHtml(o.phase_actuelle || 'Montage')}</span>
      </label>
    `).join('');
    countEl.textContent = `${selectedSet.size} sélectionnée${selectedSet.size > 1 ? 's' : ''}`;
    opsList.querySelectorAll('input[type="checkbox"]').forEach(cb => {
      cb.addEventListener('change', () => {
        const uid = cb.dataset.opUid;
        if (cb.checked) selectedSet.add(uid); else selectedSet.delete(uid);
        countEl.textContent = `${selectedSet.size} sélectionnée${selectedSet.size > 1 ? 's' : ''}`;
      });
    });
  }
  renderPlanOps();
  searchEl.addEventListener('input', renderPlanOps);

  const close = () => backdrop.remove();
  backdrop.querySelector('.wf-modal-close').addEventListener('click', close);
  backdrop.querySelector('#planFormCancel').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });

  backdrop.querySelector('#planFormSave').addEventListener('click', () => {
    const type = backdrop.querySelector('#planFormType').value;
    const isoDate = backdrop.querySelector('#planFormDate').value.trim();
    const date = isoToFr(isoDate); // converti en DD/MM/YYYY pour stockage
    const notes = backdrop.querySelector('#planFormNotes').value.trim();
    if (!date) {
      showToast('Saisis une date pour le comité', 'alert-triangle');
      return;
    }
    if (selectedSet.size === 0) {
      showToast('Sélectionne au moins une opération', 'alert-triangle');
      return;
    }

    const planningId = existing ? existing.planning_id : ('plan-' + Date.now());

    // If editing: remove old planned entries (only if they have no PV — protect realized ones)
    if (existing) {
      DATA.forEach(op => {
        if (!Array.isArray(op.comites)) return;
        const toDelete = op.comites.filter(c => c.planning_id === planningId && isComitePlanifie(c));
        toDelete.forEach(c => persistComiteDelete(c));
        op.comites = op.comites.filter(c => !(c.planning_id === planningId && isComitePlanifie(c)));
      });
    }

    // Create/update entries on each selected op
    const newComites = []; // [{ comite, op }] pour persistance
    selectedSet.forEach(uid => {
      const op = DATA.find(o => o._uid === uid);
      if (!op) return;
      if (!Array.isArray(op.comites)) op.comites = [];
      // Skip if already realized (PV joint) under same planning_id
      const existingRealized = op.comites.find(c => c.planning_id === planningId && !isComitePlanifie(c));
      if (existingRealized) return;
      // Add planned entry
      const newComite = {
        id: 'com-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
        type, date, lieu: '', notes,
        planning_id: planningId,
        statut: 'planifie',
        lien_sharepoint: '',
        doc_name: null,
        doc_data_url: null,
        doc_size: null,
      };
      op.comites.push(newComite);
      newComites.push({ comite: newComite, op });
    });
    // Persistance asynchrone (non bloquant pour l'UI)
    newComites.forEach(({ comite, op }) => persistNewComite(comite, op));

    showToast(existing ? 'Planification mise à jour' : `Comité ${type} planifié sur ${selectedSet.size} opération${selectedSet.size > 1 ? 's' : ''}`, 'check');
    close();
    renderComitesList();
  });
}

// Cancel a planned comité (remove all its planned entries)
function cancelPlannedComite(planningId) {
  if (!confirm('Annuler cette planification ? Les comités déjà réalisés (avec PV joint) seront conservés.')) return;
  let count = 0;
  DATA.forEach(op => {
    if (!Array.isArray(op.comites)) return;
    const toDelete = op.comites.filter(c => c.planning_id === planningId && isComitePlanifie(c));
    toDelete.forEach(c => persistComiteDelete(c));
    op.comites = op.comites.filter(c => !(c.planning_id === planningId && isComitePlanifie(c)));
    count += toDelete.length;
  });
  showToast(`${count} planification${count > 1 ? 's' : ''} annulée${count > 1 ? 's' : ''}`, 'trash');
  renderComitesList();
}

// Attach a PV to a planned comité → converts to "realised"
function attachPvToComite(comiteId) {
  const found = findComite(comiteId);
  if (!found) return;
  const { comite } = found;
  // Trigger a file picker
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'application/pdf,.pdf';
  input.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      showToast('Seuls les fichiers PDF sont acceptés', 'alert-triangle');
      return;
    }
    const reader = new FileReader();
    reader.onload = (ev) => {
      comite.doc_name = file.name;
      comite.doc_size = file.size;
      comite.doc_data_url = ev.target.result;
      comite.statut = 'realise'; // clôture la planification pour cette op
      persistComiteChange(comite, found.op);
      showToast(`PV joint, comité clôturé pour cette opération`, 'check');
      renderComitesList();
      if (selectedOpCode === found.op._uid) {
        renderOpDetail();
        replaceTablerIcons();
      }
    };
    reader.readAsDataURL(file);
  });
  input.click();
}

// =========== End planification ===========
// =========== Comités tab (global view) ===========
let comFilterType = 'all';
let comFilterStatut = 'all'; // 'all' | 'planifie' | 'realise'
let comSearch = '';

function comitesCalNav(delta) {
  if (!comitesCalMonth) comitesCalMonth = new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  comitesCalMonth = new Date(comitesCalMonth.getFullYear(), comitesCalMonth.getMonth() + delta, 1);
  renderComitesCalendar();
}

function renderComitesCalendar() {
  const host = document.getElementById('comCalendar');
  if (!host) return;
  if (!comitesCalMonth) comitesCalMonth = new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  const y = comitesCalMonth.getFullYear(), m = comitesCalMonth.getMonth();
  const monthNames = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
  const byDay = {}; const monthList = [];
  getAllComites().forEach(({ comite, op }) => {
    const d = ctrlParseFr(comite.date);
    if (!d || d.getFullYear() !== y || d.getMonth() !== m) return;
    (byDay[d.getDate()] = byDay[d.getDate()] || []).push({ comite, op, d });
    monthList.push({ comite, op, d });
  });
  monthList.sort((a, b) => a.d - b.d);
  const firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
  const daysInMonth = new Date(y, m + 1, 0).getDate();
  const today = new Date(); today.setHours(0, 0, 0, 0);
  let cells = ['L','M','M','J','V','S','D'].map(d => `<div class="com-cal-dow">${d}</div>`).join('');
  for (let i = 0; i < firstDow; i++) cells += '<div class="com-cal-day com-cal-empty"></div>';
  for (let day = 1; day <= daysInMonth; day++) {
    const items = byDay[day] || [];
    const isToday = new Date(y, m, day).getTime() === today.getTime();
    const tags = items.map(it => {
      const conf = comiteTypeConfig(it.comite.type);
      return `<span class="com-cal-tag" style="border-left:3px solid ${conf.accent};background:${conf.bg};color:${conf.txt};" title="${escapeHtml(conf.full)} · ${escapeHtml(it.op.display_name || it.op.code || '')}${it.comite.lieu ? ' · ' + escapeHtml(it.comite.lieu) : ''}">${escapeHtml(it.op.display_name || it.op.code || '?')}</span>`;
    }).join('');
    cells += `<div class="com-cal-day${items.length ? ' has-com' : ''}${isToday ? ' today' : ''}"><span class="com-cal-num">${day}</span><div class="com-cal-tags">${tags}</div></div>`;
  }
  const listHtml = monthList.length
    ? monthList.map(it => {
        const conf = comiteTypeConfig(it.comite.type);
        const planif = isComitePlanifie(it.comite);
        return `<div class="com-cal-li"><span class="com-cal-li-date">${escapeHtml(it.comite.date)}</span><span class="com-cal-li-badge" style="background:${conf.bg};color:${conf.txt};">${escapeHtml(conf.label)}</span><span class="com-cal-li-op">${escapeHtml(it.op.display_name || it.op.code || '')}</span>${it.comite.lieu ? `<span class="com-cal-li-lieu"><i class="ti ti-map-pin"></i>${escapeHtml(it.comite.lieu)}</span>` : ''}${planif ? '<span class="ctrl-chip ctrl-chip-soon">Planifié</span>' : '<span class="ctrl-chip ctrl-chip-ok">Réalisé</span>'}</div>`;
      }).join('')
    : '<div class="com-cal-empty-msg">Aucun comité ce mois-ci.</div>';
  host.innerHTML = `
    <div class="com-cal">
      <div class="com-cal-head">
        <button class="com-cal-nav" onclick="comitesCalNav(-1)" title="Mois précédent">&lsaquo;</button>
        <div class="com-cal-title">${monthNames[m]} ${y}</div>
        <button class="com-cal-nav" onclick="comitesCalNav(1)" title="Mois suivant">&rsaquo;</button>
      </div>
      <div class="com-cal-grid">${cells}</div>
    </div>`;
  replaceTablerIcons(host);
}

function renderComitesTab() {
  const container = document.getElementById('comitesContent');
  if (!container) return;

  // Only render the shell once. The list and counts are refreshed by renderComitesList().
  if (!container.dataset.shellRendered) {
    container.innerHTML = `
      <div class="com-toolbar">
        <div class="wf-dropzone wf-dropzone-com" id="comDropzone">
          <i class="ti ti-cloud"></i>
          <div class="wf-dropzone-title">Glissez un PV ou document de comité ici</div>
          <div class="wf-dropzone-sub">ou <button class="wf-dropzone-browse" id="comBrowseBtn" type="button">parcourir vos fichiers</button> — vous l'associerez à une opération</div>
          <input type="file" id="comFileInput" accept="application/pdf,.pdf" style="display:none;" />
        </div>
        <button class="com-plan-btn" id="comPlanBtn" type="button">
          <i class="ti ti-calendar"></i>
          <span>
            <span class="com-plan-btn-title">Planifier un comité</span>
            <span class="com-plan-btn-sub">Anticiper plusieurs mois à l'avance · multi-ops</span>
          </span>
        </button>
      </div>

      <div id="comCalendar"></div>

      <div class="wf-filter-bar">
        <div class="wf-status-tabs" id="comStatusTabs">
          <button class="wf-status-tab" data-com-filter="all">Tous <span class="wf-status-count" id="comCount-all">0</span></button>
          <button class="wf-status-tab" data-com-filter="CA">CA <span class="wf-status-count" id="comCount-CA">0</span></button>
          <button class="wf-status-tab" data-com-filter="C2I">C2I <span class="wf-status-count" id="comCount-C2I">0</span></button>
          <button class="wf-status-tab" data-com-filter="Revue">Revues <span class="wf-status-count" id="comCount-Revue">0</span></button>
          <span class="wf-status-tab-sep"></span>
          <button class="wf-status-tab" data-com-status="all">Tous statuts</button>
          <button class="wf-status-tab" data-com-status="planifie">Planifiés <span class="wf-status-count" id="comCount-planifie">0</span></button>
          <button class="wf-status-tab" data-com-status="realise">Réalisés <span class="wf-status-count" id="comCount-realise">0</span></button>
        </div>
        <input type="text" class="synth-filter-input wf-search" id="comSearchInput" placeholder="Recherche : opération, code, document…">
      </div>

      <div id="comListContainer"></div>
    `;
    container.dataset.shellRendered = '1';
    initComitesTabEvents();
  }
  renderComitesList();
  replaceTablerIcons(container);
}

// Render only the dynamic part (counts + list) — preserves the search input focus
function renderComitesList() {
  const listContainer = document.getElementById('comListContainer');
  if (!listContainer) return;

  renderComitesCalendar();
  const all = getAllComites();

  // Counts by type
  const counts = { all: all.length, CA: 0, C2I: 0, Revue: 0 };
  // Counts by statut
  const countsByStatut = { planifie: 0, realise: 0 };
  all.forEach(({ comite }) => {
    if (counts[comite.type] != null) counts[comite.type]++;
    if (isComitePlanifie(comite)) countsByStatut.planifie++;
    else countsByStatut.realise++;
  });

  // Update counts in place
  ['all', 'CA', 'C2I', 'Revue'].forEach(k => {
    const el = document.getElementById('comCount-' + k);
    if (el) el.textContent = counts[k];
  });
  ['planifie', 'realise'].forEach(k => {
    const el = document.getElementById('comCount-' + k);
    if (el) el.textContent = countsByStatut[k];
  });
  // Active filter buttons
  document.querySelectorAll('[data-com-filter]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.comFilter === comFilterType);
  });
  document.querySelectorAll('[data-com-status]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.comStatus === comFilterStatut);
  });

  // Filter
  const q = (comSearch || '').trim().toLowerCase();
  const filtered = all.filter(({ comite, op }) => {
    if (comFilterType !== 'all' && comite.type !== comFilterType) return false;
    if (comFilterStatut === 'planifie' && !isComitePlanifie(comite)) return false;
    if (comFilterStatut === 'realise' && isComitePlanifie(comite)) return false;
    if (q) {
      const hay = [comite.doc_name, comite.date, op.code, op.display_name, comite.type].filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  // Group by planning_id so a multi-ops comité shows as one card
  const groups = new Map();
  filtered.forEach(({ comite, op }) => {
    const key = comite.planning_id || ('single-' + comite.id);
    if (!groups.has(key)) {
      groups.set(key, {
        planning_id: comite.planning_id || null,
        type: comite.type,
        date: comite.date,
        lieu: comite.lieu || null,
        statut_main: isComitePlanifie(comite) ? 'planifie' : 'realise',
        members: [], // { comite, op }
      });
    }
    groups.get(key).members.push({ comite, op });
  });

  const groupList = [...groups.values()];

  // Sort: futurs en premier (par date croissante), puis passés (par date décroissante)
  const today = new Date(); today.setHours(0, 0, 0, 0);
  groupList.forEach(g => {
    const d = parseDateStr(g.date);
    g._date = d || new Date(0);
    g._isFuture = d ? d.getTime() >= today.getTime() : false;
  });
  groupList.sort((a, b) => {
    // Future first (ascending), then past (descending)
    if (a._isFuture && !b._isFuture) return -1;
    if (!a._isFuture && b._isFuture) return 1;
    if (a._isFuture && b._isFuture) return a._date - b._date;
    return b._date - a._date;
  });

  listContainer.innerHTML = groupList.length === 0 ? `
    <div class="wf-empty">
      <i class="ti ti-users"></i>
      <p>Aucun comité ${comFilterType !== 'all' ? `de type "${comFilterType}"` : ''}${comFilterStatut !== 'all' ? ` au statut "${comFilterStatut === 'planifie' ? 'Planifié' : 'Réalisé'}"` : ''} à afficher.</p>
      <p style="font-size:12px;color:var(--text-tertiary);font-style:italic;">Glissez un PV ou planifiez un comité depuis le bouton en haut.</p>
    </div>
  ` : `
    <div class="com-list">
      ${groupList.map(g => renderComiteGroup(g)).join('')}
    </div>
  `;
  replaceTablerIcons(listContainer);
}

// Render a comité (group of members if multi-ops, single if standalone)
function renderComiteGroup(g) {
  const conf = comiteTypeConfig(g.type);
  const isPlan = g.statut_main === 'planifie';
  const isMultiOp = g.members.length > 1;
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const d = parseDateStr(g.date);
  let dateBadge = '';
  if (d && isPlan) {
    const days = Math.floor((d.getTime() - today.getTime()) / 86400000);
    if (days >= 0) dateBadge = `<span class="com-row-future">dans ${days}j</span>`;
    else dateBadge = `<span class="com-row-past">il y a ${-days}j</span>`;
  }

  // Status pill
  const statutPill = isPlan
    ? `<span class="com-statut-pill com-statut-planifie"><i class="ti ti-calendar"></i>PLANIFIÉ</span>`
    : `<span class="com-statut-pill com-statut-realise"><i class="ti ti-check"></i>RÉALISÉ</span>`;

  // For multi-op planned comités: render as a grouped block
  if (isMultiOp) {
    return `
      <div class="com-group com-group-${isPlan ? 'planifie' : 'realise'} com-row-${conf.color}">
        <div class="com-group-head">
          <span class="comite-type-pill" style="background:${conf.bg};color:${conf.txt};border-color:${conf.accent};" title="${escapeHtml(conf.full)}">${escapeHtml(conf.label)}</span>
          ${statutPill}
          <span class="com-row-date"><i class="ti ti-calendar"></i>${escapeHtml(g.date || '?')}</span>
          ${dateBadge}
          ${g.lieu ? `<span class="com-group-lieu"><i class="ti ti-map-pin"></i>${escapeHtml(g.lieu)}</span>` : ''}
          <span class="com-group-count">${g.members.length} opération${g.members.length > 1 ? 's' : ''}</span>
          ${isPlan ? `<div class="com-group-actions">
            <button class="comite-action-btn" data-com-action="edit-plan" data-com-planning-id="${escapeHtml(g.planning_id)}" title="Modifier la planification"><i class="ti ti-pencil"></i></button>
            <button class="comite-action-btn comite-submit-btn" data-com-action="add-pv" data-com-planning-id="${escapeHtml(g.planning_id)}" title="Joindre le PV (clôture le comité)"><i class="ti ti-cloud"></i></button>
            <button class="comite-action-btn" data-com-action="cancel-plan" data-com-planning-id="${escapeHtml(g.planning_id)}" title="Annuler la planification"><i class="ti ti-x"></i></button>
          </div>` : ''}
        </div>
        <div class="com-group-ops">
          ${g.members.map(({ comite, op }) => renderComiteMemberRow(comite, op, isPlan)).join('')}
        </div>
      </div>
    `;
  }

  // Single comité (legacy or unique-op planned)
  const { comite, op } = g.members[0];
  return renderComiteRowGlobal(comite, op);
}

function renderComiteMemberRow(c, op, isPlan) {
  const wf = c.submitted_wf_id ? WORKFLOWS.find(w => w.id === c.submitted_wf_id) : null;
  let wfChip = '';
  if (wf) {
    const overall = computeWfOverallStatus(wf);
    const ovConf = wfStatusConfig(overall);
    const recipients = getWfRecipients(wf);
    const approved = recipients.filter(r => r.status === 'approved').length;
    wfChip = `<span class="com-row-wf-mini wf-status-${ovConf.color}"><i class="ti ti-${ovConf.icon}"></i>${escapeHtml(ovConf.label)} ${approved}/${recipients.length}</span>`;
  }
  return `
    <div class="com-group-op-row">
      <a href="#" class="com-row-op-link" data-com-op-uid="${escapeHtml(op._uid)}"><strong>${escapeHtml(op.code || '')}</strong> · ${escapeHtml(op.display_name || '')}</a>
      ${c.doc_name ? `<span class="com-group-op-doc">${escapeHtml(c.doc_name)}</span>` : (isPlan ? '<span class="com-group-op-doc com-group-op-doc-empty">PV à venir</span>' : '<span class="com-group-op-doc com-group-op-doc-empty">Aucun document</span>')}
      ${wfChip}
      <div class="com-group-op-actions">
        ${c.doc_data_url ? `<button class="comite-action-btn" onclick="openPdfPreview('${escapeHtml(c.doc_name || 'document.pdf')}', findComite('${escapeHtml(c.id)}').comite.doc_data_url)" title="Prévisualiser"><i class="ti ti-eye"></i></button>` : ''}
        ${c.lien_sharepoint ? `<a class="comite-action-btn" href="${escapeHtml(c.lien_sharepoint)}" target="_blank" rel="noopener" title="SharePoint"><i class="ti ti-cloud"></i></a>` : ''}
        ${!wf && c.doc_data_url ? `<button class="comite-action-btn comite-submit-btn" onclick="submitComiteForValidation('${escapeHtml(c.id)}')" title="Soumettre pour validation"><i class="ti ti-file-certificate"></i></button>` : ''}
      </div>
    </div>
  `;
}

function renderComiteRowGlobal(c, op) {
  const conf = comiteTypeConfig(c.type);
  const isPlan = isComitePlanifie(c);
  const wf = c.submitted_wf_id ? WORKFLOWS.find(w => w.id === c.submitted_wf_id) : null;
  let wfChip = '';
  if (wf) {
    const overall = computeWfOverallStatus(wf);
    const ovConf = wfStatusConfig(overall);
    const recipients = getWfRecipients(wf);
    const total = recipients.length;
    let detailNames = '';
    if (overall === 'approved') {
      // All approved — list all approvers
      detailNames = recipients.map(r => escapeHtml(r.name)).join(' · ');
    } else if (overall === 'refused') {
      // Show refusers (with reason on tooltip)
      const refusers = recipients.filter(r => r.status === 'refused');
      detailNames = refusers.map(r => escapeHtml(r.name)).join(' · ');
    } else {
      // Pending — show who's still pending
      const pending = recipients.filter(r => r.status === 'pending');
      detailNames = pending.map(r => escapeHtml(r.name)).join(' · ');
    }
    const counters = `${recipients.filter(r => r.status === 'approved').length}/${total}`;
    wfChip = `<div class="com-row-wf wf-status-${ovConf.color}"><i class="ti ti-${ovConf.icon}"></i><strong>${escapeHtml(ovConf.label)} ${counters}</strong> — ${detailNames}</div>`;
  }
  const statutPill = isPlan
    ? `<span class="com-statut-pill com-statut-planifie"><i class="ti ti-calendar"></i>PLANIFIÉ</span>`
    : `<span class="com-statut-pill com-statut-realise"><i class="ti ti-check"></i>RÉALISÉ</span>`;
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const d = parseDateStr(c.date);
  let dateBadge = '';
  if (d && isPlan) {
    const days = Math.floor((d.getTime() - today.getTime()) / 86400000);
    if (days >= 0) dateBadge = `<span class="com-row-future">dans ${days}j</span>`;
    else dateBadge = `<span class="com-row-past">il y a ${-days}j</span>`;
  }
  return `
    <div class="com-row com-row-${conf.color}${isPlan ? ' com-row-planifie' : ''}">
      <span class="comite-type-pill" style="background:${conf.bg};color:${conf.txt};border-color:${conf.accent};" title="${escapeHtml(conf.full)}">${escapeHtml(conf.label)}</span>
      ${statutPill}
      <span class="com-row-date"><i class="ti ti-calendar"></i>${escapeHtml(formatComDate(c.date))}</span>
      ${dateBadge}
      <div class="com-row-main">
        <div class="com-row-op"><strong>${escapeHtml(op.code || '')}</strong> · <a href="#" class="com-row-op-link" data-com-op-uid="${escapeHtml(op._uid)}">${escapeHtml(op.display_name || '')}</a></div>
        <div class="com-row-doc">${c.doc_name ? escapeHtml(c.doc_name) : (isPlan ? '<em>PV à venir</em>' : '<em>Aucun document joint</em>')}</div>
        ${wfChip}
      </div>
      <div class="com-row-actions">
        ${c.doc_data_url ? `<button class="comite-action-btn" onclick="openPdfPreview('${escapeHtml(c.doc_name || 'document.pdf')}', findComite('${escapeHtml(c.id)}').comite.doc_data_url)" title="Prévisualiser"><i class="ti ti-eye"></i></button>` : ''}
        ${c.lien_sharepoint ? `<a class="comite-action-btn" href="${escapeHtml(c.lien_sharepoint)}" target="_blank" rel="noopener" title="SharePoint"><i class="ti ti-cloud"></i></a>` : ''}
        ${isPlan ? `<button class="comite-action-btn comite-submit-btn" onclick="attachPvToComite('${escapeHtml(c.id)}')" title="Joindre le PV (clôture le comité)"><i class="ti ti-cloud"></i></button>` : ''}
        ${!wf && c.doc_data_url && !isPlan ? `<button class="comite-action-btn comite-submit-btn" onclick="submitComiteForValidation('${escapeHtml(c.id)}')" title="Soumettre pour validation"><i class="ti ti-file-certificate"></i></button>` : ''}
      </div>
    </div>
  `;
}

function initComitesTabEvents() {
  // Type filter tabs (CA / C2I / Revue / Tous)
  document.querySelectorAll('[data-com-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      comFilterType = btn.dataset.comFilter;
      renderComitesList();
    });
  });
  // Statut filter tabs (Planifié / Réalisé / Tous)
  document.querySelectorAll('[data-com-status]').forEach(btn => {
    btn.addEventListener('click', () => {
      comFilterStatut = btn.dataset.comStatus;
      renderComitesList();
    });
  });
  // Plan button
  const planBtn = document.getElementById('comPlanBtn');
  if (planBtn) {
    planBtn.addEventListener('click', () => openPlanComiteModal(null));
  }
  // Search — keeps focus because we only re-render the list
  const search = document.getElementById('comSearchInput');
  if (search) {
    search.addEventListener('input', (e) => { comSearch = e.target.value; renderComitesList(); });
  }
  // Delegation on the list container (op links + group actions)
  const listContainer = document.getElementById('comListContainer');
  if (listContainer) {
    listContainer.addEventListener('click', (e) => {
      // Op link
      const a = e.target.closest('[data-com-op-uid]');
      if (a) {
        e.preventDefault();
        const uid = a.dataset.comOpUid;
        selectOp(uid);
        document.querySelectorAll('.topnav-tab').forEach(t => t.classList.remove('active'));
        document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
        document.querySelector('[data-view="operations"]').classList.add('active');
        document.getElementById('view-operations').classList.add('active');
        return;
      }
      // Group action (edit planning, cancel, attach PV multi)
      const actionBtn = e.target.closest('[data-com-action]');
      if (actionBtn) {
        e.preventDefault();
        e.stopPropagation();
        const action = actionBtn.dataset.comAction;
        const planningId = actionBtn.dataset.comPlanningId;
        if (action === 'edit-plan') openPlanComiteModal(planningId);
        else if (action === 'cancel-plan') cancelPlannedComite(planningId);
        else if (action === 'add-pv') {
          // For multi-op planned comités: prompt user to pick one specific op
          // (simpler than handling all at once in mockup)
          alert('Pour les comités multi-ops, le PV doit être joint individuellement pour chaque opération depuis la liste.\n\nCliquez sur l\'icône ☁ à côté de l\'opération concernée.');
        }
        return;
      }
    });
  }
  // Drop zone
  const zone = document.getElementById('comDropzone');
  if (zone) {
    zone.addEventListener('dragover', (e) => { e.preventDefault(); zone.classList.add('wf-dropzone-active'); });
    zone.addEventListener('dragleave', () => zone.classList.remove('wf-dropzone-active'));
    zone.addEventListener('drop', (e) => {
      e.preventDefault();
      zone.classList.remove('wf-dropzone-active');
      handleComFile(e.dataTransfer.files[0]);
    });
  }
  const browse = document.getElementById('comBrowseBtn');
  const fileInput = document.getElementById('comFileInput');
  if (browse && fileInput) {
    browse.addEventListener('click', () => fileInput.click());
    fileInput.addEventListener('change', (e) => {
      handleComFile(e.target.files[0]);
      fileInput.value = '';
    });
  }
}

function handleComFile(file) {
  if (!file) return;
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
    showToast('Seuls les fichiers PDF sont acceptés', 'alert-triangle');
    return;
  }
  const reader = new FileReader();
  reader.onload = (e) => openComiteCreationModal(file.name, file.size, e.target.result);
  reader.readAsDataURL(file);
}

// Modal: choose op + type + date, attach the file, create the comité
function openComiteCreationModal(docName, docSize, dataUrl) {
  document.querySelectorAll('.wf-modal-backdrop').forEach(p => p.remove());

  const opOptions = DATA.filter(o => !o.deleted).map(o =>
    `<option value="${escapeHtml(o._uid)}">${escapeHtml(o.code || '?')} · ${escapeHtml(o.display_name || '')}</option>`
  ).join('');

  const backdrop = document.createElement('div');
  backdrop.className = 'wf-modal-backdrop';
  backdrop.innerHTML = `
    <div class="wf-modal">
      <div class="wf-modal-head">
        <i class="ti ti-users"></i>
        <span>Nouveau document de comité</span>
        <button class="wf-modal-close" type="button">×</button>
      </div>
      <div class="wf-modal-body">
        <div class="wf-modal-file">
          <i class="ti ti-file-text"></i>
          <div class="wf-modal-file-info">
            <div class="wf-modal-filename">${escapeHtml(docName)}</div>
            <div class="wf-modal-filesize">${formatFileSize(docSize)}</div>
          </div>
          <button class="wf-modal-file-preview" type="button" id="comModalPreviewBtn"><i class="ti ti-eye"></i>Prévisualiser</button>
        </div>

        <div class="wf-modal-field">
          <label>Type de comité</label>
          <select id="comFormType">
            ${getRef('types_comite').map(t => `<option value="${escapeHtml(t)}">${escapeHtml(comiteTypeConfig(t).label)} — ${escapeHtml(comiteTypeConfig(t).full)}</option>`).join('')}
          </select>
        </div>

        <div class="wf-modal-field">
          <label>Date du comité</label>
          <input type="text" id="comFormDate" placeholder="JJ/MM/AAAA" />
        </div>

        <div class="wf-modal-field">
          <label>Opération liée</label>
          <select id="comFormOp">
            <option value="">— Sélectionner une opération —</option>
            ${opOptions}
          </select>
        </div>
      </div>
      <div class="wf-modal-foot">
        <button class="btn-small" type="button" id="comFormCancel">Annuler</button>
        <button class="btn-small btn-primary" type="button" id="comFormSave"><i class="ti ti-check"></i>Créer le comité</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  replaceTablerIcons(backdrop);

  // Pre-fill op if currently selected
  if (selectedOpCode) {
    const opSelect = backdrop.querySelector('#comFormOp');
    if (opSelect) opSelect.value = selectedOpCode;
  }

  const close = () => backdrop.remove();
  backdrop.querySelector('.wf-modal-close').addEventListener('click', close);
  backdrop.querySelector('#comFormCancel').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });

  backdrop.querySelector('#comModalPreviewBtn').addEventListener('click', () => {
    openPdfPreview(docName, dataUrl);
  });

  backdrop.querySelector('#comFormSave').addEventListener('click', () => {
    const opUid = backdrop.querySelector('#comFormOp').value;
    if (!opUid) {
      showToast('Sélectionnez une opération', 'alert-triangle');
      return;
    }
    const op = DATA.find(o => o._uid === opUid);
    if (!op) return;
    if (!Array.isArray(op.comites)) op.comites = [];
    op.comites.push({
      id: 'com-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      type: backdrop.querySelector('#comFormType').value,
      date: backdrop.querySelector('#comFormDate').value,
      lien_sharepoint: '',
      doc_name: docName,
      doc_data_url: dataUrl,
      doc_size: docSize,
      notes: '',
    });
    showToast(`Comité ajouté à ${op.code || op.display_name}`, 'check');
    close();
    renderComitesList();
  });
}
// ============== END COMITÉS ==============

// ============== VALIDATIONS / WORKFLOW DE SIGNATURE ==============
// Les workflows sont chargés depuis Supabase au démarrage. Aucun mock ici.
const WORKFLOWS = [];

let wfStatusFilter = 'all'; // 'all' | 'draft' | 'pending' | 'approved' | 'refused'
let wfSearchQuery = '';

function wfStatusConfig(status) {
  switch (status) {
    case 'draft': return { label: 'Brouillon', color: 'neutral', icon: 'pencil' };
    case 'pending': return { label: 'En attente', color: 'warning', icon: 'clock' };
    case 'approved': return { label: 'Validé', color: 'success', icon: 'check' };
    case 'refused': return { label: 'Refusé', color: 'danger', icon: 'x' };
    default: return { label: status, color: 'neutral', icon: 'file-text' };
  }
}

// Return a normalized list of recipients [{name, status, responded_at, refused_reason}]
// Handles both new format (wf.recipients array) and legacy (wf.recipient string)
function getWfRecipients(wf) {
  if (Array.isArray(wf.recipients) && wf.recipients.length > 0) {
    return wf.recipients;
  }
  // Legacy: build single-recipient list from old fields
  if (!wf.recipient) return [];
  let status = 'pending';
  if (wf.status === 'approved') status = 'approved';
  else if (wf.status === 'refused') status = 'refused';
  else if (wf.status === 'draft') status = 'pending'; // draft means not yet sent
  return [{
    name: wf.recipient,
    status,
    responded_at: wf.validated_at || null,
    refused_reason: wf.refused_reason || null,
  }];
}

// Compute overall workflow status from its recipients list
// - draft → draft
// - any refused → refused
// - all approved → approved
// - else → pending
function computeWfOverallStatus(wf) {
  if (wf.status === 'draft') return 'draft';
  const recipients = getWfRecipients(wf);
  if (recipients.length === 0) return wf.status || 'pending';
  if (recipients.some(r => r.status === 'refused')) return 'refused';
  if (recipients.every(r => r.status === 'approved')) return 'approved';
  return 'pending';
}

function formatFileSize(bytes) {
  if (bytes == null) return '?';
  if (bytes < 1024) return bytes + ' o';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' Ko';
  return (bytes / (1024 * 1024)).toFixed(2) + ' Mo';
}

function formatWfDate(iso) {
  if (!iso) return '—';
  try {
    const d = new Date(iso);
    return d.toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch { return iso; }
}

function renderValidations() {
  const list = document.getElementById('wfList');
  if (!list) return;

  // Update status counts (using computed overall status)
  ['draft', 'pending', 'approved', 'refused'].forEach(status => {
    const el = document.getElementById('wfCount-' + status);
    if (el) el.textContent = WORKFLOWS.filter(w => computeWfOverallStatus(w) === status).length;
  });

  // Filter
  const q = (wfSearchQuery || '').trim().toLowerCase();
  const filtered = WORKFLOWS.filter(w => {
    const overall = computeWfOverallStatus(w);
    if (wfStatusFilter !== 'all' && overall !== wfStatusFilter) return false;
    if (q) {
      const op = DATA.find(o => o._uid === w.op_uid);
      const recipientsStr = getWfRecipients(w).map(r => r.name).join(' ');
      const haystack = [w.doc_name, w.doc_type, w.sender, recipientsStr, op?.display_name, op?.code]
        .filter(Boolean).join(' ').toLowerCase();
      if (!haystack.includes(q)) return false;
    }
    return true;
  });

  // Sort: most recent first
  filtered.sort((a, b) => (b.sent_at || '').localeCompare(a.sent_at || ''));

  if (filtered.length === 0) {
    list.innerHTML = `
      <div class="wf-empty">
        <i class="ti ti-file-text"></i>
        <p>Aucun document ${wfStatusFilter !== 'all' ? `au statut "${wfStatusConfig(wfStatusFilter).label}"` : 'à afficher'}.</p>
        <p style="font-size:12px;color:var(--text-tertiary);font-style:italic;">Glissez un PDF en haut pour démarrer un workflow.</p>
      </div>
    `;
    return;
  }

  list.innerHTML = filtered.map(w => {
    const conf = wfStatusConfig(w.status);
    const op = DATA.find(o => o._uid === w.op_uid);
    const recipients = getWfRecipients(w);
    const overallStatus = computeWfOverallStatus(w);
    const ovConf = wfStatusConfig(overallStatus);
    const pendingRecipients = recipients.filter(r => r.status === 'pending');
    const approvedRecipients = recipients.filter(r => r.status === 'approved');
    const refusedRecipients = recipients.filter(r => r.status === 'refused');
    return `
      <div class="wf-item wf-item-${ovConf.color}" data-wf-id="${escapeHtml(w.id)}">
        <div class="wf-item-icon"><i class="ti ti-file-text"></i></div>
        <div class="wf-item-body">
          <div class="wf-item-head">
            <div class="wf-item-name">${escapeHtml(w.doc_name)}</div>
            <span class="wf-item-status wf-status-${ovConf.color}"><i class="ti ti-${ovConf.icon}"></i>${escapeHtml(ovConf.label)}${recipients.length > 1 ? ` <span class="wf-progress-count">${approvedRecipients.length}/${recipients.length}</span>` : ''}</span>
          </div>
          <div class="wf-item-meta">
            <span class="wf-item-type">${escapeHtml(w.doc_type)}</span>
            ${op ? `<span>· <strong>${escapeHtml(op.code || '')}</strong> ${escapeHtml(op.display_name || '')}</span>` : ''}
            <span>· ${formatFileSize(w.doc_size)}</span>
          </div>
          <div class="wf-item-flow">
            <span class="wf-flow-person"><i class="ti ti-user"></i>${escapeHtml(w.sender)}</span>
            <i class="ti ti-arrow-left wf-flow-arrow" style="transform:rotate(180deg);"></i>
            <div class="wf-flow-recipients">
              ${recipients.map(r => {
                const rConf = wfStatusConfig(r.status);
                return `<span class="wf-recipient-chip wf-recipient-${rConf.color}" title="${escapeHtml(rConf.label)}${r.responded_at ? ' le ' + formatWfDate(r.responded_at) : ''}${r.refused_reason ? '. Motif : ' + r.refused_reason : ''}">
                  <i class="ti ti-${rConf.icon}"></i>${escapeHtml(r.name)}
                </span>`;
              }).join('')}
            </div>
            <span class="wf-flow-date">${w.sent_at ? 'envoyé ' + formatWfDate(w.sent_at) : 'brouillon'}</span>
          </div>
          ${w.message ? `<div class="wf-item-message">"${escapeHtml(w.message)}"</div>` : ''}
          ${approvedRecipients.length > 0 && overallStatus === 'approved' ? `<div class="wf-item-result wf-result-success">
            <i class="ti ti-check"></i>Validé par ${approvedRecipients.map(r => escapeHtml(r.name)).join(', ')}
          </div>` : ''}
          ${refusedRecipients.length > 0 ? `<div class="wf-item-result wf-result-danger">
            <i class="ti ti-x"></i>Refusé par ${refusedRecipients.map(r => `${escapeHtml(r.name)}${r.refused_reason ? ` (« ${escapeHtml(r.refused_reason)} »)` : ''}`).join(' · ')}
          </div>` : ''}
        </div>
        <div class="wf-item-actions">
          ${(w.doc_url || w.doc_data_url) ? `
            <button class="btn-small btn-preview" data-wf-action="preview" data-wf-id="${escapeHtml(w.id)}" title="Prévisualiser le PDF"><i class="ti ti-eye"></i>Voir</button>
          ` : ''}
          ${w.status === 'draft' ? `
            <button class="btn-small btn-primary" data-wf-action="send" data-wf-id="${escapeHtml(w.id)}"><i class="ti ti-arrow-left" style="transform:rotate(180deg);"></i>Envoyer</button>
            <button class="btn-small btn-perm-delete" data-wf-action="delete" data-wf-id="${escapeHtml(w.id)}"><i class="ti ti-trash"></i></button>
          ` : ''}
          ${(() => {
            // Distinction émetteur / destinataire
            const me = (typeof CURRENT_USER !== 'undefined') ? CURRENT_USER : '';
            const iAmSender = (w.sender === me);
            const myPendingRecipients = (overallStatus === 'pending')
              ? pendingRecipients.filter(r => r.name === me)
              : [];
            const iAmPendingRecipient = myPendingRecipients.length > 0;

            // Aucun cas pertinent en attente → pas d'action
            if (overallStatus !== 'pending') return '';

            // Construction des boutons selon le rôle
            const buttons = [];
            if (iAmPendingRecipient) {
              buttons.push(`<button class="btn-small btn-restore" data-wf-action="approve" data-wf-recipient="${escapeHtml(me)}" data-wf-id="${escapeHtml(w.id)}"><i class="ti ti-check"></i>Valider</button>`);
              buttons.push(`<button class="btn-small btn-perm-delete" data-wf-action="refuse" data-wf-recipient="${escapeHtml(me)}" data-wf-id="${escapeHtml(w.id)}"><i class="ti ti-x"></i>Refuser</button>`);
            }
            if (iAmSender) {
              buttons.push(`<button class="btn-small btn-perm-delete" data-wf-action="cancel" data-wf-id="${escapeHtml(w.id)}" title="Annuler ce workflow"><i class="ti ti-x"></i>Annuler</button>`);
            }
            return buttons.join('');
          })()}
          ${(overallStatus === 'refused' || overallStatus === 'approved') ? `
            <button class="btn-small" data-wf-action="archive" data-wf-id="${escapeHtml(w.id)}" title="Archiver"><i class="ti ti-trash"></i></button>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');

  // Wire action buttons
  list.querySelectorAll('[data-wf-action]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const action = btn.dataset.wfAction;
      const id = btn.dataset.wfId;
      const recipientName = btn.dataset.wfRecipient || null;
      handleWfAction(action, id, recipientName);
    });
  });
  replaceTablerIcons(list);
}

// Open a modal showing the PDF inline via iframe (browser-native PDF viewer)
function openPdfPreview(docName, dataUrl) {
  if (!dataUrl) {
    showToast('Aucun fichier disponible — workflow sans document attaché', 'alert-triangle');
    return;
  }
  document.querySelectorAll('.pdf-preview-backdrop').forEach(p => p.remove());

  const backdrop = document.createElement('div');
  backdrop.className = 'pdf-preview-backdrop';
  backdrop.innerHTML = `
    <div class="pdf-preview-modal">
      <div class="pdf-preview-head">
        <i class="ti ti-file-text"></i>
        <span class="pdf-preview-name">${escapeHtml(docName)}</span>
        <a class="pdf-preview-dl" href="${dataUrl}" download="${escapeHtml(docName)}" title="Télécharger"><i class="ti ti-arrow-down"></i></a>
        <button class="pdf-preview-close" type="button" title="Fermer">×</button>
      </div>
      <div class="pdf-preview-body">
        <iframe class="pdf-preview-iframe" src="${dataUrl}" title="${escapeHtml(docName)}"></iframe>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  replaceTablerIcons(backdrop);

  const close = () => backdrop.remove();
  backdrop.querySelector('.pdf-preview-close').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => {
    if (e.target === backdrop) close();
  });
  // Esc to close
  const escHandler = (e) => {
    if (e.key === 'Escape') {
      close();
      document.removeEventListener('keydown', escHandler);
    }
  };
  document.addEventListener('keydown', escHandler);
}

function handleWfAction(action, id, recipientName) {
  const wf = WORKFLOWS.find(w => w.id === id);
  if (!wf) return;

  if (action === 'preview') {
    openPdfPreview(wf.doc_name, wf.doc_url || wf.doc_data_url);
    return;
  }

  if (action === 'send') {
    const recipients = getWfRecipients(wf);
    if (recipients.length === 0) { showToast("Choisis un validateur d'abord", 'alert-triangle'); return; }
    wf.status = 'pending';
    wf.sent_at = new Date().toISOString();
    // Ensure all recipients are pending after sending
    if (Array.isArray(wf.recipients)) {
      wf.recipients.forEach(r => { if (!r.status || r.status === 'draft') r.status = 'pending'; });
    }
    const label = recipients.length === 1 ? recipients[0].name : `${recipients.length} validateurs`;
    showToast(`Envoyé à ${label}`, 'check');
    // Persist
    persistWorkflowChange(wf);
  }
  else if (action === 'approve') {
    if (!confirm(`Valider le document « ${wf.doc_name} »${recipientName ? ` en tant que ${recipientName}` : ''} ?

Cette action enregistre une signature électronique simulée.`)) return;
    const now = new Date().toISOString();
    if (Array.isArray(wf.recipients) && wf.recipients.length > 0) {
      if (recipientName) {
        const r = wf.recipients.find(x => x.name === recipientName);
        if (r) { r.status = 'approved'; r.responded_at = now; persistRecipientChange(r); }
      } else {
        wf.recipients.forEach(r => { if (r.status === 'pending') { r.status = 'approved'; r.responded_at = now; persistRecipientChange(r); } });
      }
      wf.status = computeWfOverallStatus(wf);
    } else {
      wf.status = 'approved';
      wf.validated_at = now;
    }
    persistWorkflowChange(wf);
    // Si le workflow est entièrement approuvé ET concerne un comité, on le clôture en "réalisé"
    if (wf.status === 'approved') {
      DATA.forEach(op => {
        if (!Array.isArray(op.comites)) return;
        op.comites.forEach(c => {
          if (c.submitted_wf_id === wf.id) {
            c.statut = 'realise';
            // Si pas encore de doc_data_url sur le comité, on récupère celui du workflow
            if (!c.doc_data_url && (wf.doc_data_url || wf.doc_url)) {
              c.doc_data_url = wf.doc_data_url || wf.doc_url;
              c.doc_name = c.doc_name || wf.doc_name;
            }
            persistComiteChange(c, op);
          }
        });
      });
    }
    showToast(recipientName ? `Validé par ${recipientName}` : 'Document validé', 'check');
  }
  else if (action === 'refuse') {
    const reason = prompt("Motif du refus (visible par l'émetteur) :");
    if (reason === null) return;
    const cleanReason = reason.trim() || 'Non précisé';
    const now = new Date().toISOString();
    if (Array.isArray(wf.recipients) && wf.recipients.length > 0) {
      if (recipientName) {
        const r = wf.recipients.find(x => x.name === recipientName);
        if (r) { r.status = 'refused'; r.responded_at = now; r.refused_reason = cleanReason; persistRecipientChange(r); }
      } else {
        wf.recipients.forEach(r => { if (r.status === 'pending') { r.status = 'refused'; r.responded_at = now; r.refused_reason = cleanReason; persistRecipientChange(r); } });
      }
      wf.status = computeWfOverallStatus(wf);
    } else {
      wf.status = 'refused';
      wf.validated_at = now;
      wf.refused_reason = cleanReason;
    }
    persistWorkflowChange(wf);
    showToast(recipientName ? `Refusé par ${recipientName}` : 'Document refusé', 'x');
  }
  else if (action === 'cancel') {
    if (!confirm(`Annuler le workflow « ${wf.doc_name} » ?

Il sera définitivement supprimé.`)) return;
    const idx = WORKFLOWS.indexOf(wf);
    if (idx >= 0) WORKFLOWS.splice(idx, 1);
    persistWorkflowDelete(wf);
    showToast('Workflow annulé', 'x');
  }
  else if (action === 'delete' || action === 'archive') {
    const verb = action === 'delete' ? 'supprimer ce brouillon' : 'archiver ce document';
    if (!confirm(`Voulez-vous ${verb} ?`)) return;
    const idx = WORKFLOWS.indexOf(wf);
    if (idx >= 0) WORKFLOWS.splice(idx, 1);
    persistWorkflowDelete(wf);
    showToast(action === 'delete' ? 'Brouillon supprimé' : 'Document archivé', 'trash');
  }
  renderValidations();
  refreshNavBadges();
  // Si on a modifié un comité (passage à "realise"), rafraîchir aussi les listes concernées
  if (action === 'approve' && wf.status === 'approved') {
    if (typeof renderComitesList === 'function') renderComitesList();
    if (typeof renderOpDetail === 'function') renderOpDetail();
    if (typeof replaceTablerIcons === 'function') replaceTablerIcons();
  }
}

// ===== Persistance workflows vers Supabase =====
async function persistNewWorkflow(wf) {
  // POST workflow + POST workflow_recipients
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    };
    // Trouver l'operation_id Supabase à partir de op_uid
    let operationId = null;
    if (wf.op_uid) {
      const op = DATA.find(o => o._uid === wf.op_uid);
      if (op && op._supabase_id) operationId = op._supabase_id;
    }
    const wfPayload = {
      operation_id: operationId,
      doc_name: wf.doc_name || '',
      doc_type: wf.doc_type || '',
      doc_size: wf.doc_size || null,
      doc_url: wf.doc_url || null,
      doc_storage_path: wf.doc_storage_path || null,
      sender_name: wf.sender || '',
      status: wf.status || 'pending',
      sent_at: wf.sent_at || null,
      message: wf.message || null,
    };
    const wfRes = await fetch(`${SUPABASE_URL}/rest/v1/workflows`, {
      method: 'POST', headers, body: JSON.stringify(wfPayload),
    });
    if (!wfRes.ok) throw new Error('Workflow POST: ' + wfRes.status);
    const wfCreated = await wfRes.json();
    const wfSupabaseId = Array.isArray(wfCreated) ? wfCreated[0]?.id : wfCreated.id;
    wf._supabase_id = wfSupabaseId;

    // Insérer les recipients
    if (Array.isArray(wf.recipients) && wf.recipients.length > 0) {
      const recipPayloads = wf.recipients.map(r => ({
        workflow_id: wfSupabaseId,
        recipient_name: r.name,
        status: r.status || 'pending',
        responded_at: r.responded_at || null,
        refused_reason: r.refused_reason || null,
      }));
      const recipRes = await fetch(`${SUPABASE_URL}/rest/v1/workflow_recipients`, {
        method: 'POST', headers, body: JSON.stringify(recipPayloads),
      });
      if (recipRes.ok) {
        const created = await recipRes.json();
        if (Array.isArray(created)) {
          created.forEach((c, idx) => { if (wf.recipients[idx]) wf.recipients[idx]._supabase_id = c.id; });
        }
      }
    }
    return wfSupabaseId;
  } catch (err) {
    console.error('persistNewWorkflow error:', err);
    showToast('Erreur création workflow Supabase : ' + err.message, 'alert-triangle');
    return null;
  }
}

async function persistWorkflowChange(wf) {
  if (!wf._supabase_id) {
    // Création différée si pas encore en DB
    return persistNewWorkflow(wf);
  }
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
    };
    const payload = {
      status: wf.status,
      sent_at: wf.sent_at || null,
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/workflows?id=eq.${wf._supabase_id}`, {
      method: 'PATCH', headers, body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('persistWorkflowChange error:', err);
    return false;
  }
}

async function persistRecipientChange(recipient) {
  if (!recipient._supabase_id) return false;
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
    };
    const payload = {
      status: recipient.status,
      responded_at: recipient.responded_at || null,
      refused_reason: recipient.refused_reason || null,
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/workflow_recipients?id=eq.${recipient._supabase_id}`, {
      method: 'PATCH', headers, body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('persistRecipientChange error:', err);
    return false;
  }
}

async function persistWorkflowDelete(wf) {
  if (!wf._supabase_id) return false;
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    // Supprimer les recipients liés (au cas où FK cascade n'est pas activée)
    await fetch(`${SUPABASE_URL}/rest/v1/workflow_recipients?workflow_id=eq.${wf._supabase_id}`, {
      method: 'DELETE', headers,
    });
    const res = await fetch(`${SUPABASE_URL}/rest/v1/workflows?id=eq.${wf._supabase_id}`, {
      method: 'DELETE', headers,
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    // Supprimer aussi le fichier Storage si présent
    if (wf.doc_storage_path) {
      await deleteWorkflowDocument(wf.doc_storage_path);
    }
    return true;
  } catch (err) {
    console.error('persistWorkflowDelete error:', err);
    return false;
  }
}

// ===== Persistance comités vers Supabase =====
// Construit le payload Supabase à partir d'un objet comité mockup
function comitePayloadFromMockup(comite, opSupabaseId) {
  // Si le comité a un workflow lié, on récupère l'id Supabase du workflow
  let pvWfId = null;
  if (comite.submitted_wf_id) {
    const wf = (typeof WORKFLOWS !== 'undefined') ? WORKFLOWS.find(w => w.id === comite.submitted_wf_id) : null;
    if (wf && wf._supabase_id) pvWfId = wf._supabase_id;
  }
  return {
    operation_id: opSupabaseId,
    type: comite.type || null,
    date: comite.date || null,
    lieu: comite.lieu || null,
    statut: comite.statut || 'planifie',
    planning_id: comite.planning_id || null,
    notes: comite.notes || null,
    doc_name: comite.doc_name || null,
    doc_size: comite.doc_size || null,
    doc_data_url: comite.doc_data_url || null,
    lien_sharepoint: comite.lien_sharepoint || null,
    pv_workflow_id: pvWfId,
  };
}

async function persistNewComite(comite, op) {
  if (!op || !op._supabase_id) {
    console.warn('persistNewComite: op without _supabase_id, skipping');
    return null;
  }
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    };
    const payload = comitePayloadFromMockup(comite, op._supabase_id);
    const res = await fetch(`${SUPABASE_URL}/rest/v1/comites`, {
      method: 'POST', headers, body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    const created = await res.json();
    const id = Array.isArray(created) ? created[0]?.id : created.id;
    comite._supabase_id = id;
    return id;
  } catch (err) {
    console.error('persistNewComite error:', err);
    showToast('Erreur sauvegarde comité : ' + err.message, 'alert-triangle');
    return null;
  }
}

async function persistComiteChange(comite, op) {
  if (!comite._supabase_id) {
    // Pas encore en DB : créer
    return persistNewComite(comite, op);
  }
  if (!op || !op._supabase_id) return null;
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
    };
    const payload = comitePayloadFromMockup(comite, op._supabase_id);
    const res = await fetch(`${SUPABASE_URL}/rest/v1/comites?id=eq.${comite._supabase_id}`, {
      method: 'PATCH', headers, body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('persistComiteChange error:', err);
    return false;
  }
}

async function persistComiteDelete(comite) {
  if (!comite._supabase_id) return true; // Pas en DB, rien à supprimer
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/comites?id=eq.${comite._supabase_id}`, {
      method: 'DELETE', headers,
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('persistComiteDelete error:', err);
    return false;
  }
}

// ===== Supabase Storage : upload/delete de PDFs =====
// Bucket public 'workflow-documents' — chaque fichier porte un chemin unique
async function uploadWorkflowDocument(file) {
  // Génère un chemin unique : YYYY-MM-DD/timestamp-cleanname.pdf
  const today = new Date().toISOString().slice(0, 10);
  const ts = Date.now();
  const cleanName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
  const storagePath = `${today}/${ts}-${cleanName}`;
  try {
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/workflow-documents/${storagePath}`, {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${AUTH_TOKEN}`,
        'Content-Type': file.type || 'application/pdf',
        'x-upsert': 'true',
      },
      body: file,
    });
    if (!res.ok) {
      const errText = await res.text();
      throw new Error('Upload Storage: ' + res.status + ' — ' + errText);
    }
    // URL publique du fichier
    const publicUrl = `${SUPABASE_URL}/storage/v1/object/public/workflow-documents/${storagePath}`;
    return { path: storagePath, url: publicUrl };
  } catch (err) {
    console.error('uploadWorkflowDocument error:', err);
    showToast('Erreur upload document : ' + err.message, 'alert-triangle');
    return null;
  }
}

async function deleteWorkflowDocument(storagePath) {
  if (!storagePath) return false;
  try {
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/workflow-documents/${storagePath}`, {
      method: 'DELETE',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${AUTH_TOKEN}`,
      },
    });
    return res.ok;
  } catch (err) {
    console.error('deleteWorkflowDocument error:', err);
    return false;
  }
}

// Handle file drop / browse
async function handleWfFile(file) {
  if (!file) return;
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
    showToast('Seuls les fichiers PDF sont acceptés', 'alert-triangle');
    return;
  }
  showToast('Upload du document en cours…', 'cloud-upload');
  // Upload vers Supabase Storage
  const uploaded = await uploadWorkflowDocument(file);
  if (!uploaded) {
    showToast("Échec de l'upload — workflow non créé", 'alert-triangle');
    return;
  }
  // Ouvrir la modal avec l'URL Supabase
  openWfModal({
    doc_name: file.name,
    doc_size: file.size,
    doc_url: uploaded.url,
    doc_storage_path: uploaded.path,
  });
}

