// ============== SUIVI VIEW ==============
let suiviSelectedPerson = null;
let suiviCatFilter = '';

// Get all unique persons across team-role fields (developpeur, resp_op, charge_fin)
function getAllPersons() {
  const persons = new Set();
  DATA.forEach(op => {
    if (op.developpeur) persons.add(op.developpeur);
    if (op.resp_op) persons.add(op.resp_op);
    if (op.charge_fin) persons.add(op.charge_fin);
  });
  return [...persons].sort();
}

// Return list of roles this person has on a given op
function getRolesForPerson(op, person) {
  const roles = [];
  if (op.developpeur === person) roles.push('Développeur');
  if (op.resp_op === person) roles.push('Resp opération');
  if (op.charge_fin === person) roles.push('Chargé de fin');
  return roles;
}

// ============== FINANCES CONSOLIDÉES ==============
function renderFinances() {
  const c = document.getElementById('financesContent');
  if (!c) return;

  const ops = DATA.filter(o => !o.deleted && inScope(o));

  // ===== Agrégation =====
  let totalBudget = 0;
  let totalFP = 0;
  let totalPrets = { count: 0, sim: 0, lo: 0, contrat: 0 };
  let totalSubv = { count: 0, demande: 0, notifie: 0 };
  let totalGaranties = { count: 0, signed_count: 0, signed_amount: 0, pending_count: 0, pending_amount: 0 };
  let totalLgts = 0;
  const opsByPhase = {};
  const budgetByPhase = {};
  // Encours par typologie de prêt
  const encoursParLigne = {}; // {'PLAI bâti': 1234, 'PLAI foncier': 567, ...}
  // Concentration risque financeur
  const pretsByFinanceur = {};
  // Concentration risque garant
  const garantiesByGarant = {};
  // Taux moyen pondéré
  const tauxBuckets = { 'TLA': { sum: 0, count: 0 }, 'Livret A': { sum: 0, count: 0 }, 'Euribor': { sum: 0, count: 0 }, 'Fixe': { sum: 0, count: 0 } };
  // Délais de garantie
  const garantieDelais = []; // jours entre date_demande et date_conv
  // Plan de financement par op (pour tableau consolidé)
  const opsFinancement = [];

  ops.forEach(op => {
    const phase = op.phase_actuelle || 'Montage';
    opsByPhase[phase] = (opsByPhase[phase] || 0) + 1;

    let opBudget = 0;
    let opFP = 0;
    let opPrets = 0;
    let opSubv = 0;
    let opLgts = 0;

    (op.tranches || []).forEach(t => {
      const bttc = trancheBudgetTTC(t) || 0;
      opBudget += bttc;
      opFP += (parseFloat(t.fonds_propres) || 0);
      const tLgts = trancheLogements(t);
      if (tLgts !== null) opLgts += tLgts;
    });

    (op.prets || []).forEach(p => {
      totalPrets.count++;
      totalPrets.sim += (parseFloat(p.montant_sim) || 0);
      totalPrets.lo += (parseFloat(p.montant_lo) || 0);
      totalPrets.contrat += (parseFloat(p.montant_contrat) || 0);
      const best = bestPretAmount(p);
      opPrets += best;
      if (p.ligne) encoursParLigne[p.ligne] = (encoursParLigne[p.ligne] || 0) + best;
      if (p.financeur) pretsByFinanceur[p.financeur] = (pretsByFinanceur[p.financeur] || 0) + best;
      // Taux moyen pondéré
      const tx = p.taux_texte || p.taux || '';
      const m = tx.match(/^(TLA|Livret A|Euribor|Fixe)/i);
      if (m && best > 0) {
        const idx = m[1].toLowerCase().includes('tla') ? 'TLA'
                  : m[1].toLowerCase().includes('livret') ? 'Livret A'
                  : m[1].toLowerCase().includes('euribor') ? 'Euribor'
                  : 'Fixe';
        // Extraire le spread
        const spreadMatch = tx.match(/([+-])\s*(\d+[,.]?\d*)\s*%/);
        if (spreadMatch) {
          const sign = spreadMatch[1] === '-' ? -1 : 1;
          const spread = parseFloat(spreadMatch[2].replace(',', '.')) * sign;
          tauxBuckets[idx].sum += spread * best;
          tauxBuckets[idx].count += best;
        }
      }
    });

    (op.subventions || []).forEach(s => {
      totalSubv.count++;
      totalSubv.demande += (parseFloat(s.montant_demande) || 0);
      totalSubv.notifie += (parseFloat(s.montant_notifie || s.montant_notif) || 0);
      opSubv += bestSubvAmount(s);
    });

    (op.garanties || []).forEach(g => {
      totalGaranties.count++;
      const m = parseFloat(g.montant_couvert) || 0;
      const isSigned = g.statut === 'Convention signée' || g.date_conv;
      if (isSigned) {
        totalGaranties.signed_count++;
        totalGaranties.signed_amount += m;
      } else {
        totalGaranties.pending_count++;
        totalGaranties.pending_amount += m;
      }
      if (g.garant) garantiesByGarant[g.garant] = (garantiesByGarant[g.garant] || 0) + m;
      // Délai si dates présentes
      if (g.date_demande && g.date_conv) {
        const d1 = parseDateStr(g.date_demande);
        const d2 = parseDateStr(g.date_conv);
        if (d1 && d2) {
          const days = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));
          if (days >= 0 && days < 730) garantieDelais.push(days);
        }
      }
    });

    totalBudget += opBudget;
    totalFP += opFP;
    totalLgts += opLgts;
    budgetByPhase[phase] = (budgetByPhase[phase] || 0) + opBudget;

    // Pour le tableau consolidé : équilibre
    if (opBudget > 0) {
      const ecart = opBudget - opFP - opPrets - opSubv;
      opsFinancement.push({
        code: op.code,
        name: op.display_name,
        phase,
        budget: opBudget,
        fp: opFP,
        prets: opPrets,
        subv: opSubv,
        ecart,
        equilibre: Math.abs(ecart) < 1000, // tolérance 1k€
      });
    }
  });

  // ===== Calculs dérivés =====
  // Top financeurs/garants
  const topFinanceurs = Object.entries(pretsByFinanceur).sort((a, b) => b[1] - a[1]);
  const topGarants = Object.entries(garantiesByGarant).sort((a, b) => b[1] - a[1]);
  // Concentration : part du top 1, top 3
  const totalEncoursPrets = Object.values(pretsByFinanceur).reduce((s, v) => s + v, 0);
  const totalGarMontant = Object.values(garantiesByGarant).reduce((s, v) => s + v, 0);
  const concentTop1Fin = topFinanceurs[0] && totalEncoursPrets > 0 ? topFinanceurs[0][1] / totalEncoursPrets : 0;
  const concentTop3Fin = totalEncoursPrets > 0 ? topFinanceurs.slice(0, 3).reduce((s, [_, v]) => s + v, 0) / totalEncoursPrets : 0;
  const concentTop1Garant = topGarants[0] && totalGarMontant > 0 ? topGarants[0][1] / totalGarMontant : 0;
  // Indicateurs HLM
  const prixMoyenLogt = totalLgts > 0 ? totalBudget / totalLgts : 0;
  const ratioFP = totalBudget > 0 ? totalFP / totalBudget : 0;
  const ratioPrets = totalBudget > 0 ? totalPrets.contrat / totalBudget : 0;
  // Délai moyen garantie
  const delaiMoyenGarantie = garantieDelais.length > 0 ? Math.round(garantieDelais.reduce((s, v) => s + v, 0) / garantieDelais.length) : null;
  // Encours par typologie agrégé PLAI/PLUS/PLS
  const encoursParTypo = {};
  Object.entries(encoursParLigne).forEach(([ligne, val]) => {
    const m = ligne.match(/^(PLAI|PLUS|PLS|PAM|PLI|PHARE|CPLS|PEX)/i);
    const key = m ? m[1].toUpperCase() : 'Autre';
    encoursParTypo[key] = (encoursParTypo[key] || 0) + val;
  });
  const sortedTypos = Object.entries(encoursParTypo).sort((a, b) => b[1] - a[1]);
  const totalEncoursTypo = sortedTypos.reduce((s, [_, v]) => s + v, 0);
  // Couverture des garanties (en % de prêts signés)
  const garantieCoverage = totalPrets.contrat > 0 ? totalGaranties.signed_amount / totalPrets.contrat : 0;
  // Équilibre du portefeuille
  const opsDesequilibrees = opsFinancement.filter(o => !o.equilibre).length;
  // Subventions taux de transformation
  const tauxNotifSubv = totalSubv.demande > 0 ? totalSubv.notifie / totalSubv.demande : 0;
  // Prêts taux de transformation
  const tauxContratPret = totalPrets.sim > 0 ? totalPrets.contrat / totalPrets.sim : 0;

  // Couleurs des typologies
  const TYPO_COLORS = { 'PLAI': '#185fa5', 'PLUS': '#1d9e75', 'PLS': '#ba7517', 'PAM': '#9333ea', 'PLI': '#d85a30', 'PHARE': '#0c447c', 'Autre': '#888780' };

  c.innerHTML = `
    <!-- ===== KPI Headline ===== -->
    <div class="finances-kpis">
      <div class="finances-kpi finances-kpi-primary">
        <div class="finances-kpi-label">Budget total portefeuille</div>
        <div class="finances-kpi-num">${fmtEuros(totalBudget)}</div>
        <div class="finances-kpi-sub">${ops.length} opérations · ${totalLgts || '—'} logements</div>
      </div>
      <div class="finances-kpi finances-kpi-info">
        <div class="finances-kpi-label">Encours prêts contractés</div>
        <div class="finances-kpi-num">${fmtEuros(totalPrets.contrat)}</div>
        <div class="finances-kpi-sub">${(ratioPrets * 100).toFixed(1)}% du budget · ${totalPrets.count} prêts</div>
      </div>
      <div class="finances-kpi finances-kpi-success">
        <div class="finances-kpi-label">Subventions notifiées</div>
        <div class="finances-kpi-num">${fmtEuros(totalSubv.notifie)}</div>
        <div class="finances-kpi-sub">Taux de transformation : ${(tauxNotifSubv * 100).toFixed(0)}%</div>
      </div>
      <div class="finances-kpi finances-kpi-purple">
        <div class="finances-kpi-label">Fonds propres engagés</div>
        <div class="finances-kpi-num">${fmtEuros(totalFP)}</div>
        <div class="finances-kpi-sub">${(ratioFP * 100).toFixed(1)}% du budget</div>
      </div>
      <div class="finances-kpi finances-kpi-warning">
        <div class="finances-kpi-label">Couverture garanties</div>
        <div class="finances-kpi-num">${(garantieCoverage * 100).toFixed(0)}%</div>
        <div class="finances-kpi-sub">${fmtEuros(totalGaranties.signed_amount)} couverts sur ${fmtEuros(totalPrets.contrat)}</div>
      </div>
    </div>

    <div class="finances-grid">
      <!-- ===== 1. ENCOURS PAR TYPOLOGIE ===== -->
      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-chart-pie"></i>Encours par typologie de prêt</h3>
        ${sortedTypos.length === 0 ? '<div class="finances-empty">Aucun prêt enregistré.</div>' : `
        <div class="finances-bars">
          ${sortedTypos.map(([typo, val]) => {
            const pct = totalEncoursTypo > 0 ? (val / totalEncoursTypo * 100) : 0;
            return `
              <div class="finances-bar-row">
                <span class="finances-bar-label" style="color:${TYPO_COLORS[typo] || '#888'};"><strong>${escapeHtml(typo)}</strong></span>
                <div class="finances-bar-track">
                  <div class="finances-bar-fill" style="width:${pct}%;background:${TYPO_COLORS[typo] || '#888'};"></div>
                </div>
                <span class="finances-bar-val">${fmtEuros(val)} <span class="finances-stage-pct">(${pct.toFixed(0)}%)</span></span>
              </div>
            `;
          }).join('')}
        </div>
        <div class="finances-panel-footnote">Encours = montant le plus engagé (contrat &gt; LO &gt; simulation)</div>
        `}
      </div>

      <!-- ===== 2. CONCENTRATION DES RISQUES — Financeurs ===== -->
      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-building-bank"></i>Concentration financeurs</h3>
        ${topFinanceurs.length === 0 ? '<div class="finances-empty">Aucun prêt enregistré.</div>' : `
        <div class="finances-mini-kpis">
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${(concentTop1Fin * 100).toFixed(0)}%</div><div class="finances-mini-kpi-label">Top 1 financeur</div></div>
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${(concentTop3Fin * 100).toFixed(0)}%</div><div class="finances-mini-kpi-label">Top 3 financeurs</div></div>
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${topFinanceurs.length}</div><div class="finances-mini-kpi-label">Financeurs distincts</div></div>
        </div>
        <div class="finances-bars">
          ${topFinanceurs.slice(0, 6).map(([name, val]) => {
            const pct = totalEncoursPrets > 0 ? (val / totalEncoursPrets * 100) : 0;
            const isHighConcent = pct > 40;
            return `
              <div class="finances-bar-row">
                <span class="finances-bar-label">${escapeHtml(name)}</span>
                <div class="finances-bar-track">
                  <div class="finances-bar-fill" style="width:${pct}%;background:${isHighConcent ? 'var(--warning-accent)' : 'var(--info-accent)'};"></div>
                </div>
                <span class="finances-bar-val">${fmtEuros(val)} <span class="finances-stage-pct">(${pct.toFixed(0)}%)</span></span>
              </div>
            `;
          }).join('')}
        </div>
        ${''}
        `}
      </div>

      <!-- ===== 3. CONCENTRATION DES RISQUES — Garants ===== -->
      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-shield-check"></i>Concentration garants</h3>
        ${topGarants.length === 0 ? '<div class="finances-empty">Aucune garantie enregistrée.</div>' : `
        <div class="finances-mini-kpis">
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${(concentTop1Garant * 100).toFixed(0)}%</div><div class="finances-mini-kpi-label">Top 1 garant</div></div>
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${topGarants.length}</div><div class="finances-mini-kpi-label">Garants distincts</div></div>
          <div class="finances-mini-kpi"><div class="finances-mini-kpi-num">${delaiMoyenGarantie !== null ? delaiMoyenGarantie + ' j' : '—'}</div><div class="finances-mini-kpi-label">Délai demande → signature</div></div>
        </div>
        <div class="finances-bars">
          ${topGarants.slice(0, 6).map(([name, val]) => {
            const pct = totalGarMontant > 0 ? (val / totalGarMontant * 100) : 0;
            return `
              <div class="finances-bar-row">
                <span class="finances-bar-label">${escapeHtml(name)}</span>
                <div class="finances-bar-track">
                  <div class="finances-bar-fill" style="width:${pct}%;background:var(--warning-accent);"></div>
                </div>
                <span class="finances-bar-val">${fmtEuros(val)} <span class="finances-stage-pct">(${pct.toFixed(0)}%)</span></span>
              </div>
            `;
          }).join('')}
        </div>
        `}
      </div>

      <!-- ===== 4. INDICATEURS HLM CLÉS ===== -->
      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-gauge"></i>Indicateurs HLM</h3>
        <div class="finances-kpi-grid">
          <div class="finances-indicator">
            <div class="finances-indicator-label">Prix de revient moyen / logement</div>
            <div class="finances-indicator-num">${prixMoyenLogt > 0 ? Math.round(prixMoyenLogt / 1000).toLocaleString('fr-FR').replace(/,/g, ' ') + ' k€' : '—'}</div>
            <div class="finances-indicator-sub">Sur ${totalLgts || 0} logements</div>
          </div>
          <div class="finances-indicator">
            <div class="finances-indicator-label">Ratio fonds propres</div>
            <div class="finances-indicator-num">${(ratioFP * 100).toFixed(1)}%</div>
            <div class="finances-indicator-sub ${ratioFP >= 0.05 ? 'good' : 'warn'}">${ratioFP >= 0.05 ? '✓ ≥ 5%' : '⚠ &lt; 5%'}</div>
          </div>
          <div class="finances-indicator">
            <div class="finances-indicator-label">Ratio prêts / budget</div>
            <div class="finances-indicator-num">${(ratioPrets * 100).toFixed(1)}%</div>
            <div class="finances-indicator-sub">${fmtEuros(totalPrets.contrat)} sur ${fmtEuros(totalBudget)}</div>
          </div>
          <div class="finances-indicator">
            <div class="finances-indicator-label">Taux de transformation prêts</div>
            <div class="finances-indicator-num">${(tauxContratPret * 100).toFixed(0)}%</div>
            <div class="finances-indicator-sub">Simulé → Contrat signé</div>
          </div>
          ${Object.entries(tauxBuckets).filter(([_, v]) => v.count > 0).map(([idx, v]) => {
            const moy = v.count > 0 ? v.sum / v.count : 0;
            const sign = moy >= 0 ? '+' : '';
            return `
              <div class="finances-indicator">
                <div class="finances-indicator-label">Spread moyen sur ${idx}</div>
                <div class="finances-indicator-num">${sign}${moy.toFixed(2)}%</div>
                <div class="finances-indicator-sub">Pondéré par encours</div>
              </div>
            `;
          }).join('')}
        </div>
      </div>

      <!-- ===== 5. PLAN DE FINANCEMENT CONSOLIDÉ ===== -->
      <div class="finances-panel finances-panel-wide">
        <h3 class="finances-panel-title">
          <i class="ti ti-table"></i>Plan de financement par opération
          ${opsDesequilibrees > 0 ? `<span class="finances-panel-badge">${opsDesequilibrees} déséquilibrée${opsDesequilibrees > 1 ? 's' : ''}</span>` : ''}
        </h3>
        ${opsFinancement.length === 0 ? '<div class="finances-empty">Aucune opération budgétée.</div>' : `
        <div class="finances-table-wrap">
          <table class="finances-table">
            <thead><tr>
              <th>Op</th><th>Phase</th>
              <th class="num">Budget</th>
              <th class="num">Fonds propres</th>
              <th class="num">Prêts</th>
              <th class="num">Subv.</th>
              <th class="num">Écart</th>
              <th></th>
            </tr></thead>
            <tbody>
              ${opsFinancement.sort((a, b) => b.budget - a.budget).map(o => {
                const phaseConf = PHASE_COLORS[o.phase] || {};
                const ecartPct = o.budget > 0 ? Math.abs(o.ecart) / o.budget * 100 : 0;
                const ecartCls = o.equilibre ? 'equilibre-ok' : (ecartPct > 5 ? 'equilibre-bad' : 'equilibre-warn');
                return `
                  <tr>
                    <td><strong>${escapeHtml(o.code)}</strong><br><span class="finances-table-subtext">${escapeHtml(o.name)}</span></td>
                    <td><span class="phase-badge-mini" style="background:${phaseConf.bg};color:${phaseConf.text};">${escapeHtml(o.phase)}</span></td>
                    <td class="num">${fmtEuros(o.budget)}</td>
                    <td class="num">${fmtEuros(o.fp)}</td>
                    <td class="num">${fmtEuros(o.prets)}</td>
                    <td class="num">${fmtEuros(o.subv)}</td>
                    <td class="num ${ecartCls}">${o.equilibre ? '✓' : (o.ecart > 0 ? '+' : '') + fmtEuros(o.ecart)}</td>
                    <td><a class="finances-table-link" onclick="selectOpFromFinances('${escapeHtml(o.code)}')" title="Voir l'opération"><i class="ti ti-arrow-up-right"></i></a></td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
        `}
      </div>

      <!-- ===== 6. RÉPARTITION PHASE + LIFECYCLE PRÊTS ===== -->
      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-chart-bar"></i>Budget par phase</h3>
        <div class="finances-bars">
          ${Object.entries(opsByPhase).map(([phase, count]) => {
            const conf = PHASE_COLORS[phase] || {};
            const budget = budgetByPhase[phase] || 0;
            const maxBudget = Math.max(...Object.values(budgetByPhase), 1);
            const pct = (budget / maxBudget * 100);
            return `
              <div class="finances-bar-row">
                <span class="finances-bar-label" style="color:${conf.text};"><strong>${escapeHtml(phase)}</strong> · ${count} op</span>
                <div class="finances-bar-track">
                  <div class="finances-bar-fill" style="width:${pct}%;background:${conf.text};"></div>
                </div>
                <span class="finances-bar-val">${fmtEuros(budget)}</span>
              </div>
            `;
          }).join('')}
        </div>
      </div>

      <div class="finances-panel">
        <h3 class="finances-panel-title"><i class="ti ti-chart-line"></i>Cycle de vie des prêts</h3>
        <div class="finances-stages">
          <div class="finances-stage">
            <div class="finances-stage-label">Simulés / demandés</div>
            <div class="finances-stage-bar"><div class="finances-stage-bar-fill" style="width:100%;background:var(--border-color-strong);"></div></div>
            <div class="finances-stage-val">${fmtEuros(totalPrets.sim)}</div>
          </div>
          <div class="finances-stage">
            <div class="finances-stage-label">Lettres d'offre reçues</div>
            <div class="finances-stage-bar"><div class="finances-stage-bar-fill" style="width:${totalPrets.sim > 0 ? totalPrets.lo / totalPrets.sim * 100 : 0}%;background:var(--warning-accent);"></div></div>
            <div class="finances-stage-val">${fmtEuros(totalPrets.lo)} <span class="finances-stage-pct">(${totalPrets.sim > 0 ? (totalPrets.lo / totalPrets.sim * 100).toFixed(0) : 0}%)</span></div>
          </div>
          <div class="finances-stage">
            <div class="finances-stage-label">Contrats signés</div>
            <div class="finances-stage-bar"><div class="finances-stage-bar-fill" style="width:${totalPrets.sim > 0 ? totalPrets.contrat / totalPrets.sim * 100 : 0}%;background:var(--success-accent);"></div></div>
            <div class="finances-stage-val">${fmtEuros(totalPrets.contrat)} <span class="finances-stage-pct">(${totalPrets.sim > 0 ? (totalPrets.contrat / totalPrets.sim * 100).toFixed(0) : 0}%)</span></div>
          </div>
        </div>
      </div>
    </div>
  `;
  replaceTablerIcons(c);
}

// Helper : sélectionner une op depuis la table Finances
function selectOpFromFinances(code) {
  const op = DATA.find(o => o.code === code);
  if (op) {
    selectedOpCode = op._uid;
    selectedTrancheIdx = 0;
    switchToTab('operations');
    renderAll();
  }
}

// ============== TRÉSORERIE PRÉVISIONNELLE ==============
function renderTresorerie() {
  const c = document.getElementById('tresorerieContent');
  if (!c) return;

  const ops = DATA.filter(o => !o.deleted && inScope(o));
  const today = new Date(); today.setHours(0, 0, 0, 0);
  // Premier du mois courant
  const startMonth = new Date(today.getFullYear(), today.getMonth(), 1);

  // Build monthly bucket projections over the next 24 months
  const months = [];
  for (let i = 0; i < 24; i++) {
    const d = new Date(startMonth.getFullYear(), startMonth.getMonth() + i, 1);
    months.push({
      key: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`,
      label: d.toLocaleDateString('fr-FR', { month: 'short', year: '2-digit' }),
      date: d,
      // Encaissements (flux entrants)
      pret_tirage: 0,         // déblocages de prêts (premier tirage à l'OS, échelonnés...)
      subv_versement: 0,      // versements de subventions
      // Engagements (informations)
      pret_lo: 0,             // lettres d'offre reçues
      pret_contrat: 0,        // contrats signés
      garantie_conv: 0,       // conventions de garantie signées
      // Charge (sortants)
      annuite_capital: 0,     // remboursement capital
      annuite_interet: 0,     // intérêts
      // Détail événements
      events: [],
    });
  }
  const monthFor = (date) => {
    if (!date) return null;
    const k = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
    return months.find(m => m.key === k);
  };

  let totalDeblocages = 0;
  let totalSubventions = 0;
  let prefin = []; // préfinancements actifs

  ops.forEach(op => {
    (op.prets || []).forEach(p => {
      const montant = bestPretAmount(p);

      // Premier tirage (= date_premier_tirage ou date_os ou date_contrat)
      const dTirage = parseDateStr(p.date_premier_tirage) || parseDateStr(p.date_contrat);
      if (dTirage && montant > 0) {
        const m = monthFor(dTirage);
        if (m) {
          m.pret_tirage += montant;
          totalDeblocages += montant;
          m.events.push({
            type: 'tirage',
            op_code: op.code, op_name: op.display_name,
            label: `Tirage ${p.ligne || 'prêt'} · ${p.financeur || ''}`,
            montant: montant,
          });
        }
      }
      // Lettre d'offre
      const dLO = parseDateStr(p.date_lo);
      if (dLO) {
        const m = monthFor(dLO);
        if (m) {
          m.pret_lo += (parseFloat(p.montant_lo) || 0);
          m.events.push({
            type: 'lo',
            op_code: op.code, op_name: op.display_name,
            label: `LO ${p.ligne || ''} · ${p.financeur || ''}`,
            montant: parseFloat(p.montant_lo) || 0,
          });
        }
      }
      // Contrat signé
      const dContrat = parseDateStr(p.date_contrat);
      if (dContrat) {
        const m = monthFor(dContrat);
        if (m) {
          m.pret_contrat += (parseFloat(p.montant_contrat) || 0);
        }
      }
      // Amortissement (simulation simplifiée, A de Q2)
      // Si mise en force définie ET montant contrat > 0 ET durée définie
      const dMEF = parseDateStr(p.date_mise_en_force);
      const duree = parseFloat(p.duree || p.duree_emprunt) || 0;
      const mContrat = parseFloat(p.montant_contrat) || 0;
      if (dMEF && duree > 0 && mContrat > 0) {
        // Amortissement linéaire simplifié sur 'duree' années
        const annuiteCapital = mContrat / duree;
        // Taux 2% pour démo
        const annuiteInterets = mContrat * 0.02; // approximation
        // Mensualité (capital + intérêts) répartie sur 12 mois
        const mensualiteCapital = annuiteCapital / 12;
        const mensualiteInterets = annuiteInterets / 12;
        // Ajouter à tous les mois de la fenêtre où l'amortissement est actif
        months.forEach(mo => {
          if (mo.date >= dMEF) {
            // L'amortissement est en cours si on est dans la fenêtre [dMEF, dMEF + duree*12 mois]
            const monthsSinceMEF = (mo.date.getFullYear() - dMEF.getFullYear()) * 12 + (mo.date.getMonth() - dMEF.getMonth());
            if (monthsSinceMEF < duree * 12) {
              mo.annuite_capital += mensualiteCapital;
              mo.annuite_interet += mensualiteInterets;
            }
          }
        });
      }
    });

    (op.subventions || []).forEach(s => {
      // Versement prévu (Q4 = A : date livraison)
      const dVers = parseDateStr(s.date_versement_prevue) || parseDateStr(s.date_notif || s.date_notification);
      const montant = parseFloat(s.montant_notif || s.montant_notifie) || parseFloat(s.montant_demande) || 0;
      if (dVers && montant > 0) {
        const m = monthFor(dVers);
        if (m) {
          m.subv_versement += montant;
          totalSubventions += montant;
          m.events.push({
            type: 'subv',
            op_code: op.code, op_name: op.display_name,
            label: `Versement subv. ${s.financeur || ''}`,
            montant: montant,
          });
        }
      }
    });

    (op.garanties || []).forEach(g => {
      const d = parseDateStr(g.date_conv);
      const montant = parseFloat(g.montant_couvert) || 0;
      if (d && montant > 0) {
        const m = monthFor(d);
        if (m) {
          m.garantie_conv += montant;
        }
      }
    });

    // Préfinancements actifs
    (op.prefinancements || op.prefin || []).forEach(pf => {
      if (pf.statut === 'En cours') {
        prefin.push({
          op_code: op.code, op_name: op.display_name,
          banque: pf.banque || pf.financeur, montant_couvert: parseFloat(pf.montant_couvert) || 0,
          montant_tire: parseFloat(pf.montant_tire) || 0,
          date_fin: pf.date_fin,
        });
      }
    });
  });

  // Cumul des flux nets (entrants - charge d'amortissement)
  let cumul = 0;
  months.forEach(m => {
    m.flux_entrant = m.pret_tirage + m.subv_versement;
    m.flux_sortant = m.annuite_capital + m.annuite_interet;
    m.flux_net = m.flux_entrant - m.flux_sortant;
    cumul += m.flux_net;
    m.cumul = cumul;
  });

  // Pics : mois avec plus gros flux entrant
  const sortedByFlux = [...months].sort((a, b) => b.flux_entrant - a.flux_entrant);
  const picEncaissement = sortedByFlux[0];
  const picBesoin = [...months].sort((a, b) => b.flux_sortant - a.flux_sortant)[0];

  // Max pour mise à l'échelle des barres
  const maxFlux = Math.max(...months.map(m => Math.max(m.flux_entrant, m.flux_sortant)), 1);
  const maxCumul = Math.max(...months.map(m => Math.abs(m.cumul)), 1);

  // Événements à venir (3 mois)
  const upcomingEvents = months.slice(0, 3).flatMap(m =>
    m.events.map(e => ({ ...e, month_label: m.label, month_date: m.date }))
  ).sort((a, b) => a.month_date - b.month_date);

  // Annuités totales sur 24 mois
  const totalAnnuites = months.reduce((s, m) => s + m.flux_sortant, 0);

  c.innerHTML = `
    <!-- ===== KPI Trésorerie ===== -->
    <div class="treso-kpis">
      <div class="treso-kpi">
        <div class="treso-kpi-label">Flux entrants 24 mois</div>
        <div class="treso-kpi-num">${fmtEuros(totalDeblocages + totalSubventions)}</div>
        <div class="treso-kpi-detail">${fmtEuros(totalDeblocages)} déblocages · ${fmtEuros(totalSubventions)} subv</div>
      </div>
      <div class="treso-kpi treso-kpi-warning">
        <div class="treso-kpi-label">Annuités à payer 24 mois</div>
        <div class="treso-kpi-num">${fmtEuros(totalAnnuites)}</div>
        <div class="treso-kpi-detail">Capital + intérêts</div>
      </div>
      <div class="treso-kpi treso-kpi-success">
        <div class="treso-kpi-label">Flux net cumulé sur 24 mois</div>
        <div class="treso-kpi-num ${cumul >= 0 ? 'treso-positive' : 'treso-negative'}">${cumul >= 0 ? '+' : ''}${fmtEuros(cumul)}</div>
        <div class="treso-kpi-detail">${cumul >= 0 ? 'Solde positif' : 'Besoin de financement'}</div>
      </div>
      <div class="treso-kpi">
        <div class="treso-kpi-label">Pic encaissement</div>
        <div class="treso-kpi-num">${picEncaissement ? fmtEuros(picEncaissement.flux_entrant) : '—'}</div>
        <div class="treso-kpi-detail">${picEncaissement && picEncaissement.flux_entrant > 0 ? picEncaissement.label : '—'}</div>
      </div>
      <div class="treso-kpi">
        <div class="treso-kpi-label">Préfinancements actifs</div>
        <div class="treso-kpi-num">${prefin.length}</div>
        <div class="treso-kpi-detail">${fmtEuros(prefin.reduce((s, p) => s + p.montant_couvert, 0))} mobilisés</div>
      </div>
    </div>

    <!-- ===== Histogramme principal : flux entrants vs sortants ===== -->
    <div class="treso-panel">
      <h3 class="treso-panel-title"><i class="ti ti-chart-bar"></i>Flux trésorerie mensuels sur 24 mois</h3>
      <div class="treso-chart-pn">
        ${months.map(m => {
          const inPct = m.flux_entrant / maxFlux * 100;
          const outPct = m.flux_sortant / maxFlux * 100;
          const tooltip = `${m.label} :
Flux entrants : ${fmtEuros(m.flux_entrant)} (déblocages ${fmtEuros(m.pret_tirage)} + subv ${fmtEuros(m.subv_versement)})
Annuités : ${fmtEuros(m.flux_sortant)}
Net : ${m.flux_net >= 0 ? '+' : ''}${fmtEuros(m.flux_net)}`;
          return `
            <div class="treso-month-pn" title="${escapeHtml(tooltip)}">
              <div class="treso-month-pn-positive">
                <div class="treso-bar-in" style="height:${inPct}%;"></div>
              </div>
              <div class="treso-month-pn-negative">
                <div class="treso-bar-out" style="height:${outPct}%;"></div>
              </div>
              <div class="treso-month-label">${m.label}</div>
            </div>
          `;
        }).join('')}
      </div>
      <div class="treso-legend">
        <span class="treso-legend-item"><span class="treso-legend-dot in"></span>Encaissements (déblocages prêts + subventions)</span>
        <span class="treso-legend-item"><span class="treso-legend-dot out"></span>Décaissements (annuités d'emprunt)</span>
      </div>
    </div>

    <!-- ===== Solde cumulé (courbe) ===== -->
    <div class="treso-panel">
      <h3 class="treso-panel-title"><i class="ti ti-chart-line"></i>Solde net cumulé</h3>
      <div class="treso-cumul-chart">
        ${months.map((m, idx) => {
          const ratio = Math.abs(m.cumul) / maxCumul;
          const isPositive = m.cumul >= 0;
          const height = ratio * 80;
          return `
            <div class="treso-cumul-month" title="${m.label} : ${m.cumul >= 0 ? '+' : ''}${fmtEuros(m.cumul)}">
              <div class="treso-cumul-area" style="height:${height}%;background:${isPositive ? 'var(--success-accent)' : 'var(--warning-accent)'};${isPositive ? 'align-self:flex-end;' : 'align-self:flex-start;'}"></div>
              <div class="treso-month-label">${m.label}</div>
            </div>
          `;
        }).join('')}
      </div>
    </div>

    <!-- ===== Tableau événements 3 mois ===== -->
    <div class="treso-grid">
      <div class="treso-panel">
        <h3 class="treso-panel-title"><i class="ti ti-calendar-event"></i>Événements financiers 3 prochains mois</h3>
        ${upcomingEvents.length === 0 ? '<div class="treso-empty">Aucun événement financier projeté sur les 3 prochains mois.</div>' : `
        <div class="treso-events">
          ${upcomingEvents.map(e => {
            const typeIcons = { 'tirage': 'arrow-down-circle', 'subv': 'gift', 'lo': 'mail' };
            const typeColors = { 'tirage': 'var(--info-accent)', 'subv': 'var(--success-accent)', 'lo': 'var(--warning-accent)' };
            return `
              <div class="treso-event">
                <div class="treso-event-icon" style="color:${typeColors[e.type]};"><i class="ti ti-${typeIcons[e.type]}"></i></div>
                <div class="treso-event-body">
                  <div class="treso-event-label">${escapeHtml(e.label)}</div>
                  <div class="treso-event-meta">${escapeHtml(e.op_code)} · ${escapeHtml(e.op_name)} · ${escapeHtml(e.month_label)}</div>
                </div>
                <div class="treso-event-amount">${fmtEuros(e.montant)}</div>
              </div>
            `;
          }).join('')}
        </div>
        `}
      </div>

      <!-- ===== Préfinancements ===== -->
      <div class="treso-panel">
        <h3 class="treso-panel-title"><i class="ti ti-clock-bolt"></i>Préfinancements actifs</h3>
        ${prefin.length === 0 ? '<div class="treso-empty">Aucun préfinancement actif.</div>' : `
        <div class="treso-events">
          ${prefin.map(p => {
            const pctTire = p.montant_couvert > 0 ? (p.montant_tire / p.montant_couvert * 100) : 0;
            return `
              <div class="treso-event">
                <div class="treso-event-icon" style="color:var(--purple-accent);"><i class="ti ti-clock-bolt"></i></div>
                <div class="treso-event-body">
                  <div class="treso-event-label">${escapeHtml(p.banque || '?')}</div>
                  <div class="treso-event-meta">${escapeHtml(p.op_code)} · ${pctTire.toFixed(0)}% tiré · fin ${escapeHtml(p.date_fin || '—')}</div>
                </div>
                <div class="treso-event-amount">${fmtEuros(p.montant_tire)} / ${fmtEuros(p.montant_couvert)}</div>
              </div>
            `;
          }).join('')}
        </div>
        `}
      </div>
    </div>

    <div class="treso-disclaimer">
      <i class="ti ti-info-circle"></i>
      <span>
        Projection construite à partir des dates contractuelles : déblocages à la date OS / 1er tirage, subventions versées à la livraison, annuités d'amortissement linéaire (simulation simplifiée, taux d'intérêt fixé à 2% pour la démo).
        En production, le profil réel CDC (différé, progressif, etc.) serait intégré.
      </span>
    </div>
  `;
  replaceTablerIcons(c);
}

// ============== ACCUEIL (personal dashboard) ==============
let CURRENT_USER = 'Bastien MERCIER';
let APP_SCOPE = (function(){ try { return sessionStorage.getItem('exnihilo_scope') || 'mine'; } catch(e){ return 'mine'; } })();
let ACCOUNTS = []; // rattachements compte (email) -> personne, chargés depuis la table 'comptes'
// Normalisation pour rattacher un compte (display name) à une personne des données (resp_op / charge_fin / developpeur)
function normPerson(s){ return (s||'').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim(); }
function isCurrentUser(name){ const c = normPerson(CURRENT_USER); return !!c && normPerson(name) === c; }
function isMyOp(op){ return !!op && (isCurrentUser(op.charge_fin) || isCurrentUser(op.resp_op) || isCurrentUser(op.developpeur)); }
function inScope(op){ return APP_SCOPE !== 'mine' || isMyOp(op); }
function firstNameOf(full){ const t=(full||'').toString().trim().split(/\s+/)[0]||''; return t ? t.charAt(0).toUpperCase()+t.slice(1).toLowerCase() : ''; }
function applyScopeRerender(){
  try { renderSidebar(); } catch(e){}
  try { if (typeof refreshDashboardKpis === 'function') refreshDashboardKpis(); } catch(e){}
  try { if (typeof renderSynthTable === 'function') renderSynthTable(); } catch(e){}
  const v = (typeof storageGet === 'function' && storageGet('activeView')) || 'accueil';
  try { if (typeof switchToTab === 'function') switchToTab(v); } catch(e){}
}

// Op chronological timeline (collapsible section under Calendar)
function toggleOpTimeline(uid) { openTimelineModal(uid); }

// === Chronologie de l'opération : collecte d'événements (partagée bouton + modale) ===
function collectOpTimelineEvents(op) {
  const events = [];
  const addEvt = (date, type, label, detail, color) => {
    const d = parseDateStr(date);
    if (!d) return;
    events.push({ date: d, dateStr: date, type, label, detail, color });
  };
  addEvt(op.date_promesse, 'Foncier', 'Promesse signée', 'Signature de la promesse de vente', 'success');
  addEvt(op.date_acte, 'Foncier', 'Acte authentique signé', 'Acquisition foncière', 'success');
  addEvt(op.date_depot_pc, 'Travaux', 'Dépôt du permis de construire', null, 'info');
  addEvt(op.date_obtention_pc, 'Travaux', 'Obtention du permis', 'Permis purgé et exécutoire', 'info');
  addEvt(op.date_obt_pc, 'Travaux', 'PC obtenu', null, 'info');
  addEvt(op.date_os, 'Travaux', "Ordre de service (OS)", 'Démarrage des travaux', 'warning');
  addEvt(op.date_droc, 'Travaux', "Déclaration ouverture chantier (DROC)", null, 'warning');
  addEvt(op.date_livraison, 'Travaux', 'Livraison', 'Réception des travaux', 'success');
  addEvt(op.date_conv_loc, 'Conventionnement', 'Convention de location', null, 'info');
  addEvt(op.date_conv_apl, 'Conventionnement', 'Convention APL', null, 'info');
  addEvt(op.date_ca_axentia, 'Gouvernance', 'Passage en CA Axentia', null, 'purple');
  (op.tranches || []).forEach(t => {
    const tCode = t.code_full ? t.code_full.split('-').slice(1).join('-') : t.id;
    addEvt(t.date_agrement, 'Agrément', `Agrément ${tCode}`, t.financement || null, 'info');
    addEvt(t.date_dfa, 'Agrément', `DFA ${tCode}`, 'Décision de financement', 'success');
  });
  (op.prets || []).forEach(p => {
    const label = `${p.ligne || 'Prêt'} ${p.financeur || ''}`.trim();
    addEvt(p.date_demande, 'Prêt', `Demande de prêt ${label}`, fmtMontant(p.montant_sim), 'info');
    addEvt(p.date_lo, 'Prêt', `Lettre d'offre ${label}`, fmtMontant(p.montant_lo), 'warning');
    addEvt(p.date_contrat, 'Prêt', `Contrat signé ${label}`, fmtMontant(p.montant_contrat), 'success');
  });
  (op.garanties || []).forEach(g => {
    const label = g.garant || 'Garantie';
    addEvt(g.date_demande, 'Garantie', `Demande de garantie ${label}`, fmtMontant(g.montant_couvert), 'info');
    addEvt(g.date_ap, 'Garantie', `Accord de principe ${label}`, null, 'warning');
    addEvt(g.date_delib, 'Garantie', `Délibération ${label}`, null, 'success');
    addEvt(g.date_conv, 'Garantie', `Convention de garantie ${label}`, null, 'success');
  });
  (op.subventions || []).forEach(s => {
    addEvt(s.date_demande, 'Subvention', `Demande ${s.financeur || ''}`, fmtMontant(s.montant_demande), 'info');
    addEvt(s.date_notification, 'Subvention', `Notification ${s.financeur || ''}`, fmtMontant(s.montant_notifie), 'success');
    addEvt(s.date_conv, 'Subvention', `Convention ${s.financeur || ''}`, null, 'success');
  });
  (op.comites || []).forEach(com => {
    const conf = comiteTypeConfig(com.type);
    addEvt(com.date, 'Comité', `${conf.full}`, com.doc_name || null, 'purple');
  });
  events.sort((a, b) => a.date.getTime() - b.date.getTime());
  return events;
}
function countOpTimelineEvents(op) { return collectOpTimelineEvents(op).length; }

let _timelineModalUid = null;
function openTimelineModal(uid) {
  _timelineModalUid = uid;
  const op = findOp(uid) || (DATA || []).find(o => o._uid === uid);
  if (!op) return;
  const events = collectOpTimelineEvents(op);
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const body = document.getElementById('timelineModalBody');
  const titleEl = document.getElementById('timelineModalTitle');
  if (titleEl) titleEl.textContent = op.display_name || op.code || "Chronologie de l'opération";
  // Filtres par type
  const types = [...new Set(events.map(e => e.type))];
  const filterBar = `<div class="timeline-modal-filters">
      <button class="tmf-chip active" data-tmf="all">Tous <span>${events.length}</span></button>
      ${types.map(t => `<button class="tmf-chip" data-tmf="${escapeHtml(t)}">${escapeHtml(t)} <span>${events.filter(e => e.type === t).length}</span></button>`).join('')}
    </div>`;
  const list = `<ul class="timeline-list">
      ${events.map(e => {
        const isPast = e.date.getTime() <= today.getTime();
        const dateStr = e.date.toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' });
        return `<li class="timeline-evt timeline-evt-${e.color} ${isPast ? 'timeline-evt-past' : 'timeline-evt-future'}" data-evt-type="${escapeHtml(e.type)}">
            <span class="timeline-dot"></span>
            <span class="timeline-date">${escapeHtml(dateStr)}</span>
            <span class="timeline-type">${escapeHtml(e.type)}</span>
            <div class="timeline-body">
              <div class="timeline-label">${escapeHtml(e.label)}</div>
              ${e.detail ? `<div class="timeline-detail">${escapeHtml(e.detail)}</div>` : ''}
            </div>
          </li>`;
      }).join('')}
    </ul>`;
  body.innerHTML = events.length ? (filterBar + list) : '<div class="subent-empty">Aucun événement daté pour cette opération.</div>';
  // Wire filters
  body.querySelectorAll('.tmf-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      body.querySelectorAll('.tmf-chip').forEach(c => c.classList.toggle('active', c === chip));
      const f = chip.dataset.tmf;
      body.querySelectorAll('.timeline-evt').forEach(li => {
        li.style.display = (f === 'all' || li.dataset.evtType === f) ? '' : 'none';
      });
    });
  });
  document.getElementById('timelineModalBackdrop').classList.add('open');
  if (typeof replaceTablerIcons === 'function') replaceTablerIcons();
}
function closeTimelineModal() {
  document.getElementById('timelineModalBackdrop').classList.remove('open');
  _timelineModalUid = null;
}

function renderAccueil() {
  const c = document.getElementById('accueilContent');
  if (!c) return;

  // Greeting based on time of day
  const greetEl = document.getElementById('accueilGreeting');
  if (greetEl) {
    const h = new Date().getHours();
    let salut = 'Bonjour';
    if (h < 6) salut = 'Bonsoir';
    else if (h < 12) salut = 'Bonjour';
    else if (h < 18) salut = 'Bon après-midi';
    else salut = 'Bonsoir';
    document.querySelector('#view-accueil .dashboard-title').textContent = `${salut} ${firstNameOf(CURRENT_USER) || ''}`.trim();
  }

  // Ops where user has a role
  const myOps = DATA.filter(op => !op.deleted && isMyOp(op));

  // Alerts aggregated across my ops
  const allAlerts = [];
  myOps.forEach(op => {
    const alerts = computeAlerts(op);
    alerts.forEach(a => allAlerts.push({ ...a, op }));
  });
  allAlerts.sort((a, b) => a.days - b.days);
  const top5Alerts = allAlerts.slice(0, 5);

  // Workflows where I'm a recipient (pending only)
  const myPendingWorkflows = WORKFLOWS.filter(w => {
    if (computeWfOverallStatus(w) !== 'pending') return false;
    const recipients = getWfRecipients(w);
    return recipients.some(r => isCurrentUser(r.name) && r.status === 'pending');
  });

  // Comités à venir (date > today, ou date dans les 30 derniers jours)
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const upcomingComites = [];
  myOps.forEach(op => {
    if (!Array.isArray(op.comites)) return;
    op.comites.forEach(com => {
      const d = parseDateStr(com.date);
      if (!d) return;
      const diff = Math.floor((d.getTime() - today.getTime()) / 86400000);
      if (diff >= -30 && diff <= 60) {
        upcomingComites.push({ comite: com, op, days: diff });
      }
    });
  });
  upcomingComites.sort((a, b) => Math.abs(a.days) - Math.abs(b.days));

  // Phase counts of my ops
  const phaseCounts = {};
  ['Montage','Validation CA','Travaux','Livraison','GPA'].forEach(p => phaseCounts[p] = 0);
  myOps.forEach(op => {
    const p = op.phase_actuelle || 'Montage';
    if (phaseCounts[p] != null) phaseCounts[p]++;
  });
  const totalPhases = Object.values(phaseCounts).reduce((s, n) => s + n, 0);

  // Recent activity (from audit logs across my ops)
  const recentActivity = [];
  myOps.forEach(op => {
    if (!Array.isArray(op.audit_log)) return;
    op.audit_log.forEach(e => {
      if (!isCurrentUser(e.user)) { // only show actions by OTHERS
        recentActivity.push({ entry: e, op });
      }
    });
  });
  recentActivity.sort((a, b) => (b.entry.date || '').localeCompare(a.entry.date || ''));
  const top5Activity = recentActivity.slice(0, 5);

  // KPIs
  const kpis = [
    { label: 'Mes opérations', value: myOps.length, color: 'info', icon: 'building-community' },
    { label: 'Échéances urgentes', value: allAlerts.filter(a => a.level === 'expired' || a.level === 'critical').length, color: allAlerts.some(a => a.level === 'expired' || a.level === 'critical') ? 'danger' : 'success', icon: 'alert-triangle' },
    { label: 'À valider', value: myPendingWorkflows.length, color: myPendingWorkflows.length > 0 ? 'warning' : 'success', icon: 'file-certificate' },
    { label: 'Comités à venir', value: upcomingComites.filter(x => x.days >= 0).length, color: 'info', icon: 'users' },
  ];

  c.innerHTML = `
    <div class="accueil-kpis">
      ${kpis.map(k => `
        <div class="accueil-kpi accueil-kpi-${k.color}">
          <i class="ti ti-${k.icon} accueil-kpi-icon"></i>
          <div class="accueil-kpi-content">
            <div class="accueil-kpi-num">${k.value}</div>
            <div class="accueil-kpi-label">${escapeHtml(k.label)}</div>
          </div>
        </div>
      `).join('')}
    </div>

    <div class="accueil-grid">
      <!-- Échéances urgentes -->
      <div class="accueil-card accueil-card-wide">
        <div class="accueil-card-head">
          <i class="ti ti-alert-triangle"></i>
          <span>Tes échéances les plus urgentes</span>
          ${top5Alerts.length > 0 ? `<a href="#" class="accueil-card-link" data-go-tab="suivi">Voir le suivi complet →</a>` : ''}
        </div>
        ${top5Alerts.length === 0 ? `
          <div class="accueil-empty">
            <i class="ti ti-check"></i>
            <p>Aucune échéance critique. Tout est sous contrôle.</p>
          </div>
        ` : `
          <ul class="accueil-alerts">
            ${top5Alerts.map(a => `
              <li class="alert-item alert-${a.level}" data-go-op="${escapeHtml(a.op._uid)}">
                <span class="alert-days">${a.days < 0 ? `${-a.days}j ⚠` : `${a.days}j`}</span>
                <div class="accueil-alert-body">
                  <div class="accueil-alert-op"><strong>${escapeHtml(a.op.code || '?')}</strong> · ${escapeHtml(a.op.display_name || '')}</div>
                  <div class="accueil-alert-msg">${escapeHtml(a.msg)}</div>
                </div>
              </li>
            `).join('')}
          </ul>
        `}
      </div>

      <!-- Workflows en attente de ma validation -->
      <div class="accueil-card">
        <div class="accueil-card-head">
          <i class="ti ti-file-certificate"></i>
          <span>En attente de ta validation</span>
        </div>
        ${myPendingWorkflows.length === 0 ? `
          <div class="accueil-empty">
            <i class="ti ti-check"></i>
            <p>Aucun document en attente.</p>
          </div>
        ` : `
          <ul class="accueil-wf-list">
            ${myPendingWorkflows.slice(0, 6).map(w => {
              const op = DATA.find(o => o._uid === w.op_uid);
              return `
                <li class="accueil-wf-item" data-go-tab="validations">
                  <i class="ti ti-file-text"></i>
                  <div class="accueil-wf-body">
                    <div class="accueil-wf-name">${escapeHtml(w.doc_name)}</div>
                    <div class="accueil-wf-meta">${escapeHtml(w.doc_type)}${op ? ` · ${escapeHtml(op.code || '')}` : ''}</div>
                  </div>
                  <span class="accueil-wf-from">de ${escapeHtml(w.sender)}</span>
                </li>
              `;
            }).join('')}
          </ul>
          ${myPendingWorkflows.length > 6 ? `<div class="accueil-card-more"><a href="#" data-go-tab="validations">+ ${myPendingWorkflows.length - 6} autres</a></div>` : ''}
        `}
      </div>

      <!-- Comités à venir -->
      <div class="accueil-card">
        <div class="accueil-card-head">
          <i class="ti ti-users"></i>
          <span>Comités proches</span>
          ${upcomingComites.length > 0 ? `<a href="#" class="accueil-card-link" data-go-tab="comites">Tous →</a>` : ''}
        </div>
        ${upcomingComites.length === 0 ? `
          <div class="accueil-empty">
            <i class="ti ti-calendar"></i>
            <p>Aucun comité prévu.</p>
          </div>
        ` : `
          <ul class="accueil-com-list">
            ${upcomingComites.slice(0, 6).map(({comite, op, days}) => {
              const conf = comiteTypeConfig(comite.type);
              const label = days === 0 ? "aujourd'hui" : (days > 0 ? `dans ${days}j` : `il y a ${-days}j`);
              const cls = days < 0 ? 'accueil-com-past' : (days <= 7 ? 'accueil-com-soon' : '');
              return `
                <li class="accueil-com-item ${cls}" data-go-op="${escapeHtml(op._uid)}">
                  <span class="comite-type-pill" style="background:${conf.bg};color:${conf.txt};border-color:${conf.accent};">${escapeHtml(conf.label)}</span>
                  <div class="accueil-com-body">
                    <div class="accueil-com-op"><strong>${escapeHtml(op.code || '?')}</strong> · ${escapeHtml(op.display_name || '')}</div>
                    <div class="accueil-com-meta">${escapeHtml(comite.date || '?')} · ${escapeHtml(label)}</div>
                  </div>
                </li>
              `;
            }).join('')}
          </ul>
        `}
      </div>

      <!-- Répartition par phase -->
      <div class="accueil-card">
        <div class="accueil-card-head">
          <i class="ti ti-chart-bar"></i>
          <span>Mes opérations par phase</span>
        </div>
        ${totalPhases === 0 ? `<div class="accueil-empty"><p>Aucune opération attribuée.</p></div>` : `
          <div class="accueil-phases">
            ${Object.entries(phaseCounts).map(([phase, n]) => {
              const conf = PHASE_COLORS[phase];
              const pct = totalPhases > 0 ? (n / totalPhases * 100) : 0;
              return `
                <div class="accueil-phase-row">
                  <span class="accueil-phase-label" style="color:${conf.text};">${escapeHtml(phase)}</span>
                  <div class="accueil-phase-bar">
                    <div class="accueil-phase-bar-fill" style="width:${pct}%;background:${conf.bg};border-right:2px solid ${conf.text};"></div>
                  </div>
                  <span class="accueil-phase-num">${n}</span>
                </div>
              `;
            }).join('')}
          </div>
        `}
      </div>

      <!-- Activité récente -->
      <div class="accueil-card accueil-card-wide">
        <div class="accueil-card-head">
          <i class="ti ti-history"></i>
          <span>Activité récente sur tes opérations</span>
        </div>
        ${top5Activity.length === 0 ? `
          <div class="accueil-empty">
            <i class="ti ti-history"></i>
            <p>Pas d'activité récente d'autres collaborateurs.</p>
            <p style="font-size:11.5px;color:var(--text-tertiary);font-style:italic;">L'activité s'affichera ici quand d'autres personnes modifieront tes opérations.</p>
          </div>
        ` : `
          <ul class="accueil-activity">
            ${top5Activity.map(({entry, op}) => {
              const d = new Date(entry.date);
              const dateStr = isNaN(d) ? entry.date : d.toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
              return `
                <li class="accueil-activity-item" data-go-op="${escapeHtml(op._uid)}">
                  <span class="accueil-activity-date">${escapeHtml(dateStr)}</span>
                  <span class="accueil-activity-user"><strong>${escapeHtml(entry.user || '?')}</strong></span>
                  <span class="accueil-activity-action">a modifié <em>${escapeHtml(entry.field || '?')}</em></span>
                  <span class="accueil-activity-op">sur ${escapeHtml(op.code || op.display_name || '?')}</span>
                </li>
              `;
            }).join('')}
          </ul>
        `}
      </div>
    </div>
  `;

  // Wire navigation links
  c.querySelectorAll('[data-go-op]').forEach(el => {
    el.addEventListener('click', () => {
      const uid = el.dataset.goOp;
      selectOp(uid);
      switchToTab('operations');
    });
  });
  c.querySelectorAll('[data-go-tab]').forEach(el => {
    el.addEventListener('click', (e) => {
      e.preventDefault();
      switchToTab(el.dataset.goTab);
    });
  });
}

// Helper to switch to a named tab programmatically
function switchToTab(viewName) {
  document.querySelectorAll('.topnav-tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  const tab = document.querySelector(`[data-view="${viewName}"]`);
  const view = document.getElementById(`view-${viewName}`);
  if (tab) tab.classList.add('active');
  if (view) view.classList.add('active');
  storageSet('activeView', viewName);
  // Trigger the same render as a real click would
  if (viewName === 'suivi') { renderSuivi(); }
  else if (viewName === 'validations') { initValidationsView(); renderValidations(); }
  else if (viewName === 'comites') { renderComitesTab(); }
  else if (viewName === 'gantt') { renderGantt(); }
  else if (viewName === 'carte') { initMapFilters(); renderMap(); }
  else if (viewName === 'finances') { renderFinances(); }
  else if (viewName === 'tresorerie') { renderTresorerie(); }
  else if (viewName === 'referentiels') { renderReferentiels(); }
  else if (viewName === 'trash') { renderTrash(); }
  else if (viewName === 'accueil') { renderAccueil(); }
  else if (viewName === 'aap') { renderAAP(); }
  else if (viewName === 'controles') { renderControles(); }
  else if (viewName === 'charge') { renderCharge(); }
  replaceTablerIcons();
}
