// ---- Moteur de tâches : transforme une opération en actions à mener ----
const SUIVI_CATS = {
  'Financement':      { color: '#2f6fb3' },
  'Garanties':        { color: '#7048b6' },
  'Subventions':      { color: '#1f9e6e' },
  'Agrément':         { color: '#b3791f' },
  'Calendrier':       { color: '#c0392b' },
  'Préfinancement':   { color: '#0d7a86' },
  'Conventionnement': { color: '#b3437f' },
  'Comité':           { color: '#555e6d' },
  'AAP':              { color: '#d4730a' },
};

function computeTasks(op) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const addMonths = (d, n) => { const r = new Date(d); r.setMonth(r.getMonth() + n); return r; };
  const dAfter = (d) => Math.floor((d.getTime() - today.getTime()) / 86400000);
  const fmt = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
  const phaseIdx = PHASES.indexOf(op.phase_actuelle || 'Montage');
  const isDelivered = phaseIdx >= PHASES.indexOf('Livraison');
  const phaseLevel = phaseIdx >= PHASES.indexOf('Travaux') ? 1 : (phaseIdx >= PHASES.indexOf('Validation CA') ? 2 : 3);
  const tasks = [];
  const add = (cat, action, deadline, opts = {}) => {
    const days = deadline ? dAfter(deadline) : null;
    let level;
    if (days != null) level = days <= 15 ? 1 : days <= 31 ? 2 : days <= 90 ? 3 : 4;
    else level = opts.level || phaseLevel;
    tasks.push({ cat, action, op, deadline: deadline || null, days, level, overdue: days != null && days < 0, detail: opts.detail || '' });
  };

  // FINANCEMENT
  if (!isDelivered) (op.prets || []).forEach(p => {
    const lib = `${p.ligne || 'prêt'}${p.financeur ? ' · ' + p.financeur : ''}`;
    const st = p.statut || '';
    if (!st || st === 'À demander') add('Financement', `Déposer la demande de prêt ${lib}`, null);
    else if (['Demandé', 'En instruction', 'Dossier transmis'].includes(st)) add('Financement', `Relancer l'instruction du prêt ${lib}`, null, { level: Math.min(phaseLevel + 1, 4) });
    else if (st === "Lettre d'offre" || (p.date_lo && !p.date_contrat)) {
      const d = parseDateStr(p.date_lo); const dl = d ? addMonths(d, 4) : null;
      add('Financement', `Faire signer le contrat de prêt ${lib}`, dl, { detail: dl ? `lettre d'offre valable jusqu'au ${fmt(dl)}` : '' });
    }
  });

  // GARANTIES
  if (!isDelivered) {
    const garantissables = (op.prets || []).filter(p => !p.non_garanti && !/^\s*als\b/i.test(p.ligne || ''));
    garantissables.forEach(p => {
      if (!(op.garanties || []).some(g => (g.pret_lie || '') === (p.ligne || '')))
        add('Garanties', `Monter le dossier de garantie pour ${p.ligne || 'prêt'}`, null);
    });
    (op.garanties || []).forEach(g => {
      const lib = g.garant || 'garant'; const st = g.statut || '';
      if (!st || st === 'À demander') add('Garanties', `Solliciter la garantie ${lib}${g.pret_lie ? ' (' + g.pret_lie + ')' : ''}`, null);
      else if (['Dossier transmis', 'Accord de principe reçu'].includes(st)) {
        const d = parseDateStr(g.date_ap || g.date_demande); const dl = d ? addMonths(d, 6) : null;
        add('Garanties', `Obtenir la délibération de garantie ${lib}`, dl, { detail: dl ? `accord de principe valable ~${fmt(dl)}` : '' });
      } else if (['Délibération votée', 'Délibération exécutoire'].includes(st) && !g.date_conv)
        add('Garanties', `Faire signer la convention de garantie ${lib}`, null);
    });
  }

  // SUBVENTIONS
  if (!isDelivered) (op.subventions || []).forEach(s => {
    const lib = `${s.financement || 'subvention'}${s.financeur ? ' · ' + s.financeur : ''}`;
    const st = s.statut || '';
    if (!st || st === 'À déposer') add('Subventions', `Déposer la demande de subvention ${lib}`, null);
    else if (['En instruction', 'Déposée'].includes(st)) add('Subventions', `Relancer la subvention ${lib}`, null, { level: Math.min(phaseLevel + 1, 4) });
  });

  // AGRÉMENT
  (op.tranches || []).forEach(t => {
    const st = t.statut_agrement || '';
    const obtained = /obtenu|dfa sign|agréé/i.test(st);
    const trc = (typeof synthTrCode === 'function' ? synthTrCode(t) : '') || '';
    if (!isDelivered && st && !obtained && !/clôtur/i.test(st))
      add('Agrément', `Suivre l'instruction de l'agrément${trc ? ' ' + trc : ''}`, null);
    if (!op.date_os && obtained) {
      const d = parseDateStr(t.date_agrement || t.date_dfa); const dl = d ? addMonths(d, 18) : null;
      if (dl) add('Agrément', `Lancer l'OS avant caducité d'agrément${trc ? ' ' + trc : ''}`, dl, { detail: `caducité le ${fmt(dl)}` });
    }
    if (t.date_cloture_agrement && !op.date_os) {
      const dc = parseDateStr(t.date_cloture_agrement);
      if (dc) add('Agrément', `Clôturer l'agrément avant la date butoir${trc ? ' ' + trc : ''}`, dc, { detail: `clôture le ${fmt(dc)}` });
    }
  });

  // CALENDRIER
  if (!isDelivered && op.date_obt_pc && !op.date_os) {
    const d = parseDateStr(op.date_obt_pc);
    if (d) add('Calendrier', `Lancer l'OS avant péremption du permis de construire`, addMonths(d, 24), { detail: 'PC valable 2 ans' });
  }
  if (isDelivered && op.date_livraison && !op.date_conv_apl) {
    const d = parseDateStr(op.date_livraison);
    add('Conventionnement', `Signer la convention APL`, d ? addMonths(d, 6) : null, { detail: 'à régulariser après livraison' });
  }

  // PRÉFINANCEMENT
  (op.prefinancements || []).forEach(pf => {
    if (pf.date_fin && pf.statut !== 'Soldé') {
      const d = parseDateStr(pf.date_fin);
      if (d) add('Préfinancement', `Mobiliser le prêt définitif — préfi ${pf.banque || ''}${pf.pret_lie ? ' ' + pf.pret_lie : ''}`, d, { detail: `préfinancement se termine le ${fmt(d)}` });
    }
  });

  // CONVENTIONNEMENT / RÉSERVATAIRES
  if (!isDelivered) (op.reservataires || []).forEach(r => {
    const et = r.etape || r.statut || '';
    if (['À demander', 'En négociation'].includes(et))
      add('Conventionnement', `Conventionner le réservataire ${r.reservataire || r.entite || ''}`, null, { level: Math.min(phaseLevel + 1, 4) });
  });

  // COMITÉS
  (op.comites || []).forEach(c => {
    if (c.statut === 'planifie' && c.date) {
      const d = parseDateStr(c.date);
      if (d && dAfter(d) >= -7) add('Comité', `Préparer le comité ${c.type || ''} du ${c.date}`, d);
    }
  });

  // AAP — échéance de candidature de l'appel à projets tagué sur l'opération
  if (op.aap_id != null && op.aap_id !== '' && !isDelivered && typeof AAPS !== 'undefined') {
    const aap = AAPS.find(a => String(a._supabase_id) === String(op.aap_id));
    if (aap && (aap.statut || '') !== 'Clôturé') {
      const dl = parseDateStr(aap.date_limite);
      if (dl) {
        const tagLbl = aap.tag || aap.intitule || 'AAP';
        add('AAP', `Déposer le dossier ${tagLbl}`, dl, { detail: `date limite de candidature : ${fmt(dl)}` });
      }
    }
  }

  return tasks;
}

function renderSuivi() {
  const view = document.getElementById('view-suivi');
  if (!view) return;
  const content = view.querySelector('#suiviContent');
  if (!content) return;

  const persons = getAllPersons();
  if (persons.length === 0) {
    content.innerHTML = '<div class="suivi-empty-state">Aucune personne renseignée dans les rôles (Développeur / Resp opération / Chargé de fin).</div>';
    return;
  }
  if (!suiviSelectedPerson || !persons.includes(suiviSelectedPerson))
    suiviSelectedPerson = persons.includes('Bastien MERCIER') ? 'Bastien MERCIER' : persons[0];

  const myOps = DATA.filter(op =>
    op.developpeur === suiviSelectedPerson || op.resp_op === suiviSelectedPerson || op.charge_fin === suiviSelectedPerson);

  let tasks = myOps.flatMap(op => computeTasks(op));
  const catCounts = {};
  tasks.forEach(t => { catCounts[t.cat] = (catCounts[t.cat] || 0) + 1; });
  if (suiviCatFilter) tasks = tasks.filter(t => t.cat === suiviCatFilter);

  tasks.sort((a, b) => a.level - b.level
    || (a.days == null) - (b.days == null)
    || ((a.days == null ? 0 : a.days) - (b.days == null ? 0 : b.days))
    || String(a.op.code || '').localeCompare(String(b.op.code || '')));

  const overdue = tasks.filter(t => t.overdue).length;
  const prio = tasks.filter(t => t.level === 1).length;
  const week = tasks.filter(t => t.days != null && t.days >= 0 && t.days <= 7).length;

  const personSelector = `
    <div class="suivi-selector">
      <label class="suivi-selector-label">Suivi de :</label>
      <select class="suivi-selector-select" id="suiviPersonSelect">
        ${persons.map(p => `<option value="${escapeHtml(p)}"${p === suiviSelectedPerson ? ' selected' : ''}>${escapeHtml(p)}</option>`).join('')}
      </select>
      <span class="suivi-selector-meta">${myOps.length} opération${myOps.length > 1 ? 's' : ''} · ${tasks.length} tâche${tasks.length > 1 ? 's' : ''}</span>
    </div>`;

  const kpiHtml = `
    <div class="suivi-kpis">
      <div class="suivi-kpi ${overdue > 0 ? 'suivi-kpi-expired' : 'suivi-kpi-zero'}"><div class="suivi-kpi-num">${overdue}</div><div class="suivi-kpi-label">En retard</div></div>
      <div class="suivi-kpi ${prio > 0 ? 'suivi-kpi-critical' : 'suivi-kpi-zero'}"><div class="suivi-kpi-num">${prio}</div><div class="suivi-kpi-label">Prioritaires</div></div>
      <div class="suivi-kpi ${week > 0 ? 'suivi-kpi-warning' : 'suivi-kpi-zero'}"><div class="suivi-kpi-num">${week}</div><div class="suivi-kpi-label">Sous 7 jours</div></div>
      <div class="suivi-kpi suivi-kpi-total"><div class="suivi-kpi-num">${tasks.length}</div><div class="suivi-kpi-label">Tâches</div></div>
    </div>`;

  const totalAll = Object.values(catCounts).reduce((a, b) => a + b, 0);
  const cats = Object.keys(SUIVI_CATS).filter(c => catCounts[c]);
  const chips = `<div class="suivi-cat-chips">
      <button class="suivi-cat-chip${!suiviCatFilter ? ' active' : ''}" data-cat="">Toutes (${totalAll})</button>
      ${cats.map(c => `<button class="suivi-cat-chip${suiviCatFilter === c ? ' active' : ''}" data-cat="${escapeHtml(c)}"><span class="suivi-cat-dot" style="background:${SUIVI_CATS[c].color}"></span>${escapeHtml(c)} (${catCounts[c]})</button>`).join('')}
    </div>`;

  const GROUPS = [
    { lvl: 1, label: 'À traiter en priorité', cls: 'g1' },
    { lvl: 2, label: 'Ce mois-ci', cls: 'g2' },
    { lvl: 3, label: 'À planifier', cls: 'g3' },
    { lvl: 4, label: 'À anticiper', cls: 'g4' },
  ];
  const fmtD = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
  const taskRow = (t) => {
    const ech = t.days == null ? 'sans échéance' : (t.overdue ? `en retard de ${-t.days} j` : (t.days === 0 ? "aujourd'hui" : `dans ${t.days} j`));
    const col = (SUIVI_CATS[t.cat] || {}).color || '#888';
    return `<div class="suivi-task suivi-task-l${t.level}${t.overdue ? ' suivi-task-overdue' : ''}" data-suivi-open="${escapeHtml(t.op._uid)}">
      <span class="suivi-task-bar"></span>
      <div class="suivi-task-main">
        <div class="suivi-task-action">${escapeHtml(t.action)}</div>
        <div class="suivi-task-sub">
          <span class="suivi-task-cat" style="color:${col};border-color:${col}55;background:${col}14;">${escapeHtml(t.cat)}</span>
          <span class="suivi-task-op">${escapeHtml(t.op.code || '')} · ${escapeHtml(t.op.display_name || '')}</span>
          ${t.detail ? `<span class="suivi-task-detail">${escapeHtml(t.detail)}</span>` : ''}
        </div>
      </div>
      <div class="suivi-task-ech">${escapeHtml(ech)}${t.deadline ? `<span class="suivi-task-date">${escapeHtml(fmtD(t.deadline))}</span>` : ''}</div>
    </div>`;
  };
  const groupsHtml = GROUPS.map(g => {
    const items = tasks.filter(t => t.level === g.lvl);
    if (!items.length) return '';
    return `<div class="suivi-group suivi-group-${g.cls}">
      <div class="suivi-group-head"><span class="suivi-group-dot"></span>${g.label}<span class="suivi-group-count">${items.length}</span></div>
      <div class="suivi-group-body">${items.map(taskRow).join('')}</div>
    </div>`;
  }).join('');

  content.innerHTML = `
    ${personSelector}
    ${kpiHtml}
    ${chips}
    ${tasks.length === 0
      ? '<div class="suivi-empty-state"><i class="ti ti-circle-check"></i>Aucune tâche en cours — tout est à jour pour cette personne.</div>'
      : `<div class="suivi-tasks">${groupsHtml}</div>`}
  `;

  const select = document.getElementById('suiviPersonSelect');
  if (select) select.addEventListener('change', (e) => { suiviSelectedPerson = e.target.value; suiviCatFilter = ''; renderSuivi(); replaceTablerIcons(); });
  view.querySelectorAll('.suivi-cat-chip').forEach(b => b.addEventListener('click', () => { suiviCatFilter = b.dataset.cat; renderSuivi(); replaceTablerIcons(); }));
  view.querySelectorAll('[data-suivi-open]').forEach(el => el.addEventListener('click', () => {
    const uid = el.dataset.suiviOpen;
    const op = DATA.find(o => o._uid === uid); if (!op) return;
    selectedOpCode = op._uid; selectedTrancheIdx = 0;
    switchToTab('operations'); renderAll();
  }));
}

// ============== END SUIVI VIEW ==============

// Initialize / refresh the mini-map embed in the Localisation section of op detail
function initOpLocationMap(op) {
  // No coords → nothing to do (the HTML shows the empty state)
  if (!op || op.latitude == null || op.longitude == null) {
    // Clear existing instance if any
    if (opLocationMapInstance) {
      try { opLocationMapInstance.remove(); } catch (e) {}
      opLocationMapInstance = null;
    }
    return;
  }
  // Wait for Leaflet to load
  if (!window.L) {
    setTimeout(() => initOpLocationMap(op), 200);
    return;
  }
  const container = document.getElementById('opLocationMap');
  if (!container) return;

  // Destroy previous instance (avoids "Map container is already initialized" error on re-render)
  if (opLocationMapInstance) {
    try { opLocationMapInstance.remove(); } catch (e) {}
    opLocationMapInstance = null;
  }

  // Create new instance at neighborhood scale (zoom 16)
  opLocationMapInstance = L.map(container, {
    zoomControl: true,
    scrollWheelZoom: false, // less aggressive inside form
    attributionControl: true,
  }).setView([op.latitude, op.longitude], 16);

  // Tile layer (Plan by default) + Plan/Satellite toggle
  applyMapLayer(opLocationMapInstance, 'plan');
  addMapLayerToggle(opLocationMapInstance, 'plan');

  // Marker colored by phase
  const phase = op.phase_actuelle || 'Montage';
  const color = PHASE_MARKER_COLORS[phase] || '#666';
  const icon = buildMarkerIcon ? buildMarkerIcon(color) : null;
  const marker = L.marker([op.latitude, op.longitude], icon ? { icon } : {});
  marker.bindPopup(`<div class="map-popup-name">${escapeHtml(op.display_name || '')}</div>${op.adresse ? `<div class="map-popup-addr">${escapeHtml(op.adresse)}</div>` : ''}`);
  marker.addTo(opLocationMapInstance);

  // Force resize after potential DOM insertion / layout shifts
  setTimeout(() => {
    if (opLocationMapInstance) opLocationMapInstance.invalidateSize();
  }, 80);
}

function renderMap() {
  if (!window.L) {
    // Leaflet not yet loaded — retry shortly
    setTimeout(renderMap, 200);
    return;
  }
  const container = document.getElementById('mapContainer');
  if (!container) return;

  // Initialize map once
  if (!mapInstance) {
    mapInstance = L.map(container, { zoomControl: true }).setView([46.5, 2.5], 6); // France center
    applyMapLayer(mapInstance, 'plan');
    addMapLayerToggle(mapInstance, 'plan');
  }

  // Clear existing markers
  mapMarkers.forEach(m => mapInstance.removeLayer(m));
  mapMarkers = [];

  // Apply filters
  const q = (mapFilters.search || '').trim().toLowerCase();
  const filtered = DATA.filter(op => {
      if (!inScope(op)) return false;
    if (q) {
      const hay = [op.display_name, op.code, op.commune, op.adresse].filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    if (mapFilters.phase && (op.phase_actuelle || 'Montage') !== mapFilters.phase) return false;
    if (mapFilters.region && op.region !== mapFilters.region) return false;
    if (mapFilters.person && op.developpeur !== mapFilters.person && op.resp_op !== mapFilters.person && op.charge_fin !== mapFilters.person) return false;
    return true;
  });

  // Populate region filter dropdown (once)
  const regionSelect = document.getElementById('mapRegionFilter');
  if (regionSelect && regionSelect.options.length <= 1) {
    const regions = [...new Set(DATA.map(o => o.region).filter(Boolean))].sort();
    regions.forEach(r => {
      const opt = document.createElement('option');
      opt.value = r; opt.textContent = r;
      regionSelect.appendChild(opt);
    });
    regionSelect.value = mapFilters.region;
  }

  // Populate person filter dropdown (once)
  const personSelect = document.getElementById('mapPersonFilter');
  if (personSelect && personSelect.options.length <= 1) {
    const persons = new Set();
    DATA.forEach(o => {
      if (o.developpeur) persons.add(o.developpeur);
      if (o.resp_op) persons.add(o.resp_op);
      if (o.charge_fin) persons.add(o.charge_fin);
    });
    [...persons].sort().forEach(p => {
      const opt = document.createElement('option');
      opt.value = p; opt.textContent = p;
      personSelect.appendChild(opt);
    });
    personSelect.value = mapFilters.person;
  }

  // Place markers for ops with coordinates
  let withCoords = 0, withoutCoords = 0;
  const bounds = [];
  filtered.forEach(op => {
    if (op.latitude == null || op.longitude == null) {
      withoutCoords++;
      return;
    }
    withCoords++;
    const phase = op.phase_actuelle || 'Montage';
    const color = PHASE_MARKER_COLORS[phase] || '#666';
    const icon = buildMarkerIcon(color);
    const marker = L.marker([op.latitude, op.longitude], icon ? { icon } : {});

    // === Calculs pour pop-up enrichi ===
    // Budget total + nb tranches + nb logements
    let opBudget = 0;
    let opLgts = 0;
    const tranches = Array.isArray(op.tranches) ? op.tranches : [];
    tranches.forEach(t => {
      const b = trancheBudgetTTC(t);
      if (b !== null) opBudget += b;
      const l = trancheLogements(t);
      if (l !== null) opLgts += l;
    });

    // Prochaine échéance clé selon phase
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let nextEvent = null;
    if (op.date_livraison) {
      const d = parseDateStr(op.date_livraison);
      if (d) {
        const days = Math.floor((d - today) / 86400000);
        if (days >= -90) {
          const label = days < 0 ? `livrée il y a ${-days}j` : days === 0 ? "livraison aujourd'hui" : `livraison dans ${days}j`;
          nextEvent = { icon: 'calendar-event', label, date: op.date_livraison };
        }
      }
    }
    // Fallback : prochain comité programmé
    if (!nextEvent && Array.isArray(op.comites)) {
      const upcoming = op.comites
        .map(c => ({ c, d: parseDateStr(c.date) }))
        .filter(x => x.d && (x.d - today) >= -7 * 86400000)
        .sort((a, b) => a.d - b.d)[0];
      if (upcoming) {
        const days = Math.floor((upcoming.d - today) / 86400000);
        const lab = days < 0 ? `passé il y a ${-days}j` : days === 0 ? "aujourd'hui" : `dans ${days}j`;
        nextEvent = { icon: 'users', label: `${upcoming.c.type || 'Comité'} ${lab}`, date: upcoming.c.date };
      }
    }

    // Top 2 alertes (les plus urgentes)
    const alertsForOp = computeAlerts(op);
    const alertsCount = alertsForOp.length;

    // Liste des personnes en charge (sans titre)
    const peopleList = [op.developpeur, op.resp_op, op.charge_fin].filter(Boolean);

    // Département depuis le code postal de l'adresse, ou champ explicite
    const dept = op.departement || op.dept || '';

    const popupHtml = `
      <div class="map-popup map-popup-rich">
        <div class="map-popup-header">
          <div class="map-popup-code">${escapeHtml(op.code || op.sheet || '—')}</div>
          <div class="map-popup-name">${escapeHtml(op.display_name || '')}</div>
          ${op.adresse ? `<div class="map-popup-addr"><i class="ti ti-map-pin"></i> ${escapeHtml(op.adresse)}</div>` : ''}
          <div class="map-popup-meta">
            ${op.commune ? `<span class="map-popup-loc">${escapeHtml(op.commune)}${dept ? ` (${escapeHtml(dept)})` : ''}</span>` : ''}
            <span class="map-popup-phase" style="background:${color};color:white;">${escapeHtml(phase)}</span>
          </div>
        </div>

        <div class="map-popup-stats">
          ${opLgts > 0 ? `
            <div class="map-popup-stat">
              <i class="ti ti-home"></i>
              <span><strong>${opLgts}</strong> logement${opLgts > 1 ? 's' : ''}${tranches.length > 1 ? ` · ${tranches.length} tranches` : ''}</span>
            </div>
          ` : tranches.length > 1 ? `
            <div class="map-popup-stat">
              <i class="ti ti-stack-2"></i>
              <span><strong>${tranches.length}</strong> tranches</span>
            </div>
          ` : ''}
          ${opBudget > 0 ? `
            <div class="map-popup-stat">
              <i class="ti ti-cash"></i>
              <span><strong>${fmtEuros(opBudget)}</strong> TTC</span>
            </div>
          ` : ''}
          ${nextEvent ? `
            <div class="map-popup-stat">
              <i class="ti ti-${nextEvent.icon}"></i>
              <span>${escapeHtml(nextEvent.label)}</span>
            </div>
          ` : ''}
        </div>

        ${peopleList.length > 0 ? `
          <div class="map-popup-people">
            <i class="ti ti-users"></i>
            <span>${peopleList.map(p => escapeHtml(p)).join(' · ')}</span>
          </div>
        ` : ''}

        <button class="map-popup-open" data-op-uid="${escapeHtml(op._uid)}">Ouvrir la fiche <i class="ti ti-arrow-right"></i></button>

        ${alertsCount > 0 ? `
          <div class="map-popup-alert-badge">
            <i class="ti ti-alert-triangle"></i>
            <span>${alertsCount} alerte${alertsCount > 1 ? 's' : ''} active${alertsCount > 1 ? 's' : ''}</span>
          </div>
        ` : ''}
      </div>
    `;
    marker.bindPopup(popupHtml);
    marker.addTo(mapInstance);
    mapMarkers.push(marker);
    bounds.push([op.latitude, op.longitude]);
  });

  // Fit to bounds if markers exist
  if (bounds.length > 0) {
    if (bounds.length === 1) {
      mapInstance.setView(bounds[0], 12);
    } else {
      mapInstance.fitBounds(bounds, { padding: [40, 40], maxZoom: 11 });
    }
  }

  // Update counts
  const countEl = document.getElementById('mapCount');
  if (countEl) countEl.textContent = `${withCoords} sur ${filtered.length} affichée${filtered.length > 1 ? 's' : ''}`;
  const noGeoEl = document.getElementById('mapNoGeoCount');
  if (noGeoEl) noGeoEl.textContent = withoutCoords;

  // Wire popup buttons (delegated on the map container)
  mapInstance.off('popupopen').on('popupopen', (e) => {
    // Remplacer les icônes Tabler dans le popup juste après ouverture
    if (e.popup._contentNode) {
      replaceTablerIcons(e.popup._contentNode);
    }
    const btn = e.popup._contentNode.querySelector('.map-popup-open');
    if (btn) {
      btn.addEventListener('click', () => {
        const uid = btn.dataset.opUid;
        selectOp(uid);
        document.querySelectorAll('.topnav-tab').forEach(t => t.classList.remove('active'));
        document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
        document.querySelector('[data-view="operations"]').classList.add('active');
        document.getElementById('view-operations').classList.add('active');
      });
    }
  });

  // Force resize because the map may have been hidden
  setTimeout(() => mapInstance.invalidateSize(), 50);
}

// Setup map filter event handlers (once)
function initMapFilters() {
  const search = document.getElementById('mapSearchInput');
  if (search && !search.dataset.wired) {
    search.dataset.wired = '1';
    search.addEventListener('input', (e) => { mapFilters.search = e.target.value; renderMap(); });
  }
  ['Phase', 'Region', 'Person'].forEach(k => {
    const el = document.getElementById('map' + k + 'Filter');
    if (el && !el.dataset.wired) {
      el.dataset.wired = '1';
      el.addEventListener('change', (e) => { mapFilters[k.toLowerCase()] = e.target.value; renderMap(); });
    }
  });
  const reset = document.getElementById('mapFilterReset');
  if (reset && !reset.dataset.wired) {
    reset.dataset.wired = '1';
    reset.addEventListener('click', () => {
      mapFilters = { search: '', phase: '', region: '', person: '' };
      const s = document.getElementById('mapSearchInput'); if (s) s.value = '';
      const p = document.getElementById('mapPhaseFilter'); if (p) p.value = '';
      const r = document.getElementById('mapRegionFilter'); if (r) r.value = '';
      const pe = document.getElementById('mapPersonFilter'); if (pe) pe.value = '';
      renderMap();
    });
  }
}
