function renderGantt() {
  const wrap = document.getElementById('ganttWrap');
  if (!wrap) return;

  const { min, max } = computeGanttRange();
  ganttMin = min; ganttMax = max;
  const totalMonths = monthsBetween(min, max);
  const totalWidth = totalMonths * GANTT_MONTH_WIDTH;
  const SIDE_WIDTH = 280;

  // Build axis labels (years + months)
  let yearLabels = '';
  let monthLabels = '';
  let cursor = new Date(min.getFullYear(), min.getMonth(), 1);
  let lastYear = -1;
  for (let i = 0; i < totalMonths; i++) {
    const left = i * GANTT_MONTH_WIDTH;
    const monthIdx = cursor.getMonth();
    const year = cursor.getFullYear();
    const monthName = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'][monthIdx];
    const isQ1 = monthIdx === 0;
    if (year !== lastYear) {
      let monthsLeftInYear = 12 - monthIdx;
      const monthsRemaining = totalMonths - i;
      const span = Math.min(monthsLeftInYear, monthsRemaining);
      const yearWidth = span * GANTT_MONTH_WIDTH;
      yearLabels += `<div class="gantt-axis-year" style="left: ${left}px; width: ${yearWidth}px;">${year}</div>`;
      lastYear = year;
    }
    monthLabels += `<div class="gantt-axis-month${isQ1 ? ' q1' : ''}" style="left: ${left}px; width: ${GANTT_MONTH_WIDTH}px;">${monthName}</div>`;
    cursor = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1);
  }

  // Today indicator with label
  const today = new Date();
  let todayHtml = '';
  let todayPx = null;
  if (today >= min && today <= max) {
    todayPx = dateToPx(today, min);
  }
  const todayBadgeHtml = todayPx != null
    ? `<div class="gantt-today-badge" style="left: ${todayPx}px;"><i class="ti ti-arrow-down"></i>Aujourd'hui</div>`
    : '';

  // Apply filters
  const q = (ganttFilters.search || '').trim().toLowerCase();
  const filtered = DATA.filter(op => {
      if (!inScope(op)) return false;
    if (q) {
      const hay = [op.display_name, op.code, op.commune, op.developpeur, op.resp_op, op.charge_fin]
        .filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    if (ganttFilters.phase && (op.phase_actuelle || 'Montage') !== ganttFilters.phase) return false;
    if (ganttFilters.region && op.region !== ganttFilters.region) return false;
    if (ganttFilters.equipe) {
      const team = [op.developpeur, op.resp_op, op.charge_fin].filter(Boolean);
      if (!team.includes(ganttFilters.equipe)) return false;
    }
    return true;
  });

  // Sort by display name
  const sorted = filtered.slice().sort((a, b) =>
    (a.display_name || '').toLowerCase().localeCompare((b.display_name || '').toLowerCase())
  );

  // Phase bar definitions: pairs of (start_field, end_field, label, color, key)
  const PHASE_BARS = [
    { start: 'date_promesse', end: 'date_acte_auth', label: 'Acquisition', color: '#888780', key: 'acq' },
    { start: 'date_depot_pc', end: 'date_obt_pc', label: 'Instruction PC', color: '#9333ea', key: 'pc' },
    { start: 'date_os', end: 'date_livraison', label: 'Chantier', color: '#185fa5', key: 'chantier' },
    { start: 'date_livraison', end: null, label: 'GPA', color: '#1d9e75', key: 'gpa', duration_months: 12 },
  ];

  const rowsHtml = sorted.map(op => {
    // Build phase bars
    const barsHtml = PHASE_BARS.map(bar => {
      const dStart = parseDateStr(op[bar.start]);
      if (!dStart) return '';
      let dEnd;
      if (bar.end) {
        dEnd = parseDateStr(op[bar.end]);
      } else if (bar.duration_months) {
        // For GPA: extrapolate
        const d = parseDateStr(op[bar.start]);
        if (!d) return '';
        dEnd = new Date(d); dEnd.setMonth(dEnd.getMonth() + bar.duration_months);
      }
      if (!dEnd || dEnd <= dStart) return '';
      const clipStart = dStart < min ? min : dStart;
      const clipEnd = dEnd > max ? max : dEnd;
      if (clipEnd <= clipStart) return '';
      const left = dateToPx(clipStart, min);
      const width = Math.max(4, dateToPx(clipEnd, min) - left);
      const fullTitle = `${bar.label} · ${fmtDateStr(dStart)} → ${fmtDateStr(dEnd)}${bar.duration_months ? ' (estimation)' : ''}`;
      return `<div class="gantt-phase-bar gantt-phase-${bar.key}" style="left:${left}px; width:${width}px; background:${bar.color};" title="${escapeHtml(fullTitle)}">
        <span class="gantt-phase-label">${escapeHtml(bar.label)}</span>
      </div>`;
    }).join('');

    // Build dots (jalons)
    const dotsHtml = GANTT_DATES.map(({key, color, label}) => {
      const d = parseDateStr(op[key]);
      if (!d) return '';
      if (d < min) return '';
      const left = dateToPx(d, min);
      const title = `${label} — ${op.display_name} — ${fmtDateStr(d)}`;
      return `<div class="gantt-dot" style="left: ${left}px; background: ${color};" data-op="${op._uid}" data-field="${key}" data-label="${escapeHtml(label)}" data-color="${color}" title="${escapeHtml(title)}"></div>`;
    }).join('');

    // Phase badge
    const phaseConf = PHASE_COLORS[op.phase_actuelle || 'Montage'] || PHASE_COLORS['Montage'];
    const phaseBadge = `<span class="gantt-side-phase" style="background:${phaseConf.bg};color:${phaseConf.text};">${escapeHtml(op.phase_actuelle || 'Montage')}</span>`;

    // Number of tranches indicator
    const trCount = (op.tranches || []).length;
    const trBadge = trCount > 0 ? `<span class="gantt-side-tranches" title="${trCount} tranche${trCount>1?'s':''}">${trCount} tr.</span>` : '';

    return `
      <tr>
        <td class="gantt-side" data-op-row="${op._uid}">
          <div class="gantt-side-line1">
            <span class="op-code-cell">${escapeHtml(op.code || op.sheet || '—')}</span>
            ${phaseBadge}
          </div>
          <div class="gantt-side-line2">
            <span class="op-name-cell">${escapeHtml(op.display_name || '')}</span>
            ${trBadge}
          </div>
        </td>
        <td class="gantt-track-cell">
          <div class="gantt-track" style="width: ${totalWidth}px; background-size: ${GANTT_MONTH_WIDTH}px 100%;">
            ${todayPx != null ? `<div class="gantt-today-line" style="left: ${todayPx}px;"></div>` : ''}
            ${barsHtml}
            ${dotsHtml}
          </div>
        </td>
      </tr>
    `;
  }).join('');

  // Populate filter dropdowns
  const regions = [...new Set(DATA.map(o => o.region).filter(Boolean))].sort();
  const teams = [...new Set(DATA.flatMap(o => [o.developpeur, o.resp_op, o.charge_fin]).filter(Boolean))].sort();

  const filterBar = `
    <div class="gantt-filter-bar">
      <input type="text" class="synth-filter-input" id="ganttSearchInput" placeholder="Recherche : nom, code, commune, équipe…" value="${escapeHtml(ganttFilters.search || '')}">
      <select class="synth-filter-select" id="ganttPhaseFilter">
        <option value="">Toutes les phases</option>
        ${['Montage','Validation CA','Travaux','Livraison','GPA'].map(p => `<option value="${p}"${ganttFilters.phase===p?' selected':''}>${p}</option>`).join('')}
      </select>
      <select class="synth-filter-select" id="ganttRegionFilter">
        <option value="">Toutes les régions</option>
        ${regions.map(r => `<option value="${escapeHtml(r)}"${ganttFilters.region===r?' selected':''}>${escapeHtml(r)}</option>`).join('')}
      </select>
      <select class="synth-filter-select" id="ganttEquipeFilter">
        <option value="">Toutes les équipes</option>
        ${teams.map(t => `<option value="${escapeHtml(t)}"${ganttFilters.equipe===t?' selected':''}>${escapeHtml(t)}</option>`).join('')}
      </select>
      <button class="synth-filter-reset" id="ganttFilterReset" title="Réinitialiser les filtres"><i class="ti ti-x"></i>Reset</button>
      <span class="synth-count">${sorted.length} sur ${DATA.length} opération${DATA.length > 1 ? 's' : ''}</span>
    </div>
  `;

  wrap.innerHTML = `
    ${filterBar}
    <div class="gantt-scroll-area">
      <table class="gantt-table">
        <colgroup>
          <col style="width: ${SIDE_WIDTH}px;">
          <col style="width: ${totalWidth}px;">
        </colgroup>
        <thead>
          <tr>
            <th class="gantt-side-header">OPÉRATION</th>
            <th class="gantt-axis-th">
              <div class="gantt-axis" style="width: ${totalWidth}px;">
                ${yearLabels}${monthLabels}
                ${todayBadgeHtml}
              </div>
            </th>
          </tr>
        </thead>
        <tbody>${rowsHtml || '<tr><td colspan="2" class="gantt-empty">Aucune opération ne correspond aux filtres.</td></tr>'}</tbody>
      </table>
    </div>
  `;

  // Wire filter events
  const searchInput = document.getElementById('ganttSearchInput');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      ganttFilters.search = e.target.value;
      renderGantt(); replaceTablerIcons();
      // Refocus the input after re-render
      requestAnimationFrame(() => {
        const i = document.getElementById('ganttSearchInput');
        if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); }
      });
    });
  }
  ['Phase','Region','Equipe'].forEach(key => {
    const el = document.getElementById('gantt' + key + 'Filter');
    if (el) el.addEventListener('change', (e) => {
      ganttFilters[key.toLowerCase()] = e.target.value;
      renderGantt(); replaceTablerIcons();
    });
  });
  const resetBtn = document.getElementById('ganttFilterReset');
  if (resetBtn) resetBtn.addEventListener('click', () => {
    ganttFilters = { search: '', phase: '', region: '', equipe: '' };
    renderGantt(); replaceTablerIcons();
  });

  // Wire click on side to open op
  wrap.querySelectorAll('[data-op-row]').forEach(el => {
    el.addEventListener('click', (e) => {
      // Don't trigger when clicking on a dropdown or input inside (none here, but safe)
      if (e.target.closest('input, select, button')) return;
      selectOp(el.dataset.opRow);
      document.querySelectorAll('.topnav-tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
      document.querySelector('[data-view="operations"]').classList.add('active');
      document.getElementById('view-operations').classList.add('active');
    });
  });

  setupGanttDragHandlers();

  // Auto-scroll today into view
  if (todayPx != null) {
    requestAnimationFrame(() => {
      const scrollArea = wrap.querySelector('.gantt-scroll-area');
      if (scrollArea) {
        const visibleTrack = scrollArea.clientWidth - SIDE_WIDTH;
        scrollArea.scrollLeft = Math.max(0, todayPx - visibleTrack * 0.25);
      }
    });
  }
}

let ganttTooltip = null;
function setupGanttDragHandlers() {
  let dragging = null;

  document.querySelectorAll('.gantt-dot').forEach(dot => {
    dot.addEventListener('mousedown', (e) => {
      if (!ganttEditMode) return;
      e.preventDefault();
      e.stopPropagation();
      dragging = {
        el: dot,
        startX: e.clientX,
        startLeft: parseFloat(dot.style.left),
        opCode: dot.dataset.op,
        field: dot.dataset.field,
        label: dot.dataset.label,
      };
      dot.classList.add('dragging');
      // Create tooltip
      ganttTooltip = document.createElement('div');
      ganttTooltip.className = 'gantt-tooltip';
      document.body.appendChild(ganttTooltip);
    });
  });

  document.addEventListener('mousemove', (e) => {
    if (!dragging) return;
    const delta = e.clientX - dragging.startX;
    const newLeft = Math.max(0, dragging.startLeft + delta);
    dragging.el.style.left = newLeft + 'px';
    // Update tooltip
    if (ganttTooltip) {
      const newDate = pxToDate(newLeft, ganttMin);
      ganttTooltip.textContent = `${dragging.label} : ${fmtDateStr(newDate)}`;
      ganttTooltip.style.left = (e.clientX + 12) + 'px';
      ganttTooltip.style.top = (e.clientY - 8) + 'px';
    }
  });

  document.addEventListener('mouseup', (e) => {
    if (!dragging) return;
    const newLeft = parseFloat(dragging.el.style.left);
    const newDate = pxToDate(newLeft, ganttMin);
    const op = findOp(dragging.opCode);
    if (op) {
      op[dragging.field] = fmtDateStr(newDate);
      saveOpToSupabase(op);
      showToast(`${dragging.label} de ${op.display_name} : ${fmtDateStr(newDate)}`, 'check');
    }
    dragging.el.classList.remove('dragging');
    if (ganttTooltip) {
      ganttTooltip.remove();
      ganttTooltip = null;
    }
    dragging = null;
    // Re-render to refresh tooltips and any other dot positions
    renderGantt();
    replaceTablerIcons();
    // Also refresh op detail if currently viewing this op
    if (selectedOpCode === op._uid) renderOpDetail();
  });
}

