// Extract sortable value from a cell
function synthSortValue(col, d) {
  let raw = col.sortValue ? col.sortValue(d) : col.get(d);
  if (raw == null || raw === '—' || raw === '') return null;
  // If raw is HTML (raw: true), strip tags for fallback
  if (col.raw) raw = String(raw).replace(/<[^>]+>/g, '').trim();
  const s = String(raw);
  // Try date DD/MM/YYYY
  const dm = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (dm) return new Date(+dm[3], +dm[2] - 1, +dm[1]).getTime();
  // Try number (with €, M€, k€, %, spaces, commas)
  const cleaned = s.replace(/\s/g, '').replace(',', '.');
  const numMatch = cleaned.match(/^-?\d+(\.\d+)?/);
  if (numMatch) {
    let n = parseFloat(numMatch[0]);
    if (cleaned.includes('M€')) n *= 1e6;
    else if (cleaned.includes('k€')) n *= 1e3;
    return n;
  }
  return s.toLowerCase();
}

// Per-op aggregation — computed fresh each render to reflect edits
function synthData(op, pretsFilter) {
  const tranches = op.tranches || [];
  const subv = op.subventions || [];
  const prets = (op.prets || []).filter(p => !pretsFilter || pretsFilter(p));
  const gar = op.garanties || [];
  const prefin = op.prefinancements || [];
  const res = op.reservataires || [];

  // Volumétrie consolidée
  const vol = { plai: 0, plus: 0, pls: 0, pli: 0, libre: 0, autre: 0 };
  tranches.forEach(t => {
    if (t.vol) Object.keys(vol).forEach(k => { vol[k] += Number(t.vol[k]) || 0; });
  });

  // Subventions
  const subvDem = subv.reduce((s, x) => s + (Number(x.montant_demande) || 0), 0);
  const subvNotif = subv.reduce((s, x) => s + (Number(x.montant_notifie) || 0), 0);
  const subvNbNotif = subv.filter(x => x.montant_notifie || ['Notifiée','Convention signée'].includes(x.statut)).length;

  // Prêts
  const pretsSim = prets.reduce((s, x) => s + (Number(x.montant_sim) || 0), 0);
  const pretsLO = prets.reduce((s, x) => s + (Number(x.montant_lo) || 0), 0);
  const pretsContrat = prets.reduce((s, x) => s + (Number(x.montant_contrat) || 0), 0);
  const pretsADem = prets.filter(x => !x.statut || x.statut === 'À demander').length;
  const pretsInstr = prets.filter(x => ['En instruction','Demandé','Dossier transmis'].includes(x.statut)).length;
  const pretsLOObt = prets.filter(x => x.statut === "Lettre d'offre" || (x.montant_lo && !x.montant_contrat)).length;
  const pretsSignes = prets.filter(x => x.statut === 'Contrat signé' || x.montant_contrat).length;
  // Banques distinctes pour cette op (alphabétique)
  const pretsBanques = [...new Set(prets.map(x => x.financeur).filter(Boolean))].sort().join(' · ') || '—';

  // Garanties
  const garADem = gar.filter(x => !x.statut || x.statut === 'À demander').length;
  const garDem = gar.filter(x => x.statut === 'Dossier transmis').length;
  const garAccord = gar.filter(x => x.statut === 'Accord de principe reçu').length;
  const garDelib = gar.filter(x => x.statut === 'Délibération votée').length;
  const garConv = gar.filter(x => x.statut === 'Convention signée').length;
  // Couverture garantie (%) : prévisionnelle (>= accord de principe) et actée (convention signée)
  const _garantissable = prets.filter(p => !p.non_garanti && !/^\s*als\b/i.test(p.ligne || ''));
  const _garBase = _garantissable.reduce((s, p) => s + (Number(p.montant_contrat) || Number(p.montant_lo) || Number(p.montant_sim) || 0), 0);
  const _garMontant = (g) => {
    if (Number(g.montant_couvert)) return Number(g.montant_couvert);
    const p = prets.find(pp => (pp.ligne || '') === (g.pret_lie || '') && (pp.tranche || '') === (g.tranche || ''));
    const m = p ? (Number(p.montant_contrat) || Number(p.montant_lo) || Number(p.montant_sim) || 0) : 0;
    const q = Number(g.quotite) || 0;
    return m * (q > 1 ? q / 100 : q);
  };
  const _garPrevStatuts = new Set(['Accord de principe reçu', 'Délibération votée', 'Convention signée']);
  const garPctPrev = _garBase > 0 ? Math.min(gar.filter(x => _garPrevStatuts.has(x.statut)).reduce((s, g) => s + _garMontant(g), 0) / _garBase, 1) : 0;
  const garPctActe = _garBase > 0 ? Math.min(gar.filter(x => x.statut === 'Convention signée').reduce((s, g) => s + _garMontant(g), 0) / _garBase, 1) : 0;

  // Préfinancements
  const prefinCouvert = prefin.reduce((s, x) => s + (Number(x.montant_couvert) || 0), 0);
  const prefinTire = prefin.reduce((s, x) => s + (Number(x.montant_tire) || 0), 0);
  const prefinPctTire = prefinCouvert > 0 ? prefinTire / prefinCouvert : 0;
  const prefinEnCours = prefin.filter(x => x.statut === 'En cours').length;
  const prefinSoldes = prefin.filter(x => x.statut === 'Soldé').length;
  // Earliest date_fin (first non-null in sort)
  const prefinDateFin = prefin.map(x => x.date_fin).filter(Boolean).sort()[0] || null;

  // Réservataires
  const resLgts = res.reduce((s, x) => s + (Number(x.nb_logements) || 0), 0);
  // % réservé = logements réservés / total logements de l'op (et non somme des % par tranche)
  const _opLgtsRes = totalLgts(op) || 0;
  const resPctSum = _opLgtsRes > 0 ? Math.min(resLgts / _opLgtsRes, 1) : 0;
  const resValid = res.filter(x => ['Validé','Conventionné','DU sur opération'].includes(x.etape)).length;
  const resNego = res.filter(x => ['À demander','En négociation'].includes(x.etape)).length;

  // Agrément (take from first tranche with data)
  const yearProg = tranches.find(t => t.annee_prog)?.annee_prog || '—';
  const nSiap = tranches.find(t => t.n_siap)?.n_siap || '—';
  const agrStatut = tranches.find(t => t.statut_agrement)?.statut_agrement || '—';
  const typeEtab = tranches[0]?.type_structure || '—';
  const gestionnaire = tranches.find(t => t.gestionnaire)?.gestionnaire || '—';

  return {
    op,
    nbTranches: tranches.length,
    totalLgts: totalLgts(op),
    totalSurface: opTotalSurface(op),
    vol,
    totalBudget: totalBudget(op),
    totalPrets: opTotalPrets(op),
    totalSubv: opTotalSubv(op),
    totalFP: totalFondsPropres(op),
    equilibre: (totalBudget(op) == null)
      ? null
      : (totalBudget(op) - ((opTotalPrets(op) || 0) + (opTotalSubv(op) || 0) + (totalFondsPropres(op) || 0))),
    typeEtab, gestionnaire,
    gestionnaireDetail: synthPerTranche(tranches, t => t.gestionnaire),
    yearProg, nSiap, agrStatut,
    agrCategorie: synthPerTranche(tranches, t => t.nature),
    agrBeneficiaire: synthPerTranche(tranches, t => t.public_cible),
    agrLgts: synthAgrLgts(tranches),
    convTypeRedevance: synthPerTranche(tranches, t => t.type_redevance),
    convMontantRedevance: synthPerTranche(tranches, t => t.montant_redevance),
    convAccordRedevance: synthPerTranche(tranches, t => t.conv_loc_montant_loyer),
    convDateValeur: synthPerTranche(tranches, t => t.conv_loc_date_valeur),
    convGrille: synthPerTranche(tranches, t => t.conv_loc_grille),
    convDateAccordRedev: synthPerTranche(tranches, t => t.date_accord_redev),
    subvNb: subv.length, subvDem, subvNotif, subvNbNotif,
    pretsNb: prets.length, pretsSim, pretsLO, pretsContrat, pretsADem, pretsInstr, pretsLOObt, pretsSignes, pretsBanques,
    garNb: gar.length, garADem, garDem, garAccord, garDelib, garConv, garPctPrev, garPctActe,
    prefinNb: prefin.length, prefinCouvert, prefinTire, prefinPctTire, prefinEnCours, prefinSoldes, prefinDateFin,
    resNb: new Set(res.map(x => (x.reservataire || x.entite || '').trim().toLowerCase()).filter(Boolean)).size, resLgts, resPctSum, resValid, resNego,
  };
}

function synthTrCode(t) { return t.code_full ? t.code_full.split('-').slice(1).join('-') : (t.id || ''); }
function synthPerTranche(tranches, getVal) {
  const parts = tranches.map(t => ({ code: synthTrCode(t), val: getVal(t) })).filter(p => p.val != null && p.val !== '' && p.val !== '—');
  if (parts.length === 0) return '—';
  const distinct = [...new Set(parts.map(p => String(p.val)))];
  if (distinct.length === 1) return distinct[0];
  return parts.map(p => `${p.val} (${p.code})`).join(' · ');
}
function synthVolBreakdown(t) {
  const va = (t.vol_agree && Object.values(t.vol_agree).some(x => Number(x) > 0)) ? t.vol_agree : (t.vol || {});
  return ['plai','plus','pls','pli','libre','autre'].filter(k => Number(va[k]) > 0).map(k => `${va[k]} ${k.toUpperCase()}`).join(' / ');
}
function synthAgrLgts(tranches) {
  const parts = tranches.map(t => ({ code: synthTrCode(t), bd: synthVolBreakdown(t) })).filter(p => p.bd);
  if (parts.length === 0) return '—';
  if (parts.length === 1) return parts[0].bd;
  return parts.map(p => `${p.code}: ${p.bd}`).join(' · ');
}

