function renderSynthTabs() {
  const c = document.getElementById('synthTabs');
  if (!c) return;
  c.innerHTML = SYNTH_TABS.map(t => `
    <div class="synth-tab${t.id === synthActiveTab ? ' active' : ''}" data-synth-tab="${t.id}">
      <i class="ti ti-${t.icon}"></i>${escapeHtml(t.label)}
    </div>
  `).join('');
  c.querySelectorAll('[data-synth-tab]').forEach(el => {
    el.addEventListener('click', () => {
      if (synthActiveTab !== el.dataset.synthTab) {
        // Reset sort and contextual filters on tab change
        synthSort = { tabId: null, colIdx: null, direction: null };
        // Clear filters that are not in the common set
        const common = ['phase', 'region', 'equipe', 'type_travaux'];
        Object.keys(synthFilters).forEach(k => {
          if (!common.includes(k)) delete synthFilters[k];
        });
        synthDateFilter = { field: 'date_os', from: '', to: '' };
      }
      synthActiveTab = el.dataset.synthTab;
      storageSet('synthTab', synthActiveTab);
      renderSynthTabs();
      renderSynthContextFilters();
      renderSynthTable();
      replaceTablerIcons();
    });
  });
}

function synthDateToYM(v) {
  if (!v) return null;
  const m = String(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  return m ? (m[3] + '-' + m[2].padStart(2, '0')) : null;
}

function renderSynthTable() {
  const table = document.getElementById('synthTable');
  const countEl = document.getElementById('synthCount');
  if (!table) return;
  const tab = SYNTH_TABS.find(t => t.id === synthActiveTab) || SYNTH_TABS[0];

  // Free-text search filter
  const q = synthFilter.trim().toLowerCase();
  const tabFilters = TAB_FILTERS[synthActiveTab] || [];
  // En vue Prêts filtrée par banque : ne garder, dans la ligne, que les prêts de la banque filtrée
  const pretBankFilter = (synthActiveTab === 'prets' && synthFilters.pret_banque)
    ? (p => _synthEq(p.financeur, synthFilters.pret_banque))
    : null;
  let filtered = DATA.filter(op => {
    if (!inScope(op)) return false;
    if (q) {
      const hay = [op.display_name, op.code, op.commune, op.departement,
                   op.developpeur, op.resp_op, op.charge_fin, op.promoteur,
                   op.region, op.adresse].filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    // Common dropdown filters
    if (synthFilters.phase && (op.phase_actuelle || 'Montage') !== synthFilters.phase) return false;
    if (synthFilters.region && op.region !== synthFilters.region) return false;
    if (synthFilters.equipe) {
      const team = [op.developpeur, op.resp_op, op.charge_fin].filter(Boolean);
      if (!team.includes(synthFilters.equipe)) return false;
    }
    if (synthFilters.type_travaux && op.type_travaux !== synthFilters.type_travaux) return false;
    // Tab-contextual filters
    for (const f of tabFilters) {
      const val = synthFilters[f.id];
      if (val && !f.match(op, val)) return false;
    }
    // Filtre de période (onglet Travaux & Calendrier)
    if (synthActiveTab === 'travaux' && synthDateFilter.field && (synthDateFilter.from || synthDateFilter.to)) {
      const ym = synthDateToYM(op[synthDateFilter.field]);
      if (!ym) return false;
      if (synthDateFilter.from && ym < synthDateFilter.from) return false;
      if (synthDateFilter.to && ym > synthDateFilter.to) return false;
    }
    return true;
  });

  // Apply sort (or default: alphabetical by display_name)
  const sortActive = synthSort.tabId === tab.id && synthSort.colIdx != null && synthSort.direction;
  if (sortActive) {
    const col = tab.cols[synthSort.colIdx];
    const dir = synthSort.direction === 'asc' ? 1 : -1;
    filtered = filtered.slice().map(op => ({ op, d: synthData(op, pretBankFilter) }));
    filtered.sort((a, b) => {
      const av = synthSortValue(col, a.d);
      const bv = synthSortValue(col, b.d);
      if (av == null && bv == null) return 0;
      if (av == null) return 1; // nulls always last
      if (bv == null) return -1;
      if (av < bv) return -1 * dir;
      if (av > bv) return 1 * dir;
      return 0;
    });
    filtered = filtered.map(x => x.op);
  } else {
    filtered.sort((a, b) => (a.display_name || '').toLowerCase().localeCompare((b.display_name || '').toLowerCase()));
  }

  if (countEl) {
    countEl.textContent = q
      ? `${filtered.length} / ${DATA.length} opérations`
      : `${DATA.length} opérations`;
  }

  // Compute the sticky-left widths (Code is ~80px, Nom ~220px)
  const stickyCodeWidth = 90;
  const stickyNameLeft = stickyCodeWidth;

  // Sortable column headers — clickable with sort arrow
  const colHeads = tab.cols.map((col, idx) => {
    const isSorted = sortActive && synthSort.colIdx === idx;
    let arrow = '';
    if (isSorted) arrow = synthSort.direction === 'asc' ? ' ↑' : ' ↓';
    return `<th class="${col.align === 'num' ? 'num' : ''} sortable" data-col-idx="${idx}" style="cursor: pointer; user-select: none;">${escapeHtml(col.label)}<span class="sort-arrow">${arrow}</span></th>`;
  }).join('');

  const headHtml = `
    <thead>
      <tr>
        <th class="sticky-left" style="background: var(--bg-secondary); min-width: ${stickyCodeWidth}px;">Code</th>
        <th class="sticky-left-2" style="left: ${stickyNameLeft}px; background: var(--bg-secondary); min-width: 220px;">Nom</th>
        ${colHeads}
      </tr>
    </thead>
  `;

  if (filtered.length === 0) {
    table.innerHTML = headHtml + `<tbody><tr><td colspan="${2 + tab.cols.length}" class="synth-empty">Aucune opération ne correspond au filtre.</td></tr></tbody>`;
    bindSortHeaders(table);
    return;
  }

  const bodyHtml = '<tbody>' + filtered.map(op => {
    const d = synthData(op, pretBankFilter);
    return `
      <tr class="clickable" data-op="${op._uid}">
        <td class="sticky-left code-cell">${escapeHtml(op.code || op.sheet || '—')}</td>
        <td class="sticky-left-2" style="left: ${stickyNameLeft}px;">${escapeHtml(op.display_name)}</td>
        ${tab.cols.map(col => {
          const v = col.get(d);
          const klass = col.align === 'num' ? 'num' : '';
          const muted = (v === '—' || v === '') ? ' muted' : '';
          return `<td class="${klass}${muted}">${col.raw ? v : escapeHtml(String(v))}</td>`;
        }).join('')}
      </tr>
    `;
  }).join('') + '</tbody>';

  table.innerHTML = headHtml + bodyHtml;
  table.querySelectorAll('[data-op]').forEach(el => {
    el.addEventListener('click', () => {
      selectOp(el.dataset.op);
      document.querySelectorAll('.topnav-tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
      document.querySelector('[data-view="operations"]').classList.add('active');
      document.getElementById('view-operations').classList.add('active');
    });
  });
  bindSortHeaders(table);
}

function bindSortHeaders(table) {
  table.querySelectorAll('th.sortable').forEach(th => {
    th.addEventListener('click', (e) => {
      const idx = parseInt(th.dataset.colIdx, 10);
      // Cycle: asc → desc → off (and target current tab)
      if (synthSort.tabId === synthActiveTab && synthSort.colIdx === idx) {
        if (synthSort.direction === 'asc') {
          synthSort.direction = 'desc';
        } else if (synthSort.direction === 'desc') {
          synthSort = { tabId: null, colIdx: null, direction: null };
        }
      } else {
        synthSort = { tabId: synthActiveTab, colIdx: idx, direction: 'asc' };
      }
      renderSynthTable();
    });
  });
}

function renderSynthContextFilters() {
  const container = document.getElementById('synthContextFilters');
  if (!container) return;
  const filters = TAB_FILTERS[synthActiveTab] || [];
  let html = filters.map(f => {
    const opts = f.source();
    const optsHtml = ['<option value="">— ' + escapeHtml(f.label) + ' —</option>']
      .concat(opts.map(o => `<option value="${escapeHtml(o)}"${synthFilters[f.id] === o ? ' selected' : ''}>${escapeHtml(o)}</option>`))
      .join('');
    return `<select class="synth-filter-select synth-filter-contextual" data-filter="${f.id}">${optsHtml}</select>`;
  }).join('');

  // Filtre de période (onglet Travaux & Calendrier)
  if (synthActiveTab === 'travaux') {
    const dateFields = [
      ['date_os', 'Date OS'], ['date_livraison', 'Livraison'],
      ['date_depot_pc', 'Dépôt PC'], ['date_obt_pc', 'Obt. PC'],
      ['date_promesse', 'Promesse'], ['date_acte_auth', 'Acte auth.'],
    ];
    const fieldOpts = dateFields.map(([k, lbl]) => `<option value="${k}"${synthDateFilter.field === k ? ' selected' : ''}>${escapeHtml(lbl)}</option>`).join('');
    html += `<select class="synth-filter-select synth-filter-contextual" id="synthDateField" title="Date filtrée">${fieldOpts}</select>`
      + `<input type="month" class="synth-filter-select synth-filter-contextual" id="synthDateFrom" value="${synthDateFilter.from}" title="De (mois)">`
      + `<input type="month" class="synth-filter-select synth-filter-contextual" id="synthDateTo" value="${synthDateFilter.to}" title="À (mois)">`;
  }

  if (!html) { container.innerHTML = ''; return; }
  container.innerHTML = html;

  // Wire events on newly created selects
  container.querySelectorAll('select[data-filter]').forEach(sel => {
    sel.addEventListener('change', (e) => {
      synthFilters[e.target.dataset.filter] = e.target.value;
      renderSynthTable();
    });
  });
  const dF = container.querySelector('#synthDateField');
  const dFrom = container.querySelector('#synthDateFrom');
  const dTo = container.querySelector('#synthDateTo');
  if (dF) dF.addEventListener('change', e => { synthDateFilter.field = e.target.value; renderSynthTable(); });
  if (dFrom) dFrom.addEventListener('change', e => { synthDateFilter.from = e.target.value; renderSynthTable(); });
  if (dTo) dTo.addEventListener('change', e => { synthDateFilter.to = e.target.value; renderSynthTable(); });
}

// ============== SAVED VIEWS for Synthese ==============
function renderSavedViews() {
  const c = document.getElementById('synthSavedList');
  if (!c) return;
  if (synthSavedViews.length === 0) {
    c.innerHTML = '<span class="synth-saved-empty">Aucune vue sauvegardée pour l\'instant.</span>';
    return;
  }
  c.innerHTML = synthSavedViews.map(v => `
    <button class="synth-saved-chip${synthActiveViewId === v.id ? ' active' : ''}" data-view-id="${escapeHtml(v.id)}" title="Appliquer cette vue">
      <span class="synth-saved-chip-name">${escapeHtml(v.name)}</span>
      <span class="synth-saved-chip-x" data-view-delete="${escapeHtml(v.id)}" title="Supprimer cette vue">×</span>
    </button>
  `).join('');
  c.querySelectorAll('[data-view-id]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      if (e.target.closest('[data-view-delete]')) return; // delete click handled separately
      applySavedView(btn.dataset.viewId);
    });
  });
  c.querySelectorAll('[data-view-delete]').forEach(x => {
    x.addEventListener('click', (e) => {
      e.stopPropagation();
      deleteSavedView(x.dataset.viewDelete);
    });
  });
}

function saveCurrentView() {
  const name = prompt('Nom de la vue (ex : "Mes ops PLAI 2026", "Travaux en cours") :');
  if (!name || !name.trim()) return;
  const id = 'view-' + Date.now();
  synthSavedViews.push({
    id,
    name: name.trim(),
    tab: synthActiveTab,
    filter: synthFilter,
    filters: { ...synthFilters },
  });
  synthActiveViewId = id;
  persistSavedViews();
  renderSavedViews();
  showToast(`Vue « ${name.trim()} » sauvegardée`, 'bookmark');
}

function applySavedView(id) {
  const v = synthSavedViews.find(x => x.id === id);
  if (!v) return;
  synthActiveTab = v.tab || synthActiveTab;
  synthFilter = v.filter || '';
  synthFilters = { ...v.filters };
  synthActiveViewId = id;
  // Refresh UI controls
  const filterInput = document.getElementById('synthFilter');
  if (filterInput) filterInput.value = synthFilter;
  document.querySelectorAll('.synth-filter-select').forEach(sel => {
    const key = sel.dataset.filter;
    if (key && synthFilters[key] != null) sel.value = synthFilters[key];
  });
  // Re-render everything that depends on the active tab
  renderSynthTabs();
  populateSynthFilters();
  renderSynthContextFilters();
  renderSynthTable();
  renderSavedViews();
  showToast(`Vue « ${v.name} » appliquée`, 'bookmark');
}

function deleteSavedView(id) {
  const v = synthSavedViews.find(x => x.id === id);
  if (!v) return;
  if (!confirm(`Supprimer la vue « ${v.name} » ?`)) return;
  synthSavedViews = synthSavedViews.filter(x => x.id !== id);
  if (synthActiveViewId === id) synthActiveViewId = null;
  persistSavedViews();
  renderSavedViews();
  showToast('Vue supprimée', 'trash');
}

// Reset active view marker when user changes filters manually (after view applied)
function clearActiveView() { synthActiveViewId = null; renderSavedViews(); }
// ============== END SAVED VIEWS ==============

function renderOpTable() {
  // Initialize the new tabbed synthese (replacing the old single table)
  renderSynthTabs();
  populateSynthFilters();
  renderSynthContextFilters();
  renderSynthTable();

  // Hook up the filter input
  const filterInput = document.getElementById('synthFilter');
  if (filterInput && !filterInput.dataset.bound) {
    filterInput.dataset.bound = '1';
    filterInput.addEventListener('input', (e) => {
      synthFilter = e.target.value;
      renderSynthTable();
      clearActiveView();
    });
  }
  // Hook up dropdown filters
  document.querySelectorAll('.synth-filter-select[data-filter]').forEach(sel => {
    if (sel.dataset.bound) return;
    sel.dataset.bound = '1';
    sel.addEventListener('change', (e) => {
      synthFilters[e.target.dataset.filter] = e.target.value;
      renderSynthTable();
      clearActiveView();
    });
  });
  // Hook up reset
  const resetBtn = document.getElementById('synthFilterReset');
  if (resetBtn && !resetBtn.dataset.bound) {
    resetBtn.dataset.bound = '1';
    resetBtn.addEventListener('click', () => {
      synthFilter = '';
      synthFilters = { phase: '', region: '', equipe: '', type_travaux: '' };
      synthDateFilter = { field: 'date_os', from: '', to: '' };
      if (filterInput) filterInput.value = '';
      document.querySelectorAll('.synth-filter-select[data-filter]').forEach(s => s.value = '');
      renderSynthContextFilters();
      renderSynthTable();
      clearActiveView();
    });
  }
  // Saved views: add button + render
  const addBtn = document.getElementById('synthSavedAdd');
  if (addBtn && !addBtn.dataset.bound) {
    addBtn.dataset.bound = '1';
    addBtn.addEventListener('click', saveCurrentView);
  }
  renderSavedViews();
}

function renderReferentiels() {
  const grid = document.getElementById('referentielsGrid');
  if (!grid) return;
  grid.innerHTML = Object.entries(REFERENTIELS).map(([key, ref]) => {
    return `
      <div class="ref-card" data-ref-key="${escapeHtml(key)}">
        <div class="ref-card-head">
          <div>
            <div class="ref-card-title">${escapeHtml(ref.label)}</div>
            <div class="ref-card-sub">clé : <code>${escapeHtml(key)}</code> · ${ref.items.length} ${ref.items.length > 1 ? 'entrées' : 'entrée'}</div>
          </div>
        </div>
        <ul class="ref-items">
          ${ref.items.map((item, idx) => `
            <li class="ref-item">
              <input class="ref-item-input" data-ref-key="${escapeHtml(key)}" data-ref-idx="${idx}" value="${escapeHtml(item)}">
              <button class="ref-item-del" data-ref-key="${escapeHtml(key)}" data-ref-idx="${idx}" title="Supprimer cette entrée"><i class="ti ti-trash"></i></button>
            </li>
          `).join('')}
        </ul>
        <div class="ref-card-foot">
          <input class="ref-new-input" data-ref-key="${escapeHtml(key)}" placeholder="Nouvelle entrée…">
          <button class="ref-add-btn" data-ref-key="${escapeHtml(key)}"><i class="ti ti-plus"></i>Ajouter</button>
        </div>
      </div>
    `;
  }).join('');
  // Wire events — persistance vers Supabase
  grid.querySelectorAll('.ref-item-input').forEach(input => {
    input.addEventListener('change', async (e) => {
      const k = e.target.dataset.refKey;
      const idx = parseInt(e.target.dataset.refIdx, 10);
      const newVal = e.target.value.trim();
      if (newVal === '') return;
      const oldVal = REFERENTIELS[k].items[idx];
      REFERENTIELS[k].items[idx] = newVal;
      // Persistance Supabase
      const id = REFERENTIELS[k]._ids?.[idx];
      if (id) {
        const ok = await updateReferentielItem(id, newVal);
        if (ok) showToast(`« ${newVal} » mis à jour dans ${REFERENTIELS[k].label}`, 'check');
        else { REFERENTIELS[k].items[idx] = oldVal; e.target.value = oldVal; }
      } else {
        showToast(`« ${newVal} » modifié en mémoire (non persisté)`, 'alert-circle');
      }
    });
  });
  grid.querySelectorAll('.ref-item-del').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const b = e.currentTarget;
      const k = b.dataset.refKey;
      const idx = parseInt(b.dataset.refIdx, 10);
      const item = REFERENTIELS[k].items[idx];
      if (!confirm(`Supprimer « ${item} » de ${REFERENTIELS[k].label} ?`)) return;
      const id = REFERENTIELS[k]._ids?.[idx];
      if (id) {
        const ok = await deleteReferentielItem(id);
        if (!ok) return; // garde la valeur en cas d'échec
      }
      REFERENTIELS[k].items.splice(idx, 1);
      if (REFERENTIELS[k]._ids) REFERENTIELS[k]._ids.splice(idx, 1);
      renderReferentiels();
      replaceTablerIcons();
      showToast(`« ${item} » supprimé`, 'check');
    });
  });
  grid.querySelectorAll('.ref-add-btn').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      const b = e.currentTarget;
      const k = b.dataset.refKey;
      const card = b.closest('.ref-card');
      const newInput = card.querySelector('.ref-new-input');
      const val = newInput.value.trim();
      if (!val) { newInput.focus(); return; }
      if (REFERENTIELS[k].items.includes(val)) {
        showToast('Cette entrée existe déjà', 'alert-circle');
        return;
      }
      // Persistance Supabase d'abord
      const order = REFERENTIELS[k].items.length;
      const newId = await addReferentielItem(k, REFERENTIELS[k].label, val, order);
      if (newId) {
        REFERENTIELS[k].items.push(val);
        if (!REFERENTIELS[k]._ids) REFERENTIELS[k]._ids = [];
        REFERENTIELS[k]._ids.push(newId);
        newInput.value = '';
        renderReferentiels();
        replaceTablerIcons();
        showToast(`« ${val} » ajouté à ${REFERENTIELS[k].label}`, 'check');
      } else {
        showToast("Erreur lors de l'ajout", 'alert-triangle');
      }
    });
  });
  grid.querySelectorAll('.ref-new-input').forEach(input => {
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const card = e.target.closest('.ref-card');
        card.querySelector('.ref-add-btn').click();
      }
    });
  });
}

// ===== Helpers de persistance des référentiels vers Supabase =====
async function updateReferentielItem(id, newValue) {
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/referentiels?id=eq.${id}`, {
      method: 'PATCH', headers, body: JSON.stringify({ item_value: newValue }),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('updateReferentielItem error:', err);
    showToast('Erreur mise à jour : ' + err.message, 'alert-triangle');
    return false;
  }
}

async function deleteReferentielItem(id) {
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/referentiels?id=eq.${id}`, {
      method: 'DELETE', headers,
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    return true;
  } catch (err) {
    console.error('deleteReferentielItem error:', err);
    showToast('Erreur suppression : ' + err.message, 'alert-triangle');
    return false;
  }
}

async function addReferentielItem(refKey, refLabel, value, order) {
  try {
    const headers = {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${AUTH_TOKEN}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    };
    const payload = {
      ref_key: refKey,
      ref_label: refLabel,
      item_value: value,
      item_order: order,
      is_active: true,
    };
    const res = await fetch(`${SUPABASE_URL}/rest/v1/referentiels`, {
      method: 'POST', headers, body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error('Status ' + res.status);
    const created = await res.json();
    return Array.isArray(created) ? created[0]?.id : created.id;
  } catch (err) {
    console.error('addReferentielItem error:', err);
    return null;
  }
}

function populateSynthFilters() {
  // Populate region dropdown from unique values in DATA
  const regionSel = document.getElementById('synthFilterRegion');
  if (regionSel && regionSel.options.length <= 1) {
    const regions = [...new Set(DATA.map(o => o.region).filter(Boolean))].sort();
    regions.forEach(r => {
      const opt = document.createElement('option');
      opt.value = r; opt.textContent = r;
      regionSel.appendChild(opt);
    });
  }
  // Populate équipe dropdown (union of developpeur, resp_op, charge_fin)
  const equipeSel = document.getElementById('synthFilterEquipe');
  if (equipeSel && equipeSel.options.length <= 1) {
    const teams = new Set();
    DATA.forEach(o => {
      [o.developpeur, o.resp_op, o.charge_fin].filter(Boolean).forEach(p => teams.add(p));
    });
    [...teams].sort().forEach(p => {
      const opt = document.createElement('option');
      opt.value = p; opt.textContent = p;
      equipeSel.appendChild(opt);
    });
  }
  // Populate type travaux dropdown
  const travauxSel = document.getElementById('synthFilterTravaux');
  if (travauxSel && travauxSel.options.length <= 1) {
    const types = [...new Set(DATA.map(o => o.type_travaux).filter(Boolean))].sort();
    types.forEach(t => {
      const opt = document.createElement('option');
      opt.value = t; opt.textContent = t;
      travauxSel.appendChild(opt);
    });
  }
}

// View switching
// Theme toggle (dark / light)
// ============== SECTIONS REPLIABLES (fiche opération) ==============
let collapsedSections = (() => { try { return JSON.parse(storageGet('collapsedSections') || '{}'); } catch (e) { return {}; } })();
function saveCollapsedSections() { storageSet('collapsedSections', JSON.stringify(collapsedSections)); }

function osnLabelEl(sec) {
  return sec.querySelector(':scope > .section-label, :scope > .subent-header .subent-title, :scope > .timeline-toggle .section-label');
}
function osnLabelText(lab) {
  if (!lab) return '';
  const clone = lab.cloneNode(true);
  clone.querySelectorAll('button, select, input, .auto-tag').forEach(n => n.remove());
  return clone.textContent.replace(/\s+/g, ' ').trim();
}
function osnKeyOf(sec) {
  const t = osnLabelText(osnLabelEl(sec));
  return t.replace(/·.*$/, '').trim().toLowerCase();
}
function applyCollapsedSections() {
  document.querySelectorAll('#opDetail .section, #trancheDetail .section').forEach(sec => {
    const key = osnKeyOf(sec);
    if (key) sec.classList.toggle('collapsed', !!collapsedSections[key]);
  });
}

// Tout replier / tout déplier : si au moins une section est dépliée -> tout replier, sinon tout déplier
function toggleAllSections() {
  const secs = [...document.querySelectorAll('#opDetail .section, #trancheDetail .section')];
  if (!secs.length) return;
  const anyOpen = secs.some(s => !s.classList.contains('collapsed'));
  secs.forEach(sec => {
    const k = osnKeyOf(sec);
    if (!k) return;
    sec.classList.toggle('collapsed', anyOpen);
    if (anyOpen) collapsedSections[k] = 1; else delete collapsedSections[k];
  });
  saveCollapsedSections();
  const btn = document.getElementById('opFoldAllBtn');
  if (btn) {
    const i = btn.querySelector('i, .tabler-svg-icon');
    if (i) { i.className = 'ti ' + (anyOpen ? 'ti-unfold-all' : 'ti-fold-all'); }
    btn.title = anyOpen ? 'Tout déplier' : 'Tout replier';
    if (typeof replaceTablerIcons === 'function') replaceTablerIcons();
  }
}

// Repli/dépli au clic sur les titres de sections (hors timeline qui a son toggle)
document.addEventListener('click', (e) => {
  if (e.target.closest('button, a, input, select, textarea, .icon-btn, .add-row-btn, .timeline-toggle')) return;
  const head = e.target.closest('.section-label, .subent-header');
  if (!head) return;
  const sec = head.parentElement;
  if (!sec || !sec.classList.contains('section')) return;
  if (!sec.closest('#opDetail, #trancheDetail')) return;
  sec.classList.toggle('collapsed');
  const k = osnKeyOf(sec);
  if (k) {
    if (sec.classList.contains('collapsed')) collapsedSections[k] = 1; else delete collapsedSections[k];
    saveCollapsedSections();
  }
});

// Réapplication après chaque re-render (les renderers remplacent l'innerHTML)
(function initCollapseObserver() {
  let raf = null;
  const obs = new MutationObserver(() => {
    if (raf) return;
    raf = requestAnimationFrame(() => { raf = null; applyCollapsedSections(); });
  });
  ['opDetail', 'trancheDetail'].forEach(id => {
    const el = document.getElementById(id);
    if (el) obs.observe(el, { childList: true, subtree: true });
  });
})();

