(function initTheme() {
  const root = document.documentElement;
  const toggle = document.getElementById('themeToggle');
  if (toggle) {
    toggle.addEventListener('click', () => {
      const current = root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
      const next = current === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      storageSet('theme', next);
    });

    // Easter egg : 5 clics rapides => mode arc-en-ciel (1 s de sécurité avant de pouvoir le couper)
    let _rbClicks = [], _rbOn = false, _rbLock = 0;
    toggle.addEventListener('click', (e) => {
      const now = Date.now();
      if (_rbOn) {
        if (now < _rbLock) { e.stopImmediatePropagation(); e.preventDefault(); return; }
        _rbOn = false;
        const fx = document.getElementById('rainbowFx'); if (fx) fx.remove();
        e.stopImmediatePropagation(); e.preventDefault();
        if (typeof showToast === 'function') showToast('Mode arc-en-ciel désactivé', 'palette');
        return;
      }
      _rbClicks.push(now);
      _rbClicks = _rbClicks.filter(t => now - t < 1200);
      if (_rbClicks.length >= 5) {
        _rbClicks = [];
        _rbOn = true; _rbLock = now + 1000;
        if (!document.getElementById('rainbowFx')) {
          const fx = document.createElement('div'); fx.id = 'rainbowFx'; document.body.appendChild(fx);
        }
        e.stopImmediatePropagation(); e.preventDefault();
        if (typeof showToast === 'function') showToast('Mode arc-en-ciel activé \u2014 reclique sur le thème pour quitter', 'palette');
      }
    }, true);
  }
})();

// Global field-modification tracker: any input touched during edit mode gets a visual cue
(function initFieldModificationTracker() {
  document.addEventListener('input', (e) => {
    if (!editMode) return;
    const el = e.target;
    if (!el || !(el.matches && el.matches('input, select, textarea'))) return;
    // Only inputs that are part of an editable form, not the search/filter inputs
    if (el.closest('.synth-filter, .sidebar-search, .gantt-filter-bar, #ganttSearchInput')) return;
    el.classList.add('field-modified-session');
  });
  document.addEventListener('change', (e) => {
    if (!editMode) return;
    const el = e.target;
    if (!el || !(el.matches && el.matches('input, select, textarea'))) return;
    if (el.closest('.synth-filter, .sidebar-search, .gantt-filter-bar, #ganttSearchInput')) return;
    el.classList.add('field-modified-session');
  });
})();

// Global validator: pour les champs avec data-validate, on valide à la volée
// Affiche une bordure rouge + un message d'erreur si invalide
(function initFieldValidator() {
  // Regex pour date au format français DD/MM/YYYY
  const dateFrRe = /^(0?[1-9]|[12]\d|3[01])\/(0?[1-9]|1[0-2])\/\d{4}$/;
  const isValidDateFr = (str) => {
    if (!str) return true; // vide = valide (champ optionnel)
    if (!dateFrRe.test(str)) return false;
    // Vérifie la cohérence (ex: 31/02/2025 invalide)
    const [d, m, y] = str.split('/').map(Number);
    const dt = new Date(y, m - 1, d);
    return dt.getDate() === d && dt.getMonth() === m - 1 && dt.getFullYear() === y;
  };
  const isValidNumber = (str) => {
    if (!str) return true;
    return !isNaN(Number(str)) && isFinite(Number(str));
  };

  const validateEl = (el) => {
    if (!el || !el.dataset || !el.dataset.validate) return;
    const v = el.value.trim();
    let valid = true;
    let errMsg = '';
    if (el.dataset.validate === 'date-fr') {
      valid = isValidDateFr(v);
      if (!valid) errMsg = 'Format attendu : JJ/MM/AAAA';
    } else if (el.dataset.validate === 'number') {
      valid = isValidNumber(v);
      if (!valid) errMsg = 'Nombre attendu';
    }
    if (valid) {
      el.classList.remove('field-invalid');
      // Retire le message d'erreur s'il existe
      const next = el.nextElementSibling;
      if (next && next.classList.contains('field-error-msg')) next.remove();
    } else {
      el.classList.add('field-invalid');
      // Ajoute/met à jour le message d'erreur
      let msg = el.nextElementSibling;
      if (!msg || !msg.classList.contains('field-error-msg')) {
        msg = document.createElement('div');
        msg.className = 'field-error-msg';
        el.parentNode.insertBefore(msg, el.nextSibling);
      }
      msg.textContent = errMsg;
    }
  };

  document.addEventListener('input', (e) => {
    const el = e.target;
    if (el && el.matches && el.matches('input[data-validate]')) {
      validateEl(el);
    }
  });
  document.addEventListener('blur', (e) => {
    const el = e.target;
    if (el && el.matches && el.matches('input[data-validate]')) {
      validateEl(el);
    }
  }, true);
})();

// Global stepper click delegation (robust to re-renders)
(function initStepperClicks() {
  document.addEventListener('click', (e) => {
    const item = e.target.closest('[data-stepper-action]');
    if (!item) return;
    e.preventDefault();
    e.stopPropagation();
    const action = item.dataset.stepperAction;
    const arg = item.dataset.stepperArg;
    if (action === 'viewCurrent') {
      viewCurrentPhase();
    } else if (action === 'viewSnap') {
      const idx = parseInt(arg, 10);
      if (!isNaN(idx)) viewSnapshot(idx);
    }
  });
})();

// Tag click delegation: remove, show-linked, or add via Enter key
(function initTagActions() {
  document.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('[data-tag-action="remove"]');
    if (removeBtn) {
      e.preventDefault();
      e.stopPropagation();
      const idx = parseInt(removeBtn.dataset.tagIdx, 10);
      removeOpTag(idx);
      return;
    }
    const showLinked = e.target.closest('[data-tag-action="show-linked"]');
    if (showLinked) {
      e.preventDefault();
      e.stopPropagation();
      showTagLinkedPopover(showLinked, showLinked.dataset.tagValue);
      return;
    }
  });
  // Enter in tag input adds the tag
  document.addEventListener('keydown', (e) => {
    if (e.target && e.target.id === 'opTagInput' && e.key === 'Enter') {
      e.preventDefault();
      const val = (e.target.value || '').trim();
      if (val) {
        addOpTag(val);
        e.target.value = '';
      }
    }
  });
  // Blur on tag input also adds (if value present)
  document.addEventListener('blur', (e) => {
    if (e.target && e.target.id === 'opTagInput') {
      const val = (e.target.value || '').trim();
      if (val) {
        addOpTag(val);
        e.target.value = '';
      }
    }
  }, true);
})();

function addOpTag(tagValue) {
  const op = findOp(selectedOpCode);
  if (!op) return;
  const clean = tagValue.trim();
  if (!clean) return;
  if (!Array.isArray(op.tags)) op.tags = [];
  // Case-insensitive dedupe (but preserve user's casing)
  if (!op.tags.some(t => t.toLowerCase() === clean.toLowerCase())) {
    op.tags.push(clean);
    saveOpToSupabase(op);
  }
  renderOpDetail();
  renderSidebar();
  replaceTablerIcons();
  requestAnimationFrame(() => {
    const i = document.getElementById('opTagInput');
    if (i) i.focus();
  });
}

function removeOpTag(idx) {
  const op = findOp(selectedOpCode);
  if (!op || !Array.isArray(op.tags)) return;
  op.tags.splice(idx, 1);
  renderOpDetail();
  renderSidebar();
  replaceTablerIcons();
  saveOpToSupabase(op);
}

// Show a popover listing ops linked by this tag
function showTagLinkedPopover(anchorEl, tagValue) {
  // Close existing popover
  document.querySelectorAll('.tag-linked-popover').forEach(p => p.remove());
  const op = findOp(selectedOpCode);
  if (!op) return;
  // Find ops sharing this exact tag
  const linked = DATA.filter(o =>
    o._uid !== op._uid
    && Array.isArray(o.tags)
    && o.tags.includes(tagValue)
  );
  const pop = document.createElement('div');
  pop.className = 'tag-linked-popover';
  pop.innerHTML = `
    <div class="tag-linked-head"><i class="ti ti-tag"></i>Tag « ${escapeHtml(tagValue)} »<button class="tag-linked-close" type="button">×</button></div>
    ${linked.length === 0
      ? '<div class="tag-linked-empty">Aucune autre opération ne porte ce tag.</div>'
      : `<ul class="tag-linked-list">
          ${linked.map(o => {
            const phaseConf = PHASE_COLORS[o.phase_actuelle || 'Montage'] || PHASE_COLORS['Montage'];
            return `<li data-linked-op-uid="${escapeHtml(o._uid)}">
              <span class="tag-linked-code">${escapeHtml(o.code || o.sheet || '—')}</span>
              <span class="tag-linked-name">${escapeHtml(o.display_name || '')}</span>
              <span class="tag-linked-phase" style="background:${phaseConf.bg};color:${phaseConf.text};">${escapeHtml(o.phase_actuelle || 'Montage')}</span>
            </li>`;
          }).join('')}
        </ul>`}
  `;
  // Position relative to clicked tag
  const rect = anchorEl.getBoundingClientRect();
  pop.style.position = 'fixed';
  pop.style.top = (rect.bottom + 4) + 'px';
  pop.style.left = rect.left + 'px';
  document.body.appendChild(pop);
  replaceTablerIcons(pop);
  // Wire links
  pop.querySelectorAll('[data-linked-op-uid]').forEach(li => {
    li.addEventListener('click', () => {
      selectOp(li.dataset.linkedOpUid);
      pop.remove();
    });
  });
  pop.querySelector('.tag-linked-close').addEventListener('click', () => pop.remove());
  // Click outside closes
  setTimeout(() => {
    const outside = (e) => {
      if (!pop.contains(e.target)) {
        pop.remove();
        document.removeEventListener('click', outside);
      }
    };
    document.addEventListener('click', outside);
  }, 0);
}

