// Envoie une op modifiée vers Supabase via PATCH, ainsi que ses entités liées
async function saveOpToSupabase(op) {
  // Extraire l'id Supabase depuis le _uid (format : "op-supabase-1" → 1)
  const supabaseId = op._supabase_id || (op._uid ? parseInt(op._uid.replace('op-supabase-', '')) : null);
  if (!supabaseId || isNaN(supabaseId)) {
    console.warn('UID non Supabase, sauvegarde locale uniquement:', op._uid);
    return;
  }
  const headers = {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${AUTH_TOKEN}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation',
  };
  try {
    // 1. Sauvegarder les champs de l'op (tous les champs Supabase)
    const opPayload = {
      code: op.code,
      display_name: op.display_name,
      phase_actuelle: op.phase_actuelle,
      commune: op.commune,
      code_postal: op.code_postal,
      region: op.region,
      departement: op.departement,
      adresse: op.adresse,
      zone_abc: op.zone_abc,
      zone_123: op.zone_123,
      lien_sharepoint: op.lien_sharepoint,
      promoteur: op.promoteur,
      developpeur: op.developpeur,
      resp_op: op.resp_op,
      charge_fin: op.charge_fin,
      latitude: op.latitude,
      longitude: op.longitude,
      vefa_mod: op.vefa_mod,
      notaire: op.notaire,
      aap_id: (op.aap_id != null && op.aap_id !== '') ? Number(op.aap_id) : null,
      aap_tranche: op.aap_tranche || null,
      type_travaux: op.type_travaux,
      maitrise_fonciere: op.maitrise_fonciere,
      anru: op.anru,
      label_certif: op.label_certif,
      mode_constructif: op.mode_constructif,
      mode_chauffage: op.mode_chauffage,
      nb_batiments: op.nb_batiments,
      perf_seuil: op.perf_seuil,
      perf_certif: op.perf_certif,
      date_promesse: op.date_promesse,
      date_acte_auth: op.date_acte_auth || op.date_acte,
      date_depot_pc: op.date_depot_pc,
      date_obtention_pc: op.date_obtention_pc,
      date_os: op.date_os,
      date_livraison: op.date_livraison,
      date_conv_apl: op.date_conv_apl,
      date_conv_loc: op.date_conv_loc,
      date_ca_axentia: op.date_ca_axentia,
      notes_libres: op.notes_libres,
      jalons_reel: op.jalons_reel || {},
      deleted_at: op.deleted_at || null,
    };
    const opResponse = await fetch(`${SUPABASE_URL}/rest/v1/operations?id=eq.${supabaseId}`, {
      method: 'PATCH', headers, body: JSON.stringify(opPayload),
    });
    if (!opResponse.ok) throw new Error('Op: ' + opResponse.status + ' — ' + await opResponse.text());

    // 2. Synchroniser tranches / prêts / garanties / subventions / réservataires / comités / workflows / tags
    await syncEntitiesToSupabase(op, supabaseId);

    console.log('Sauvegardé dans Supabase : op', supabaseId, 'et entités liées');
    showToast('Modifications enregistrées dans Supabase', 'check');
  } catch (err) {
    console.error('Erreur sauvegarde Supabase :', err);
    showToast('Erreur Supabase : ' + err.message, 'alert-triangle');
  }
}

// Synchronise les tranches / prêts / garanties d'une op vers Supabase
// Stratégie : pour chaque entité locale, INSERT si pas d'_supabase_id, sinon PATCH
// Pour les entités présentes sur Supabase mais absentes en mémoire, DELETE
async function syncEntitiesToSupabase(op, operationId) {
  const headers = {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${AUTH_TOKEN}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation',
  };

  // === TRANCHES ===
  // 1. Récupérer les tranches actuelles sur Supabase pour cette op
  const trRes = await fetch(`${SUPABASE_URL}/rest/v1/tranches?operation_id=eq.${operationId}&select=id`, {
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` }
  });
  const remoteTranches = trRes.ok ? await trRes.json() : [];
  const remoteTrIds = new Set(remoteTranches.map(t => t.id));

  // 2. Pour chaque tranche locale, UPDATE ou INSERT
  const localTrIds = new Set();
  const trancheIdMap = {}; // ancien id local → nouvel id Supabase (pour resync prêts/garanties)

  for (const t of (op.tranches || [])) {
    const trPayload = buildTranchePayload(t, operationId);
    if (t._supabase_id) {
      // UPDATE
      await fetch(`${SUPABASE_URL}/rest/v1/tranches?id=eq.${t._supabase_id}`, {
        method: 'PATCH', headers, body: JSON.stringify(trPayload),
      });
      localTrIds.add(t._supabase_id);
      trancheIdMap[t.id] = t._supabase_id;
    } else {
      // INSERT
      const ins = await fetch(`${SUPABASE_URL}/rest/v1/tranches`, {
        method: 'POST', headers, body: JSON.stringify(trPayload),
      });
      if (ins.ok) {
        const created = await ins.json();
        const newId = Array.isArray(created) ? created[0]?.id : created.id;
        if (newId) {
          t._supabase_id = newId;
          localTrIds.add(newId);
          trancheIdMap[t.id] = newId;
        }
      }
    }
  }

  // 3. DELETE les tranches supprimées localement (présentes remote mais pas local)
  for (const remoteId of remoteTrIds) {
    if (!localTrIds.has(remoteId)) {
      await fetch(`${SUPABASE_URL}/rest/v1/tranches?id=eq.${remoteId}`, {
        method: 'DELETE', headers,
      });
    }
  }

  // === PRÊTS ===
  const prRes = await fetch(`${SUPABASE_URL}/rest/v1/prets?operation_id=eq.${operationId}&select=id`, {
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` }
  });
  const remotePrets = prRes.ok ? await prRes.json() : [];
  const remotePrIds = new Set(remotePrets.map(p => p.id));
  const localPrIds = new Set();
  const pretLigneToSupabaseId = {}; // pour les garanties qui pointent vers une ligne de prêt

  for (const p of (op.prets || [])) {
    // Retrouver le tranche_id Supabase à partir du suffixe local (RSJA, etc.)
    const trancheSupabaseId = findTrancheSupabaseIdFromSuffix(op, p.tranche);
    const prPayload = buildPretPayload(p, operationId, trancheSupabaseId);
    if (p._supabase_id) {
      await fetch(`${SUPABASE_URL}/rest/v1/prets?id=eq.${p._supabase_id}`, {
        method: 'PATCH', headers, body: JSON.stringify(prPayload),
      });
      localPrIds.add(p._supabase_id);
      pretLigneToSupabaseId[p.ligne] = p._supabase_id;
    } else {
      const ins = await fetch(`${SUPABASE_URL}/rest/v1/prets`, {
        method: 'POST', headers, body: JSON.stringify(prPayload),
      });
      if (ins.ok) {
        const created = await ins.json();
        const newId = Array.isArray(created) ? created[0]?.id : created.id;
        if (newId) {
          p._supabase_id = newId;
          localPrIds.add(newId);
          pretLigneToSupabaseId[p.ligne] = newId;
        }
      }
    }
  }

  for (const remoteId of remotePrIds) {
    if (!localPrIds.has(remoteId)) {
      await fetch(`${SUPABASE_URL}/rest/v1/prets?id=eq.${remoteId}`, {
        method: 'DELETE', headers,
      });
    }
  }

  // === GARANTIES ===
  const gaRes = await fetch(`${SUPABASE_URL}/rest/v1/garanties?operation_id=eq.${operationId}&select=id`, {
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` }
  });
  const remoteGaranties = gaRes.ok ? await gaRes.json() : [];
  const remoteGaIds = new Set(remoteGaranties.map(g => g.id));
  const localGaIds = new Set();

  for (const g of (op.garanties || [])) {
    const trancheSupabaseId = findTrancheSupabaseIdFromSuffix(op, g.tranche);
    const pretSupabaseId = pretLigneToSupabaseId[g.pret_lie] || null;
    const gaPayload = buildGarantiePayload(g, operationId, trancheSupabaseId, pretSupabaseId);
    if (g._supabase_id) {
      await fetch(`${SUPABASE_URL}/rest/v1/garanties?id=eq.${g._supabase_id}`, {
        method: 'PATCH', headers, body: JSON.stringify(gaPayload),
      });
      localGaIds.add(g._supabase_id);
    } else {
      const ins = await fetch(`${SUPABASE_URL}/rest/v1/garanties`, {
        method: 'POST', headers, body: JSON.stringify(gaPayload),
      });
      if (ins.ok) {
        const created = await ins.json();
        const newId = Array.isArray(created) ? created[0]?.id : created.id;
        if (newId) {
          g._supabase_id = newId;
          localGaIds.add(newId);
        }
      }
    }
  }

  for (const remoteId of remoteGaIds) {
    if (!localGaIds.has(remoteId)) {
      await fetch(`${SUPABASE_URL}/rest/v1/garanties?id=eq.${remoteId}`, {
        method: 'DELETE', headers,
      });
    }
  }

  // === SUBVENTIONS ===
  await syncSimpleEntity({
    op, operationId, headers,
    tableName: 'subventions',
    localItems: op.subventions || [],
    buildPayload: (s) => ({
      operation_id: operationId,
      tranche_id: findTrancheSupabaseIdFromSuffix(op, s.tranche),
      // Colonne 'type' ← champ front 'financement'
      type: s.financement || s.type || '',
      financeur: s.financeur || '',
      montant_simule: s.montant_simule,
      date_simule: s.date_simule || null,
      montant_demande: s.montant_demande,
      date_demande: s.date_demande || null,
      // Colonne 'date_notif' ← champ front 'date_notification'
      date_notif: s.date_notification || s.date_notif || null,
      // Colonne 'montant_notif' ← champ front 'montant_notifie' (LE bug signalé)
      montant_notif: (s.montant_notifie !== undefined && s.montant_notifie !== null) ? s.montant_notifie : s.montant_notif,
      // Colonne 'date_conv_signature' ← champ front 'date_conv'
      date_conv_signature: s.date_conv || s.date_conv_signature || null,
      montant_verse: s.montant_verse,
      date_versement_prevue: s.date_versement_prevue || null,
      statut: s.statut || '',
      // Colonne 'notes' ← champ front 'commentaires'
      notes: s.commentaires || s.notes || '',
      lien_sp_conv: s.lien_sp_conv || '',
      contact: s.contact || '',
      n_arrete: s.n_arrete || '',
      lien_sp_notif: s.lien_sp_notif || '',
      nb_droits_reserves: s.nb_droits_reserves,
      aap_id: s.aap_id ? Number(s.aap_id) : null,
    }),
  });

  // === RÉSERVATAIRES ===
  await syncSimpleEntity({
    op, operationId, headers,
    tableName: 'reservataires',
    localItems: op.reservataires || [],
    buildPayload: (r) => ({
      operation_id: operationId,
      tranche_id: findTrancheSupabaseIdFromSuffix(op, r.tranche),
      // Colonne 'entite' ← champ front 'reservataire'
      entite: r.reservataire || r.entite || '',
      // Colonne 'nb_logements_reserves' ← champ front 'nb_logements'
      nb_logements_reserves: (r.nb_logements !== undefined && r.nb_logements !== null) ? r.nb_logements : r.nb_logements_reserves,
      // Colonne 'type_reservation' ← champ front 'financement'
      type_reservation: r.financement || r.type_reservation || '',
      // Colonne 'statut' ← champ front 'etape'
      statut: r.etape || r.statut || '',
      date_demande: r.date_demande || null,
      date_conv: r.date_conv || null,
      contact: r.contact || '',
      // Colonne 'notes' ← champ front 'commentaires'
      notes: r.commentaires || r.notes || '',
      pct_reserve: r.pct_reserve,
      lien_sharepoint: r.lien_sharepoint || '',
    }),
  });

  // === PRÉFINANCEMENTS ===
  await syncSimpleEntity({
    op, operationId, headers,
    tableName: 'prefinancements',
    localItems: op.prefinancements || [],
    buildPayload: (pf) => ({
      operation_id: operationId,
      tranche_id: findTrancheSupabaseIdFromSuffix(op, pf.tranche),
      pret_id: pretLigneToSupabaseId[pf.pret_lie] || null,
      banque: pf.banque || '',
      montant_couvert: pf.montant_couvert,
      montant_tire: pf.montant_tire,
      pct_tire: pf.pct_tire,
      date_debut: pf.date_debut || null,
      date_fin: pf.date_fin || null,
      statut: pf.statut || '',
      taux: pf.taux || '',
      duree_prefi: pf.duree_prefi,
      notes: pf.commentaires || pf.notes || '',
      lien_sharepoint: pf.lien_sharepoint || '',
    }),
  });

  // === AVENANTS ===
  await syncSimpleEntity({
    op, operationId, headers,
    tableName: 'avenants',
    localItems: op.avenants || [],
    buildPayload: (a) => ({
      operation_id: operationId,
      tranche_id: findTrancheSupabaseIdFromSuffix(op, a.tranche),
      pret_id: pretLigneToSupabaseId[a.pret_lie] || null,
      n_avenant: a.n_avenant || '',
      date_avenant: a.date_avenant || null,
      objet: a.objet || '',
      nouveau_montant: a.nouveau_montant,
      nouvelle_duree: a.nouvelle_duree,
      nouveau_taux: a.nouveau_taux || '',
      statut: a.statut || '',
      notes: a.commentaires || a.notes || '',
      lien_sharepoint: a.lien_sharepoint || '',
      gar_garant: a.gar_garant || '',
      gar_quotite: a.gar_quotite,
      gar_statut: a.gar_statut || '',
      gar_date_demande: a.gar_date_demande || null,
      gar_date_conv: a.gar_date_conv || null,
    }),
  });

  // === COMITÉS ===
  await syncSimpleEntity({
    op, operationId, headers,
    tableName: 'comites',
    localItems: op.comites || [],
    buildPayload: (c) => ({
      operation_id: operationId,
      type: c.type || '',
      date: c.date || null,
      lieu: c.lieu || '',
      statut: c.statut || 'realise',
      planning_id: c.planning_id || null,
      notes: c.notes || '',
      doc_name: c.doc_name || null,
      doc_size: c.doc_size || null,
      doc_data_url: c.doc_data_url || null,
      lien_sharepoint: c.lien_sharepoint || '',
    }),
  });

  // === TAGS === (modèle particulier : on ne stocke que le nom du tag)
  // On commence par supprimer tous les tags actuels pour cette op, puis on réinsère
  await fetch(`${SUPABASE_URL}/rest/v1/tags?operation_id=eq.${operationId}`, {
    method: 'DELETE', headers,
  });
  const tagNames = (op.tags || []).filter(t => t);
  if (tagNames.length > 0) {
    await fetch(`${SUPABASE_URL}/rest/v1/tags`, {
      method: 'POST', headers,
      body: JSON.stringify(tagNames.map(name => ({ operation_id: operationId, tag_name: name }))),
    });
  }
}

// Helper générique pour synchroniser une entité simple (1 table, pas de sous-relations)
async function syncSimpleEntity({ op, operationId, headers, tableName, localItems, buildPayload }) {
  // Récupérer les remote ids
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${tableName}?operation_id=eq.${operationId}&select=id`, {
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` }
  });
  const remote = res.ok ? await res.json() : [];
  const remoteIds = new Set(remote.map(r => r.id));
  const localIds = new Set();

  for (const item of localItems) {
    const payload = buildPayload(item);
    if (item._supabase_id) {
      await fetch(`${SUPABASE_URL}/rest/v1/${tableName}?id=eq.${item._supabase_id}`, {
        method: 'PATCH', headers, body: JSON.stringify(payload),
      });
      localIds.add(item._supabase_id);
    } else {
      const ins = await fetch(`${SUPABASE_URL}/rest/v1/${tableName}`, {
        method: 'POST', headers, body: JSON.stringify(payload),
      });
      if (ins.ok) {
        const created = await ins.json();
        const newId = Array.isArray(created) ? created[0]?.id : created.id;
        if (newId) {
          item._supabase_id = newId;
          localIds.add(newId);
        }
      }
    }
  }

  // DELETE remote items absent en local
  for (const remoteId of remoteIds) {
    if (!localIds.has(remoteId)) {
      await fetch(`${SUPABASE_URL}/rest/v1/${tableName}?id=eq.${remoteId}`, {
        method: 'DELETE', headers,
      });
    }
  }
}

