// Helper: retrouver le _supabase_id d'une tranche à partir de son suffixe (RSJA, etc.)
function findTrancheSupabaseIdFromSuffix(op, suffix) {
  if (!suffix) return null;
  const t = (op.tranches || []).find(tr => {
    const trSuffix = tr.code_full ? tr.code_full.split('-').slice(1).join('-') : '';
    return trSuffix === suffix;
  });
  return t?._supabase_id || null;
}

// ============== AUTHENTIFICATION (Supabase Auth · email + mot de passe) ==============
const AUTH_STORE_KEY = 'exnihilo_auth';
function authSaveSession(s){ try{ sessionStorage.setItem(AUTH_STORE_KEY, JSON.stringify(s)); }catch(e){} }
function authLoadSession(){ try{ return JSON.parse(sessionStorage.getItem(AUTH_STORE_KEY) || 'null'); }catch(e){ return null; } }
function authClear(){ try{ sessionStorage.removeItem(AUTH_STORE_KEY); }catch(e){} AUTH_TOKEN = SUPABASE_KEY; }

async function authLogin(email, password){
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  const data = await res.json().catch(()=>({}));
  if (!res.ok) throw new Error(data.error_description || data.msg || data.message || 'Identifiants invalides');
  const _md = (data.user && data.user.user_metadata) || {};
  const _mail = (data.user && data.user.email) || email || '';
  const session = {
    access_token: data.access_token,
    refresh_token: data.refresh_token,
    expires_at: Date.now() + ((data.expires_in || 3600) * 1000),
    email: _mail,
    name: _md.display_name || _md.full_name || _md.name || (_mail.split('@')[0] || 'Utilisateur')
  };
  AUTH_TOKEN = session.access_token;
  authSaveSession(session);
  return session;
}

async function authRefresh(refresh_token){
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
    method: 'POST',
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token })
  });
  const data = await res.json().catch(()=>({}));
  if (!res.ok) throw new Error('refresh failed');
  const _md2 = (data.user && data.user.user_metadata) || {};
  const _prev = authLoadSession() || {};
  const _mail2 = (data.user && data.user.email) || _prev.email || '';
  const session = {
    access_token: data.access_token,
    refresh_token: data.refresh_token,
    expires_at: Date.now() + ((data.expires_in || 3600) * 1000),
    email: _mail2,
    name: _md2.display_name || _md2.full_name || _md2.name || _prev.name || (_mail2.split('@')[0] || 'Utilisateur')
  };
  AUTH_TOKEN = session.access_token;
  authSaveSession(session);
  return session;
}

async function authLogout(){
  try { await fetch(`${SUPABASE_URL}/auth/v1/logout`, { method:'POST', headers:{ 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` } }); } catch(e){}
  authClear();
  location.reload();
}

function addLogoutButton(){
  const nav = document.querySelector('.topnav');
  if (!nav || document.getElementById('authLogoutBtn')) return;
  const s = authLoadSession();
  if (s && s.name) CURRENT_USER = s.name;

  // Bascule de périmètre : mes opérations / tout le portefeuille
  const scopeBtn = document.createElement('button');
  scopeBtn.id = 'scopeToggle'; scopeBtn.className = 'sess-btn';
  const _scopeLabel = () => (APP_SCOPE === 'mine' ? 'Mes opérations' : 'Tout le portefeuille');
  scopeBtn.textContent = _scopeLabel();
  scopeBtn.title = 'Basculer entre vos opérations et tout le portefeuille';
  scopeBtn.addEventListener('click', () => {
    APP_SCOPE = (APP_SCOPE === 'mine') ? 'all' : 'mine';
    try { sessionStorage.setItem('exnihilo_scope', APP_SCOPE); } catch(e){}
    scopeBtn.textContent = _scopeLabel();
    applyScopeRerender();
  });
  nav.appendChild(scopeBtn);

  // Bouton rafraîchir (icône seule)
  const rbtn = document.createElement('button');
  rbtn.id = 'sessRefreshBtn'; rbtn.className = 'sess-btn sess-icon-btn';
  rbtn.title = 'Rafraîchir les données (auto toutes les 30 s)';
  rbtn.setAttribute('aria-label', 'Rafraîchir');
  rbtn.innerHTML = '<span class="sess-refresh-ico">⟳</span>';
  rbtn.addEventListener('click', () => refreshData(false));
  nav.appendChild(rbtn);

  // Chip utilisateur (display name) — tout à droite, menu déconnexion au survol
  let uname = (s && (s.name || s.email)) || 'Utilisateur';
  uname = uname.split(/([ ._\-]+)/).map(w => (w && /[a-zA-ZÀ-ÿ]/.test(w.charAt(0))) ? w.charAt(0).toUpperCase() + w.slice(1) : w).join('');
  const initials = uname.split(/[ ._@-]+/).filter(Boolean).slice(0,2).map(x => x[0].toUpperCase()).join('') || 'U';
  const email = (s && s.email) ? s.email : '';
  const userChip = document.createElement('div');
  userChip.id = 'sessUser'; userChip.className = 'sess-user';
  userChip.innerHTML = `
    <span class="sess-ava">${escapeHtml(initials)}</span>
    <span class="sess-uname">${escapeHtml(uname)}</span>
    <span class="sess-caret">▾</span>
    <div class="sess-menu">
      ${email ? `<div class="sess-menu-email">${escapeHtml(email)}</div>` : ''}
      <button class="sess-menu-logout" id="authLogoutBtn" type="button">Déconnexion</button>
    </div>`;
  nav.appendChild(userChip);
  const lo = userChip.querySelector('#authLogoutBtn');
  if (lo) lo.addEventListener('click', authLogout);

  startSessionLoops();
}

// ============== SESSIONS : rafraîchissement live + présence ==============
let _sessClientId = 'c' + Math.random().toString(36).slice(2) + Date.now().toString(36);
let _sessAutoOn = true;
let _sessLoops = [];

function _two(n){ return String(n).padStart(2,'0'); }
function updateSyncStamp(){
  const d = new Date();
  const rb = document.getElementById('sessRefreshBtn');
  if (rb) rb.title = 'Dernière synchro : ' + _two(d.getHours()) + ':' + _two(d.getMinutes()) + ':' + _two(d.getSeconds()) + ' · cliquer pour rafraîchir';
}

async function refreshData(silent){
  // Ne jamais écraser une saisie en cours
  if (silent && (editMode || (typeof hasUnsavedChanges === 'function' && hasUnsavedChanges()))) return;
  const selCode = (typeof storageGet === 'function') ? storageGet('selectedOp') : null;
  const view = (typeof storageGet === 'function') ? storageGet('activeView') : null;
  const rbtn = document.getElementById('sessRefreshBtn');
  if (!silent && rbtn) { rbtn.classList.add('spinning'); }
  try { await loadFromSupabase({ silent: true }); } catch(e){}
  updateSyncStamp();
  if (!silent && view === 'operations' && selCode && typeof selectOp === 'function') { try { selectOp(selCode); } catch(e){} }
  if (!silent && typeof showToast === 'function') showToast('Données rafraîchies', 'refresh');
  if (!silent && rbtn) setTimeout(()=>rbtn.classList.remove('spinning'), 400);
}

async function presenceHeartbeat(){
  const s = authLoadSession(); if (!s) return;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/sessions?on_conflict=client_id`, {
      method: 'POST',
      headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates,return=minimal' },
      body: JSON.stringify({ client_id: _sessClientId, email: s.email || '', last_seen: new Date().toISOString() })
    });
  } catch(e){}
}

async function refreshPresence(){
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/sessions?select=email,last_seen`, {
      headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${AUTH_TOKEN}` }
    });
    if (!res.ok) return; // table absente -> présence désactivée en silence
    const rows = await res.json();
    const cutoff = Date.now() - 90000;
    const active = rows.filter(r => r.last_seen && new Date(r.last_seen).getTime() > cutoff);
    const emails = [...new Set(active.map(r => r.email).filter(Boolean))];
    const pill = document.getElementById('sessPresence');
    if (pill) {
      pill.style.display = active.length ? 'inline-flex' : 'none';
      const c = pill.querySelector('.sess-count'); if (c) c.textContent = active.length;
      pill.title = active.length + ' session(s) active(s) · ' + (emails.join(', ') || '—');
    }
  } catch(e){}
}

function startSessionLoops(){
  if (_sessLoops.length) return;
  updateSyncStamp();
  _sessLoops.push(setInterval(() => { if (_sessAutoOn) refreshData(true); }, 30000));
}
